-- Israel Today: 이스라엘 언론 보도를 바탕으로 새로 쓴 기사 54건 (승인대기)
-- Supabase SQL 에디터에서 실행 (seed-israel-today.sql 다음). 여러 번 실행해도 된다 (같은 제목 기사는 건너뛴다)
--   · 출처: 예루살렘포스트·JNS·와이넷·아루츠 셰바·CBN 기사(RSS로 받은 공개 기사). 번역이 아니라 사실만 골라 새로 썼고, 본문에 출처 매체를 밝혔다
--   · 인용문·숫자는 모두 원문 문장과 대조했다. 기사마다 '확인할 점'과 원문 주소를 AI 메모(편집 메모)에 남겼다
--   · 원문 사진은 저작권 때문에 쓰지 않았다. 대표 사진은 비워 두었다 (편집장이 기사를 고칠 때 사진을 넣는다)
--   · 작성: Israel Today 관리자 계정(없으면 편집장 → 총관리자), 기자명 '관리자', 기자 이메일 없음, 상태 '승인대기'
--   · 섹션: israel 25, bible 10, holyland 8, mission 4, shema 7

with ctx as (
  select o.id as outlet_id, o.name as outlet_name,
         coalesce(
           (select p.id from profiles p where p.outlet_id = o.id and p.role = 'admin' order by p.created_at limit 1),
           (select p.id from profiles p where p.outlet_id = o.id and p.role = 'editor' order by p.created_at limit 1),
           (select p.id from profiles p where (to_jsonb(p) ->> 'is_super') = 'true' order by p.created_at limit 1),
           (select p.id from profiles p where p.role = 'admin' order by p.created_at limit 1)
         ) as author_id
  from outlets o
  where o.name = 'Israel Today'
)
insert into articles (outlet_id, category_id, author_id, title, body, excerpt, thumbnail_url, status, published_at, tags)
select ctx.outlet_id, c.id, ctx.author_id, v.title,
       replace(v.body, '@@BYLINE@@', '[' || ctx.outlet_name || '=관리자 기자]'),
       v.excerpt, null, 'in_review', v.published_at, v.tags
from ctx
cross join (values
  ('israel-security', '흉기 든 부기장 막아선 승객들…플라이두바이 174명 무사 귀환', '<p>@@BYLINE@@&nbsp;9월 30일(수) 두바이에서 텔아비브로 향하던 플라이두바이 FZ1073편에서 오만 국적 부기장이 기장을 흉기로 찌르고 여객기를 추락시키려 한 것으로 의심되는 사건이 일어났다. 현지 매체 와이넷에 따르면 이 비행기에는 어린이 27명을 포함해 승객 174명이 타고 있었다. 여객기는 사우디아라비아 타북 공항에 비상 착륙했고, 승객들은 같은 날 저녁 모두 벤구리온 공항으로 돌아왔다. 이스라엘 보안 당국은 테러 가능성에 점점 무게를 두고 조사하고 있다.</p><p>와이넷이 비행 자료와 승객 증언을 토대로 재구성한 경과에 따르면, 여객기는 오전 6시 5분 두바이를 이륙했다. 오전 8시 21분 갑자기 고도가 떨어지기 시작해 30초도 안 되는 사이 1만4000피트 넘게 급강하했다. 이어 일반 비상 신호(7700)와 항공기 납치를 뜻하는 신호(7500)가 차례로 송신되자 이스라엘 공군은 전투기 2대를 긴급 출격시켰다. 여객기는 오전 9시 45분 타북 공항에 내렸다.</p><p>참사를 막은 데는 이스라엘 승객 네 명의 역할이 컸다고 와이넷은 전했다. 야니브 하윤은 조종실에 들어가 계기를 부수려던 부기장을 제압했다며 “범인을 붙잡아 목을 조르고 밖으로 끌어냈다”고 말했다. 그는 다시 조종실로 들어가 조종간을 당겨 기체를 바로잡는 데 힘을 보탰고, 이후 비번으로 탑승해 있던 조종사 2명이 조종을 넘겨받아 착륙시켰다. 즈비카 마네스와 아사프 라주안 등은 기내에서 나눠 준 헤드폰 선으로 용의자를 묶었다.</p><p>승객 가운데 유일한 의사였던 치과의사 쇼타 무사예프는 머리와 손에서 피를 많이 흘리던 기장을 응급 처치했다. 그는 “그 순간에는 생각하지 않고 그냥 행동하게 된다”며 당시를 돌아봤다. 승객들은 중상을 입은 기장이 쓰러지기 전에 조종실 문을 열어 두어 자신들이 들어갈 수 있었다고 입을 모았다.</p><p>주인공으로 떠오른 인도 국적 스밋 마치하르 기장은 10월 2일(금) 아랍에미리트(UAE)의 병상에서 나렌드라 모디 인도 총리와 영상 통화를 하며 처음으로 입을 열었다. JNS에 따르면 그는 문을 직접 열었다고 확인하며 “나는 살기 위해 싸웠다”고 말했다. 그는 2022년 6월 플라이두바이에 입사했고, 보잉 737 기종으로만 9750시간 넘게 비행한 교관 기장이다.</p><p>이스라엘 카츠 국방장관은 이번 사건을 지하드주의 테러 시도로 규정하고, 이스라엘 승객들의 행동으로 저지됐다고 밝혔다. 베냐민 네타냐후 총리는 미국 CNN 인터뷰에서 인도인 기장과 이스라엘 승객들이 9·11과 같은 참사를 막았다고 평가했다. 반면 플라이두바이는 조종사 사이의 폭력 사건이라고 설명하며 공식 조사가 진행 중인 만큼 원인과 동기에 대한 추측을 삼가 달라고 했다.</p><p>귀국길도 순탄하지 않았다. 사우디 당국이 이스라엘 측 구조기의 입국을 승인하지 않자 일부 승객은 다시 플라이두바이 여객기에 타기를 거부하다가 다른 방법이 없다는 설명을 듣고 탑승했다. 모사드가 승무원 신원 확인을 마친 뒤 여객기가 타북을 떠났다. 벤구리온 공항에서는 이스라엘 응급구조대(MDA)가 승객들을 진찰했고, 상체를 다친 51세 남성이 경상으로 병원에 이송됐다.</p>', '오만 국적 부기장이 기장을 찌르고 여객기를 추락시키려 한 것으로 의심되는 사건이 9월 30일 벌어졌다. 중상을 입고도 조종실 문을 연 인도인 기장과 이스라엘 승객들이 참사를 막았다.', '/sites/israeltoday/covers/israel-security-2.svg', '2026-10-02T07:40:49+00:00'::timestamptz, array['플라이두바이', '항공테러', '벤구리온공항', '이스라엘승객', '사우디아라비아']::text[]),
  ('israel-security', '플라이두바이 용의자 부기장, 급진화 정황…UAE서 조사', '<p>@@BYLINE@@&nbsp;두바이발 텔아비브행 플라이두바이 FZ1073편에서 기장을 흉기로 찌르고 여객기를 추락시키려 한 혐의를 받는 오만 국적 부기장에 대한 조사가 본격화됐다. 예루살렘포스트에 따르면 베냐민 네타냐후 이스라엘 총리는 10월 1일(목) 미국 폭스뉴스 인터뷰에서 이 부기장이 이슬람 급진주의 세뇌를 받았으며 분명히 자살할 의도가 있었다고 말했다. 다만 그는 아직 최종 결론을 내리지는 않았다고 덧붙였다.</p><p>이란 개입 여부에 대해 네타냐후 총리는 판단하기 이르다고 했다. 그는 “공범이 있었는지, 이란이 배후에 있었는지 이 공격범의 뿌리까지 밝혀낼 것”이라고 말했다. 예루살렘포스트가 인용한 이스라엘 보안 당국자 2명은 지금까지 이란의 개입은 확인되지 않았으며, 초기 평가로는 단독 범행일 가능성이 크다고 전했다.</p><p>용의자의 과거를 둘러싼 보도도 이어졌다. 아루츠 셰바(이스라엘내셔널뉴스)는 미국 월스트리트저널을 인용해 이 부기장이 급진화 우려 때문에 오만에서 비행 금지 조치를 받은 적이 있다고 전했다. 네타냐후 총리도 앞서 용의자의 배경에서 이슬람주의 성향과 급진화 흔적이 발견됐다며 이것이 상당한 단서라고 말한 바 있다.</p><p>용의자는 사우디아라비아 타북 공항에서 사우디 당국에 구금됐다가 10월 1일 아랍에미리트(UAE)로 이송됐다. 예루살렘포스트는 수사 상황을 아는 소식통을 인용해 이스라엘 당국자들이 UAE에서 그를 신문할 예정이라고 보도했다. 한 이스라엘 정부 관계자는 이스라엘 수사관들이 UAE 주도 수사에 참여해 용의자의 동기와 배경을 살필 것이라고 말했다. UAE 검찰총장은 테러 활동이나 사전 계획, 배후 지시가 있었는지 조사하라고 지시했다.</p><p>오만 국적자가 어떻게 이스라엘행 항공편에 배정됐는지도 논란이다. 이스라엘은 오만과 공식 외교 관계가 없다. 교통부 소식통은 앞서 플라이두바이가 이스라엘 노선에 이스라엘과 관계를 정상화한 나라 국적 조종사만 배정하기로 돼 있었다며 “명백한 협정 위반”이라고 주장했다. 미리 레게브 교통부 장관도 9월 30일(수) 플라이두바이의 이스라엘 운항 중단을 요청했다.</p><p>그러나 예루살렘포스트가 10월 2일(금) 단독 보도한 바에 따르면, 수사 사정을 아는 소식통들은 용의자에게 “다른 국적은 없다”고 밝히면서도 이스라엘과 UAE의 양자 항공협정에는 조종사 국적을 제한하는 조항이 없다고 전했다. 신문은 별도의 운항·보안 약정에 추가 조건이 있었는지는 이번 설명만으로 확인되지 않는다고 짚었다.</p><p>플라이두바이의 가이스 알 가이스 최고경영자(CEO)는 10월 2일 처음으로 입장을 내고 조종실에서 일어난 안전 사고에 대해 당국이 공식 조사를 진행하고 있다며 사실이 밝혀질 때까지 기다려 달라고 했다. 네타냐후 총리는 같은 날 영상 성명에서 누가 연루됐든 무거운 대가를 치를 것이라고 경고했다. 이번 사건은 10월 27일 총선을 앞두고 이스라엘 사회의 안보 불안을 키우고 있다.</p>', '네타냐후 총리는 오만 국적 부기장이 이슬람 급진주의 세뇌를 받았다고 밝혔다. 오만에서 급진화 우려로 비행이 금지된 적이 있다는 보도도 나왔지만, 범행 동기는 아직 확인되지 않았다.', '/sites/israeltoday/covers/israel-security-3.svg', '2026-10-02T23:35:13+03:00'::timestamptz, array['플라이두바이', '항공테러', '오만', '아랍에미리트', '네타냐후']::text[]),
  ('israel-politics', '플라이두바이 사건 뒤 이스라엘·UAE, 협력 강조 속 온도 차', '<p>@@BYLINE@@&nbsp;9월 30일 두바이발 텔아비브행 플라이두바이 여객기에서 벌어진 조종실 공격 사건 이후 이스라엘과 아랍에미리트(UAE)의 관계에 관심이 쏠리고 있다. 요시 셸리 주UAE 이스라엘 대사는 10월 2일(금) 예루살렘포스트와의 인터뷰에서 이번 사건이 두 나라의 전략적 관계를 약화시키지 않았으며, 오히려 아브라함 협정으로 맺어진 유대가 얼마나 단단한지 보여 줬다고 주장했다.</p><p>셸리 대사는 사건 이후 UAE 당국자와 시민들로부터 따뜻한 반응을 받았다고 전했다. 그는 항공편 문제로 새벽 1시쯤 UAE의 한 고위 기업인에게 전화했더니 1시 10분에 회신이 왔다는 일화를 소개했다. 또 이스라엘 항공사들의 UAE 운항 재개 결정을 근거로 들며 “이것은 일시적인 합의가 아니다”라고 강조했다. 다만 그는 조종사를 배정할 때 국적과 배경을 따져 보는 등 승무원 검증 수준을 높여야 한다고 제안했다.</p><p>정상 간 소통도 이어졌다. 와이넷에 따르면 베냐민 네타냐후 총리는 사건 당일 저녁 무함마드 빈 자이드 알 나하얀 UAE 대통령과 통화했다. 네타냐후 총리는 승객 야니브 하윤을 만난 자리에서 두 정상이 보안 문제 전반을 정리하기로 했다고 밝혔다. 같은 날 신베트(이스라엘 국내 정보기관)는 수사가 진행되는 동안 이스라엘 항공사들이 임차 항공기로 며칠간 UAE 노선을 운항하도록 임시 승인했다.</p><p>UAE 정부도 사건을 강하게 규탄했다. 예루살렘포스트에 따르면 안와르 가르가시 UAE 대통령 외교 고문은 10월 2일 엑스(X)에 올린 글에서 이번 사건을 위험한 테러 행위로 규정하고, 조종실 문을 열어 승객들이 개입할 수 있게 한 인도인 스밋 마치하르 기장을 진정한 영웅이라고 칭송했다. 그는 음모론 확산은 경계해야 한다고 덧붙였다.</p><p>그러나 온도 차도 드러났다. 예루살렘포스트가 전한 UAE 측 소식통은 이스라엘이 UAE발 항공편을 ‘구조 항공편’이라고 부르는 데 불만을 나타내며, 이 표현은 머물기 위험한 나라에나 쓰는 말이라고 지적했다. 이 소식통은 UAE가 이스라엘이 요구한 추가 보안 조치에 모두 동의했고 플라이두바이도 새 절차에 따라 운항하겠다고 했지만 이스라엘이 거부했다고 주장했다.</p><p>와이넷도 UAE 정부와 가까운 소식통을 인용해 이스라엘이 플라이두바이 운항 재개를 늦추며 사건을 정치적으로 이용하고 있다는 비판을 전했다. 이 소식통은 “승객을 아르키아 항공편에 태울 수 있다면 왜 플라이두바이 항공편에는 안 되는가”라고 반문했다. 미리 레게브 교통부 장관은 수사가 끝날 때까지 플라이두바이의 이스라엘 운항을 중단해야 한다는 입장이다.</p><p>이에 대해 이스라엘의 한 고위 당국자는 UAE에서 이스라엘인을 귀국시키는 일을 구조 작전으로 규정한 적이 없으며, 민간 회사들의 표현은 국가와 무관하다고 반박했다. 그는 “UAE에 머무는 이스라엘인들은 발이 묶인 것도 아니고 구조가 필요하지도 않다”고 말했다. 이스라엘 수사관들은 UAE 주도의 수사에 참여해 용의자의 동기와 배경을 조사할 예정이다.</p>', '요시 셸리 주UAE 이스라엘 대사는 플라이두바이 사건이 아브라함 협정의 힘을 보여 줬다고 말했다. 반면 UAE 쪽 소식통들은 이스라엘이 사건을 정치적으로 이용한다고 비판했다.', '/sites/israeltoday/covers/israel-politics-1.svg', '2026-10-02T18:23:38+00:00'::timestamptz, array['아랍에미리트', '아브라함협정', '플라이두바이', '이스라엘외교', '항공보안']::text[]),
  ('israel-local', '두바이에 발 묶인 이스라엘인 귀국 시작…아르키아 첫 귀국편 도착', '<p>@@BYLINE@@&nbsp;9월 30일(수) 두바이발 텔아비브행 플라이두바이 여객기에서 오만 국적 부기장이 기장을 찌른 사건 이후 두 도시를 잇는 하늘길이 사실상 멈추면서, 아랍에미리트(UAE)에 머물던 이스라엘인들의 귀국이 차질을 빚고 있다. 예루살렘포스트에 따르면 두바이와, 두바이를 거쳐 귀국할 예정이던 다른 지역에 발이 묶인 이스라엘인은 1만 명이 넘는 것으로 추산된다.</p><p>이스라엘 항공사 아르키아가 운항한 첫 귀국편은 토요일인 10월 3일 이스라엘에 도착했다. 아루츠 셰바(이스라엘내셔널뉴스)는 아르키아가 주말 동안 귀국편을 한 차례 더 띄우고, 두바이에 남겨진 승객 짐을 실어 오기 위한 별도 항공편도 운항한다고 전했다. 이스라엘 카츠 국방장관도 짐을 가져올 첫 화물기가 토요일 아침 출발한다고 확인했다.</p><p>귀국편 운항은 순탄치 않았다. 예루살렘포스트에 따르면 UAE 당국이 엘알 항공편의 착륙 허가를 취소하면서 첫 귀국편 계획이 어긋났다. 이스라엘 교통부는 이스라엘 항공사들의 두바이발 운항을 10월 2일(금)부터 시작하기로 합의했지만 보안 당국의 준비와 조율이 필요해 출발이 늦어질 것이라고 밝혔다. 이스라에어는 같은 날 UAE 당국의 최종 승인을 받았다고 발표했다.</p><p>교통부는 현재 두바이에 있는 국민들에게 “항공권을 예약한 항공사와 계속 연락하며 그 안내와 공지를 따라야 한다”고 당부했다. 엘알은 공식 허가가 나오는 대로 계획한 귀국편을 운항하겠다고 밝혔다.</p><p>앞서 플라이두바이는 사건 당일 두바이–텔아비브 노선 운항을 모두 일시 중단했다. 이스라엘 국내 정보기관 신베트가 수사가 진척될 때까지 UAE와 이스라엘 간 항공편을 중단하라고 권고한 데 따른 것이다. 미리 레게브 교통부 장관은 이스라엘과 수교한 나라 조종사만 이스라엘에 착륙할 수 있다며 플라이두바이가 항공 협정을 어겼다고 주장했다. 그는 이스라엘 항공사의 두바이 운항을 즉시 허용해야 한다고도 요구했다.</p><p>승객들을 위한 지원책도 나왔다. 예루살렘포스트에 따르면 이스라엘 여행자보험사 리브라는 플라이두바이 운항 중단으로 피해를 본 고객의 보험 기간을 10월 6일 또는 귀국 시점 가운데 빠른 날까지 무료로 연장한다고 발표했다. 연장은 자동으로 적용돼 고객이 따로 신청할 필요가 없다.</p><p>한편 와이넷은 사건이 테러 시도였을 수 있다는 평가가 나오면서 이스라엘 승객들이 국적 항공사를 더 찾을 수 있다고 분석했다. 사건 당일 텔아비브증권거래소에서 엘알 주가는 약 7%, 이스라에어 주가는 9% 넘게 올랐다고 이 매체는 전했다.</p>', '플라이두바이 사건 여파로 두바이–텔아비브 노선이 멈추면서 1만 명 넘는 이스라엘인이 귀국길이 막힌 것으로 추산된다. 이스라엘 항공사들이 귀국편 운항에 나섰고 여행자보험 연장 조치도 나왔다.', '/sites/israeltoday/covers/israel-local-2.svg', '2026-10-03T05:55:34+00:00'::timestamptz, array['플라이두바이', '두바이', '아르키아', '귀국항공편', '여행자보험']::text[]),
  ('israel-politics', '대법원, 카시프 의원·아랍계 정당 총선 출마 허용', '<p>@@BYLINE@@&nbsp;이스라엘 대법원은 10월 2일(금) 오페르 카시프 의원과 아랍계 정당인 라암(통합아랍리스트), 연합리스트가 제26대 크네세트(이스라엘 의회) 선거에 출마할 수 있다고 판결했다. 예루살렘포스트에 따르면 이번 판결로 이들의 출마 자격을 박탈한 중앙선거관리위원회의 결정은 효력을 잃었다.</p><p>대법원은 하루 전인 10월 1일(목) 네 건의 사건을 함께 심리했다. 카시프 의원과 사미 아부 셰하데 후보 개인의 자격 박탈을 승인해 달라는 요청 두 건, 그리고 정당 명부 전체의 자격을 박탈한 선관위 결정에 맞서 라암과 연합리스트가 낸 항소 두 건이다.</p><p>선관위는 카시프 의원이 유대적·민주적 국가로서 이스라엘의 존재를 부정하고 적국이나 테러 조직의 무장 투쟁을 지지했다는 이유로 자격 박탈을 의결했다. 그러나 대법원은 7대 2로 이를 승인하지 않았다. 재판부 전원은 카시프 의원의 발언과 행동을 “혐오스럽다”고 비판하면서도, 다수 의견은 그의 언행이 판례가 세운 엄격한 기준을 충족하지 못했고 자격 박탈에 필요한 증거의 임계점에 이르지 못했다고 판단했다.</p><p>반대 의견을 낸 다비드 민츠 대법관과 알렉스 스타인 대법관은 카시프 의원의 언행이 국가에 대한 무장 투쟁 지지에 해당해 출마를 막을 근거가 충분하다고 봤다.</p><p>라암과 연합리스트의 항소는 대법관 전원 일치로 받아들여졌다. 재판부는 선관위에 제출된 자료와 증거가 정당 명부 전체의 선거 참여를 막는 데 필요한 좁고 엄격한 판례 기준을 충족하지 못한다고 판단했다.</p><p>한편 발라드 대표인 아부 셰하데 후보는 같은 날 연합리스트 후보직을 내려놓겠다고 발표했고, 그에 대한 심리는 종결됐다. 심리 과정에서 대법관들은 그의 발언이 “고통스럽고 터무니없으며 역겹다”는 데 이견이 없다고 밝혔고, 선관위의 자격 박탈 결정을 유지하는 쪽으로 결론이 모이고 있음을 내비쳤다.</p><p>예루살렘포스트는 그의 사퇴가 아랍 사회와 연합리스트 활동가들 사이에서 적잖은 놀라움을 불렀다고 전했다. 이들은 절차가 이미 상당히 진행된 만큼 법원의 이유 있는 판결을 끝까지 받아 냈어야 했다고 본 것으로 알려졌다.</p>', '이스라엘 대법원이 중앙선거관리위원회의 자격 박탈 결정을 뒤집고 오페르 카시프 의원과 라암, 연합리스트의 제26대 크네세트 선거 출마를 허용했다. 사미 아부 셰하데 후보는 심리 도중 출마를 철회했다.', '/sites/israeltoday/covers/israel-politics-3.svg', '2026-10-02T14:11:26+00:00'::timestamptz, array['이스라엘총선', '크네세트', '대법원', '아랍계정당', '중앙선거관리위원회']::text[]),
  ('israel-politics', '콜롬비아, 2주 뒤 예루살렘 대사관 개설…10번째 국가', '<p>@@BYLINE@@&nbsp;콜롬비아가 2주 뒤 예루살렘에 대사관을 연다고 이스라엘 당국자들이 9월 30일(수) 밝혔다. 현지 매체 와이넷에 따르면 이로써 콜롬비아는 예루살렘에 대사관을 둔 10번째 나라가 된다. 최근 이스라엘 언론 보도에 따르면 현재 예루살렘에 대사관을 운영하는 나라는 9개국이다.</p><p>오마르 불라 콜롬비아 외교장관은 개관식 참석을 위해 처음으로 이스라엘을 방문할 예정이다. 대사관 이전 계획은 올해 초 이미 발표됐지만, 이번에 구체적인 개관 일정이 나왔다고 와이넷은 전했다.</p><p>이번 결정은 아벨라르도 데 라 에스프리에야 대통령 체제에서 빠르게 회복되고 있는 두 나라 관계를 보여 준다. 두 나라 정부는 그의 취임 전인 7월 외교 관계 완전 복원과 대사 교환, 무비자 왕래 재개, 콜롬비아 대사관의 예루살렘 이전에 합의했다. 이스라엘 외교부는 이후 대사관 이전이 콜롬비아 새 정부의 결정이라고 설명했다.</p><p>콜롬비아의 대이스라엘 정책은 전임 정부와 크게 달라졌다. 구스타보 페트로 전 대통령 정부는 2024년 이스라엘과 외교 관계를 끊었다. 두 나라는 데 라 에스프리에야 대통령이 8월 취임한 뒤 공식적으로 국교를 회복했다. 7월 합의와 8월 국교 회복에 이어 대사관 개관 일정까지 나오면서, 단교 이후 관계 정상화가 불과 몇 달 사이에 빠르게 진행된 셈이다.</p><p>기드온 사르 이스라엘 외교장관은 다른 한 나라도 조만간 예루살렘에 대사관을 열 준비를 하고 있다고 밝혔지만, 어느 나라인지는 공개하지 않았다. 와이넷은 이 발표가 더 많은 나라가 예루살렘에 외교 공관을 두도록 설득하는 이스라엘의 노력이 계속되고 있음을 보여 준다고 분석했다.</p><p>예루살렘은 성경에서 다윗 왕이 도읍으로 삼은 이래 유대 민족의 중심이 되어 온 도시다. 이스라엘은 예루살렘을 수도로 여기지만, 이곳에 대사관을 둔 나라는 콜롬비아를 포함해도 10개국에 그친다. 이스라엘 정부는 더 많은 나라가 예루살렘에 공관을 두도록 외교적 노력을 이어 가고 있다.</p>', '콜롬비아 외교장관이 개관식에 맞춰 처음으로 이스라엘을 방문할 예정이다. 기드온 사르 이스라엘 외교장관은 또 다른 나라도 예루살렘 대사관 개설을 준비하고 있다고 밝혔다.', '/sites/israeltoday/covers/israel-politics-1.svg', '2026-09-30T18:15:33+03:00'::timestamptz, array['콜롬비아', '예루살렘', '대사관이전', '이스라엘외교', '기드온사르']::text[]),
  ('israel-security', '예비군 긴급 소집 11월 말까지 연장…상한은 20만 명으로', '<p>@@BYLINE@@&nbsp;이스라엘 정부는 9월 30일(수) 이스라엘군(IDF)이 ‘명령 8호’에 따라 예비군을 긴급 소집할 수 있는 비상 체제를 11월 30일까지 연장하기로 승인했다. 예루살렘포스트에 따르면 소집 상한은 24만 명에서 20만 명으로 줄었다. 각료들은 전화 투표로 이 안건과 함께, 불법 전투원 구금에 관한 특별 조치를 두 달 연장하는 안건도 처리했다.</p><p>소집 규모는 올해 여러 차례 바뀌었다. 3월 24일 ‘포효하는 사자’ 작전과 헤즈볼라를 상대로 한 작전 등이 진행되던 때는 5월 31일까지 최대 40만 명 소집이 승인됐고, 7월 26일에는 9월 30일까지 최대 24만 명으로 조정됐다. 국방부는 20만 명이 동시에 복무한다는 뜻이 아니라 기간 전체에 걸쳐 발부할 수 있는 소집 명령의 최대치라고 설명했다.</p><p>국방부는 위협이 계속되고 여러 전선에서 작전이 이어지고 있다는 점을 연장 이유로 들었다. 평시 법률로는 3년 동안 예비군 복무일이 사병 54일, 지휘관 70일, 장교 84일로 제한돼 있어, 필요한 병력을 오랫동안 유지할 수 없다는 것이다.</p><p>그러나 국방 당국이 작성한 법률 의견서는 형평성 문제를 날카롭게 지적했다. 실제로 복무하는 이들의 부담은 계속 커지는데 국가가 모든 계층에 공평한 징병 의무를 이행하지 않고 있다는 것이다. 의견서는 정부가 “한 손으로는 예비군의 부담을 늘리면서 다른 손으로는 병역 기피자들에게 징병 의무를 집행하지 않고 있다”고 비판했다.</p><p>이 문제의 중심에는 하레디(초정통파 유대인) 징병 문제가 있다. 이스라엘군은 하레디 대상자들에게 소집 명령을 보내고 병역 기피자 단속도 강화했지만 부담의 불균형은 여전하다고 예루살렘포스트는 전했다. 군은 예비군을 늘리는 것으로는 의무 복무 인력을 온전히 활용하는 것을 대신할 수 없다는 입장이다.</p><p>비용도 막대하다. 1월부터 8월까지 명령 8호에 따른 예비군 복무 비용은 267억 셰켈에 이르렀고, 이번 두 달 연장에는 약 66억 셰켈이 더 들 것으로 추산됐다.</p><p>함께 연장된 불법 전투원 구금 특례는 변호인 접견 제한 등 전쟁 중 도입된 조치를 유지하는 내용이다. 법률 의견서는 휴전이 이미 발효됐고 가자지구 테러 조직들이 더 이상 인질을 붙잡고 있지 않은 만큼 반복된 연장이 “사소한 문제가 아니다”라고 지적하면서도, 승인에 법적 장애는 없다고 결론 내렸다.</p>', '이스라엘 정부가 ‘명령 8호’에 따른 예비군 소집 권한과 불법 전투원 구금 특례를 두 달 더 연장했다. 국방부 법률 의견서는 병역 부담의 형평성 문제를 무겁게 지적했다.', '/sites/israeltoday/covers/israel-security-2.svg', '2026-10-02T08:06:33+00:00'::timestamptz, array['이스라엘군', '예비군', '하레디징병', '명령8호', '국방부']::text[]),
  ('israel-security', '이란, 美 압박 속 대응 수단 모색…미국은 중동 해군 증강 검토', '<p>@@BYLINE@@&nbsp;미국과 이란의 핵 협상이 교착 상태에 빠진 가운데 이란이 미국의 압박에 어떻게 대응할지 저울질하고 있다고 이스라엘의 한 고위 국방 당국자가 10월 2일(금) 밝혔다. 예루살렘포스트에 따르면 이 당국자는 “이란은 이번 국면에서 쓸 수 있는 수단을 찾고 있다”며, 이란이 이스라엘 선거에 영향을 주는 방안도 논의하고 있을 것으로 보는 것이 합리적이라고 말했다.</p><p>이 당국자는 최근 정체가 밝혀지지 않은 사건이 많았고, 그 가운데 일부는 이란만이 아니라 여러 방향에서 이스라엘 후방을 겨냥한 공격으로 번질 수 있었다고 전했다. 경계 태세를 높였다 낮추기를 반복한 밤이 많았다는 것이다. 그는 이란이 이스라엘과 충돌할 경우 헤즈볼라도 이란의 계산에 분명히 들어간다고 덧붙였다.</p><p>이스라엘 국방 당국은 이란의 경제 사정이 나빠지고 있으며 미국 제재의 효과가 뚜렷하다고 평가했다. 이스라엘군 자료에 따르면 호르무즈 해협을 지나는 유조선은 하루 평균 30~40척으로 전쟁 이전 수준을 회복했다. 이란 리알화 가치는 최근 1달러당 250만 리알 가까이로 떨어져 최저치를 기록했다. 이번 주 시작된 미국의 해상 봉쇄도 이란을 압박하고 있다고 이 당국자는 설명했다.</p><p>이스라엘 국방 당국은 해상 봉쇄로 이란의 선택지가 크게 좁아졌다고 본다. 이란이 군사 행동으로 봉쇄를 뚫으려 하거나 미국과 합의에 이르지 않는 한 제재로 인한 내부 문제가 깊어질 것이라는 분석이다. 이스라엘군은 이란의 순항미사일이 미국 함정을 타격해 사망자가 나오는 등 사태가 통제 불능으로 번질 가능성에 대비하고 있다. 다만 이 당국자는 이란이 그 대가를 잘 알기 때문에 이스라엘을 공격하지 않고 있다고 말했다.</p><p>한편 예루살렘포스트는 미국 워싱턴포스트를 인용해 미 국방부가 앞으로 몇 주 안에 중동 해군 전력을 수천 명 규모로 늘리는 방안을 계획하고 있다고 전했다. 항공모함 3척과 호위함을 이 지역으로 보내는 계획으로, 추가 전력에는 병력 2만 명과 전투기 최대 150대, 다수의 구축함이 포함된다.</p><p>워싱턴포스트에 따르면 도널드 트럼프 행정부는 8개월째에 접어든 이란 전쟁을 어떻게 끌고 갈지 고심하고 있다. 트럼프 대통령은 11월 중간선거 이후 이란 공습 재개를 검토하고 있으며, 타임지 인터뷰에서 중간선거 뒤 폭격을 늘리는 것이 “가능하다”고 말했다. 현재 중동에는 미군 약 5만 명이 배치돼 있으며, 이번 전쟁으로 미군 800명 넘게 다치고 최소 19명이 숨졌다고 이 신문은 전했다.</p>', '핵 협상이 멈춘 가운데 이란이 미국과 이스라엘을 상대로 선택지를 검토하고 있다고 이스라엘 고위 국방 당국자가 밝혔다. 미 국방부는 중동 해군 전력 증강을 계획 중이라는 보도도 나왔다.', '/sites/israeltoday/covers/israel-security-3.svg', '2026-10-02T21:52:50+00:00'::timestamptz, array['이란', '미국', '호르무즈해협', '이스라엘군', '트럼프']::text[]),
  ('israel-security', '사우디, 후티 공세 준비…홍해 바브엘만데브 해협 탈환 노려', '<p>@@BYLINE@@&nbsp;사우디아라비아가 이란의 지원을 받는 예멘 후티 반군을 상대로 대규모 공세를 계획하고 있다고 예루살렘포스트가 로이터통신을 인용해 보도했다. 준비 상황을 아는 6명의 소식통에 따르면 작전은 앞으로 몇 주 안에 시작될 것으로 보이며, 사우디가 관할하는 예멘 지상군이 앞장서고 사우디 공군이 공습으로 지원하는 형태가 될 전망이다.</p><p>공세의 핵심 목표는 후티 반군이 지난달 해안을 따라 남하해 장악한 바브엘만데브 해협을 되찾는 것이다. 이 해협은 홍해의 남쪽 출구로, 지중해와 아시아를 잇는 주요 해상 항로다. 이란 전쟁으로 호르무즈 해협이 사실상 막히면서 올해 그 중요성이 더욱 커졌다. 서방 외교관들과 걸프 지역 당국자는 후티가 이 해협을 쥐고 있는 한 사우디가 새로운 평화 협상에 나설 수 없다고 판단했다고 전했다.</p><p>사우디는 바브엘만데브 주변에 집중한 제한적 공격과, 바이다·마리브·타이즈·자우프 등 여러 전선을 동시에 공략하는 전면 공세를 놓고 검토하고 있다. 규모에 따라 예멘군 10만 명 이상이 동원될 수 있다고 소식통들은 밝혔다. 다만 공세 시점에 대해서는 1주일 안부터 11월 초 미국 중간선거 이후까지 전망이 엇갈렸다.</p><p>사우디는 2015년 아랍 연합군을 이끌고 예멘 내전에 개입했다. 2022년 합의된 휴전은 대체로 유지됐지만, 올해 이란 전쟁의 여파로 후티가 사우디의 선박과 석유 시설에 미사일과 드론 공격을 가하면서 깨졌다. 후티 반군은 지난 3년 동안 이스라엘이 레바논의 헤즈볼라를 약화시킨 뒤 중동에서 이란의 가장 강력한 동맹 세력으로 떠올랐다.</p><p>외부 지원도 이어지고 있다. 서방 외교관에 따르면 미국은 표적 정보를 포함한 정보와 군사 고문을 제공하고 있지만, 트럼프 대통령은 공습 같은 직접 군사 지원 요청은 거절한 것으로 알려졌다. 지난달 사우디와 공동 방위 협정을 맺은 파키스탄은 방공 체계와 드론 등을 실은 수송기 4대를 아덴으로 보냈고, 사우디 영토 방어를 위해 병력 3만~4만 명을 배치했다고 파키스탄 당국자가 밝혔다.</p><p>전망은 엇갈린다. 마이클 래트니 전 주사우디 미국 대사는 공세가 2015년 작전보다 훨씬 제한적일 것으로 내다보며 “이상적으로는 해안 지역을 되찾고 해상 교통을 정상화하는 상당히 제한적인 작전이 될 것”이라고 말했다. 사우디 정부 입장에 가까운 정치 분석가 알리 시하비는 “성공은 현지 병력이 얼마나 잘 싸우느냐에 크게 달려 있다”고 했다.</p>', '사우디아라비아가 이란의 지원을 받는 예멘 후티 반군을 상대로 지상 공세를 준비하고 있다고 로이터통신이 보도했다. 예멘군 10만 명 이상이 동원될 수 있다는 관측이 나온다.', '/sites/israeltoday/covers/israel-security-1.svg', '2026-10-02T19:33:55+00:00'::timestamptz, array['사우디아라비아', '후티반군', '예멘', '홍해', '바브엘만데브']::text[]),
  ('israel-politics', '‘중동의 스위스’ 오만은 이스라엘과 어떤 관계인가', '<p>@@BYLINE@@&nbsp;텔아비브행 플라이두바이 여객기를 추락시키려 한 혐의를 받는 부기장이 오만 국적자로 알려지면서 이 나라에 새삼 관심이 쏠리고 있다. 예루살렘포스트는 해설 기사에서 ‘중동의 스위스’로 불리는 오만이 오랫동안 서방과 이란 사이에서 균형을 잡아 왔다고 소개했다. 다만 오만 정부는 아직 이번 사건에 공식 입장을 내지 않았고, 조종사의 신원이나 국적도 공개적으로 확인하지 않았다.</p><p>오만은 아라비아반도 남동쪽 끝에 자리해 사우디아라비아, 아랍에미리트, 예멘과 국경을 맞대고 있다. 세계 석유 공급량의 약 5분의 1이 지나는 호르무즈 해협을 끼고 있어 전략적 가치가 크다. 인구는 약 550만 명이며, 시민 상당수가 수니파나 시아파와 구별되는 이바디파 이슬람에 속한다. 2020년 1월 즉위한 하이삼 빈 타리크 술탄이 다스리는 술탄국이다.</p><p>오만은 미국과 이란 사이의 핵심 중재국 역할을 해 왔다. 그러나 중재가 올해 초 미국·이란 전쟁을 막지 못하자, 2월 시작된 미국과 이스라엘의 공동 군사 작전을 두고 국제법 규칙에 어긋난다고 비판했다. 미군 기지 3곳이 있는 오만은 이란의 공격을 받은 뒤에도 중립을 버리지 않았다.</p><p>미국과의 관계도 껄끄러워졌다. 오만 외교장관은 영국 이코노미스트 기고에서 이번 전쟁을 불법이라고 규정했다. 트럼프 대통령은 8월 기자들에게 “그들이 아주 잘 처신했다고 생각하지 않지만, 다른 나라들처럼 아주 쉽게 처리할 수 있을 것”이라고 말하며 오만을 폭격할 수 있다고 위협했다.</p><p>이스라엘과의 관계는 복잡하다. 두 나라는 한때 통상 관계를 유지했지만 이스라엘·팔레스타인 갈등이 악화하면서 2000년 단절됐다. 이후에도 물밑 접촉은 이어졌고, 베냐민 네타냐후 총리는 2018년 오만을 방문해 술탄과 만났다. 이스라엘 총리와 오만 술탄의 공개 회동은 드문 일이었다. 두 나라는 수교를 논의하기도 했지만 아직 결실을 보지 못했다.</p><p>오만은 2020년 이스라엘과 아랍에미리트, 바레인의 관계를 정상화한 아브라함 협정에 지지를 표명한 적이 있다. 그러나 예루살렘포스트에 따르면 2023년 10월 7일 이후 오만의 대이스라엘 발언은 거칠어졌고 관계도 냉각됐다. 오만 당국자들은 가자지구에서 이스라엘이 벌인 작전과 이란과의 전쟁을 강하게 비판해 왔으며, 오만의 대무프티는 이스라엘의 이란 공격을 미국과 시온주의자의 배신적 침략이라고 표현했다.</p><p>이번 사건과 관련해 네타냐후 총리는 성명에서 범인이 이슬람주의 급진화를 거쳤으며, 누군가 그를 보냈는지 조사하고 있다고 밝혔다. 그는 배후가 있다면 매우 무거운 대가를 치르게 될 것이라고 경고했다.</p>', '플라이두바이 사건 용의자의 국적이 오만으로 알려지면서 오만이 주목받고 있다. 서방과 이란 사이에서 중립을 지켜 온 오만은 이스라엘과 공식 외교 관계가 없다.', '/sites/israeltoday/covers/israel-politics-2.svg', '2026-10-03T01:49:36+00:00'::timestamptz, array['오만', '중동외교', '아브라함협정', '플라이두바이', '호르무즈해협']::text[]),
  ('israel-society', '10·7 학살 3년…이스라엘 방송, ‘그 이후의 삶’을 비추다', '<p>@@BYLINE@@&nbsp;하마스의 10월 7일 기습 공격 3년을 맞아 이스라엘 방송계가 다큐멘터리, 특별 방송, 인터뷰, 추모 프로젝트를 폭넓게 선보인다. 예루살렘포스트의 방송 칼럼 ‘TV 타임’은 새 프로그램들이 참사 직후 몇 달 동안 만들어진 다큐멘터리와 확연히 다르다고 평가했다. 초기 작품들이 휴대전화 영상과 보안 카메라 기록 등을 서둘러 모아 무슨 일이 있었는지 밝히고 증거를 남기는 데 집중했다면, 이번 작품들은 그날 이후를 살아간다는 것이 무엇을 의미하는지 묻는다는 것이다.</p><p>공영방송 칸(KAN)은 10월 5일 다큐멘터리 ‘교대 근무’를 방송한다. 그날 수백 명의 사상자가 밀려든 브엘세바의 소로카 의료센터 내부를 다룬 작품으로, 처음 공개되는 병원 보안 카메라 영상이 담겼다. 칸 뉴스는 10월 5~7일 앵커 탈리 모레노의 3부작 ‘그들이 돌아온 뒤’도 내보낸다. 인질 석방 운동 대신, 가족이 돌아온 뒤 몸과 마음의 고통 속에서 서로를 다시 알아 가야 하는 가정들을 찾아간다.</p><p>10월 6일에는 전 인질 4명이 모샤브(협동 농촌 마을)에 모여 어떻게 살아남았고 어떻게 희망을 지켰는지, 석방 뒤 삶을 다시 세우는 길고 복잡한 과정을 털어놓는 프로그램도 방송된다. 칸은 가자 접경 지역의 사건을 재구성한 디지털 추모 프로젝트 ‘7.10.360’도 소개한다. 사용자는 오전 6시 29분부터 사건을 따라갈 수 있으며, 현재 약 250개의 개인 이야기가 담겨 있다.</p><p>케이블 채널 HOT 8의 ‘공에 구원받다’는 크파르 아자 키부츠의 축구팀 이야기다. 살아남은 선수들은 피란지에서 며칠 만에 다시 공을 찼고, 축구가 주는 90분 동안 잠시나마 예전의 자신으로 돌아간 듯한 느낌을 얻었다. 그러나 2024년 여름 가자 접경 키부츠 대회를 되살리려 하자 이들은 “모두가 돌아올 때까지” 복귀하지 않겠다며 거절했다.</p><p>같은 채널의 ‘영혼은 묻지 않는다’는 10월 7일 자녀를 잃은 부모 13명이 유족 치유 공동체와 함께 인도 남부를 2주 동안 여행하는 과정을 따라간다. 슬픔에서 잠시 벗어나는 것이 자녀를 버리는 일은 아닌지, 부모들은 고통스러운 질문과 씨름한다.</p><p>전쟁의 짐을 지고 사는 예비군을 다룬 작품도 있다. 예스 독(Yes Docu)의 ‘한쪽 눈을 뜬 채’는 감독 톰 기아트가 ‘철검 작전’에서 400일 넘게 예비군으로 복무하며 동료들이 겪은 위기를 기록한 영화다. 가자지구에서 전차를 몬 예비군이 군 무전망으로 즉흥 팟캐스트를 진행한 이야기를 담은 ‘굿모닝 가자’도 방송된다.</p><p>이 밖에 2025년 10월 석방된 인질 다비드 쿠니오에게 보내는 영화 편지 ‘다비드에게 보내는 편지’ 등 기존 작품들도 다시 공개된다. 칼럼은 이 영화들이 비극 자체와 그에 이르게 된 과정에 대한 이해를 넓히고, 무엇보다 앞으로 무엇을 해야 할지 고민하는 데 도움이 될 것이라고 평가했다.</p>', '이스라엘 방송사들이 하마스 기습 3주기를 맞아 다큐멘터리와 특집을 잇달아 내놓는다. 참사 직후의 기록 중심 작품과 달리, 생존자와 유족, 귀환 인질, 예비군이 삶을 다시 세우는 과정에 초점을 맞췄다.', '/sites/israeltoday/covers/israel-society-3.svg', '2026-10-03T00:08:34+00:00'::timestamptz, array['10월7일', '하마스', '다큐멘터리', '인질', '이스라엘방송']::text[]),
  ('israel-society', '헤르초그 대통령, 다마스쿠스문 폭행 피해 아랍 노인에 위로 전화', '<p>@@BYLINE@@&nbsp;아이작 헤르초그(Isaac Herzog) 이스라엘 대통령이 10월 1일(목) 예루살렘 구시가지 다마스쿠스문(Damascus Gate)에서 폭행을 당해 다친 아랍인 남성 아흐메드 알후세이니(66)와 통화하고 위로와 지지의 뜻을 전했다고 예루살렘포스트가 보도했다. 폭행 사건은 같은 주 초에 일어났다.</p><p>예루살렘포스트에 따르면 헤르초그 대통령은 알후세이니에게 깊은 유감을 표하며 “당신에게 일어난 일을 보고 정말 슬펐고, 이스라엘 국민 전체가 이 사건을 보며 깊이 아파했다고 생각한다”고 말했다. 그는 노인은 물론 그 누구도 이런 일을 당해서는 안 된다고 덧붙였다.</p><p>헤르초그 대통령은 이어 “당신을 향한 폭력을 강력히 규탄한다”며 이 같은 폭력에 맞서 가능한 모든 수단을 동원해야 한다고 강조했다. 또 알후세이니가 빨리 회복해 일상으로 돌아가기를 바란다고 전했다.</p><p>알후세이니는 출근하던 길에 공격을 당했다고 말했다. 그는 현장을 벗어나려 했지만 여러 차례 넘어졌고, 충격이 너무 커서 자신이 어디에 있는지조차 알 수 없을 정도였다고 당시 상황을 전했다.</p><p>같은 날 민주당(The Democrats) 소속 길라드 카리브(Gilad Kariv) 크네세트(국회) 의원도 알후세이니를 찾아갔다. 카리브 의원은 이번 사건을 “인종차별적 극단주의자들의 충격적인 폭력”이라고 규정했다. 그는 다마스쿠스문 검문소에 인력이 배치돼 있었는데도 알후세이니가 이스라엘군(IDF)이나 경찰로부터 아무런 도움을 받지 못해 스스로 서둘러 병원에 가야 했으며, 이 과정에서 갈비뼈 두 대가 부러졌다고 주장했다.</p><p>카리브 의원은 이 같은 무관심과 폭력, 냉혹함은 유대교의 표현이 아니라 이스라엘 사회의 깊은 병을 드러내는 것이며, 거친 정치 문화와 거리에서 벌어지는 일이 깊이 연결돼 있다고 비판했다. 그는 이스라엘인 대다수가 이런 행동을 혐오하지만 침묵하는 다수로 머물러 있고, 이러한 방관이 폭력배들에게 힘을 실어 주고 있다고 지적했다. 카리브 의원은 경찰이 가해자들을 반드시 법의 심판대에 세워야 한다고 촉구했다.</p><p>다마스쿠스문은 예루살렘 구시가지 북쪽의 대표적인 출입문으로, 무슬림 지구로 이어지는 길목이다. 이번 보도에는 가해자의 신원이나 수사 진행 상황은 나오지 않았다.</p>', '아이작 헤르초그 대통령이 예루살렘 다마스쿠스문에서 폭행당한 아랍인 남성과 통화하며 폭력을 강하게 규탄했다. 같은 날 피해자를 찾은 길라드 카리브 의원은 경찰에 가해자 처벌을 촉구했다.', '/sites/israeltoday/covers/israel-society-1.svg', '2026-10-02T13:37:10+00:00'::timestamptz, array['예루살렘', '헤르초그', '다마스쿠스문', '폭력 규탄', '아랍계 주민']::text[]),
  ('israel-local', '예루살렘 회당 화재… 구조 대원들, 토라 두루마리 구출 도와', '<p>@@BYLINE@@&nbsp;최근 예루살렘 메아셰아림(Mea Shearim) 지역 샤아레이 피나(Sha’arei Pina) 거리의 한 회당(시나고그)에서 불이 나, 이스라엘 응급구조 자원봉사 단체 유나이티드 하찰라(United Hatzalah) 대원들이 현장에 출동했다고 예루살렘포스트가 보도했다. 메아셰아림은 초정통파 유대인들이 모여 사는 예루살렘의 대표적인 동네다.</p><p>다행히 이번 화재로 다친 사람은 없었다. 그러나 회당에 보관돼 있던 토라 두루마리 여러 개가 심하게 훼손됐다. 유나이티드 하찰라 대원들은 서둘러 건물 안으로 들어가, 유대인의 삶에서 가장 귀하게 여겨지는 두루마리를 불길 속에서 구해 내는 일을 도왔다.</p><p>예루살렘포스트는 응급 상황이 대개 부상자 수와 부상 정도, 구조 속도처럼 사람을 기준으로 평가된다고 짚었다. 이 단체 대원들이 재난 현장의 동물을 돕기 위해 출동하는 경우는 있지만, 물건을 구하러 나서는 일은 드물다는 것이다. 이번에는 사람이 아니라 유대인 모두가 소중히 여기는 토라 두루마리가 구조 대상이었다.</p><p>화재가 난 시점은 대속죄일(욤 키푸르) 며칠 뒤이자 심하트 토라(Simchat Torah)를 얼마 앞둔 때였다. ‘토라의 기쁨’이라는 뜻의 심하트 토라는 한 해 동안 이어 온 토라(모세오경) 낭독을 마치는 날이다. 유대인들은 마지막 구절을 읽은 뒤 쉴 틈도 없이 곧바로 창세기 첫머리로 돌아가 낭독을 다시 시작한다.</p><p>신문은 이러한 ‘끊이지 않는 이어짐’이 응급구조 현장과도 닮았다고 설명했다. 응급구조사가 시작한 처치를 상급 구급대원이 이어받고, 현장에서 시작된 치료를 병원 의료진이 이어 가듯 한 사람이 멈춘 곳에서 다른 사람이 다시 시작한다는 것이다.</p><p>유나이티드 하찰라의 약 1만 명에 이르는 자원봉사자들은 ‘모든 이스라엘은 서로에게 책임이 있다’는 뜻의 원칙(Kol Yisrael arevim zeh lazeh)을 매일의 삶으로 실천하고 있다고 신문은 전했다.</p><p>예루살렘포스트는 “토라 두루마리는 양피지와 잉크 그 이상”이라며, 두루마리에는 유대 민족의 이야기와 전통, 정체성이 담겨 있고 그 가르침이 여러 세대에 걸쳐 유대인의 삶을 빚어 왔다고 강조했다. 이어 유대인이 무엇보다 사람의 생명을 지키는 데 헌신하듯, 이 단체 역시 거룩한 물건이 위협받을 때 그것을 지킨다고 덧붙였다. 화재 원인은 보도에 나오지 않았다.</p>', '예루살렘 메아셰아림 지역 회당에서 불이 나 토라 두루마리 여러 개가 심하게 훼손됐다. 인명 피해는 없었으며, 응급구조 단체 유나이티드 하찰라 대원들이 건물 안으로 들어가 두루마리 구출을 도왔다.', '/sites/israeltoday/covers/israel-local-2.svg', '2026-10-03T06:06:00+00:00'::timestamptz, array['예루살렘', '토라 두루마리', '회당 화재', '유나이티드 하찰라', '심하트 토라']::text[]),
  ('israel-local', '이스라엘 북부서 경비행기 추락… 1명 사망·1명 부상', '<p>@@BYLINE@@&nbsp;10월 2일(금) 이스라엘 북부 카프르 카라(Kafr Kara) 인근 65번 고속도로 변에 소형 항공기가 추락해 1명이 숨지고 1명이 다쳤다고 이스라엘 소방구조청이 발표했다. 예루살렘포스트가 이를 보도했다. 사고 직후 소방구조청은 구조대가 현장으로 향하고 있다고 알렸고, 이후 소방과 응급의료, 경찰 인력이 잇달아 현장에 투입됐다.</p><p>소방구조청에 따르면 하데라(Hadera) 소방서 소방관들이 현장에 도착했을 때 추락 이후 일어난 불이 인근 주택 쪽으로 번지고 있었다. 소방관들은 진화 작업을 벌여 불길을 잡는 데 성공했다. 주택가로 불이 옮겨붙기 전에 확산을 막은 셈이다.</p><p>이스라엘의 국가 응급의료기관인 마겐 다비드 아돔(MDA)의 응급구조사와 구급대원들은 화상을 입은 34세 남성을 현장에서 처치한 뒤 병원으로 이송했다. 이송 당시 이 남성의 상태는 중등도(moderate)로 전해졌다. MDA는 또 다른 한 명이 기체 안에 갇혀 있다고 알렸다.</p><p>이후 소방구조청은 기체 안에 갇혀 있던 사람이 숨졌다고 발표했다. 숨진 사람의 신원과 나이는 보도에 나오지 않았다.</p><p>사고 항공기는 교육 비행을 하던 중이었던 것으로 나중에 발표됐다. 숨진 사람과 다친 남성이 교관과 교육생이었는지 등 탑승자의 역할은 보도에 나오지 않았다. 구체적인 기종이나 소속, 추락 원인도 아직 밝혀지지 않았다.</p><p>이스라엘 경찰은 사고 직후 65번 고속도로의 차량 통행을 막았다. 사고가 고속도로 바로 옆에서 일어난 만큼, 현장 수습과 진화 작업 동안 일대 교통이 통제됐다.</p><p>카프르 카라는 이스라엘 북부 하데라 북동쪽에 있는 아랍계 도시로, 65번 고속도로는 지중해 연안의 하데라와 이즈르엘 평야의 아풀라를 잇는 주요 간선도로다. 해안 지역과 갈릴리 방면을 오가는 차량이 많이 이용하는 길이다. 마겐 다비드 아돔은 ‘다윗의 붉은 방패’라는 뜻으로, 다른 나라의 적십자사에 해당하는 이스라엘의 응급의료 기관이다.</p>', '교육 비행 중이던 소형 항공기가 카프르 카라 인근 65번 고속도로 변에 추락했다. 34세 남성이 화상을 입고 병원으로 옮겨졌고, 기체 안에 갇혀 있던 한 명은 숨졌다.', '/sites/israeltoday/covers/israel-local-3.svg', '2026-10-02T09:37:17+00:00'::timestamptz, array['경비행기 추락', '카프르 카라', '마겐 다비드 아돔', '이스라엘 소방구조청']::text[]),
  ('israel-economy', '이스라엘 휘발유값 사상 최고… 재무부, 추가 인하 추진', '<p>@@BYLINE@@&nbsp;이스라엘의 휘발유 가격이 10월 1일 0시부터 리터당 52아고로트 올라 사상 최고치인 8.27셰켈을 기록했다고 예루살렘포스트가 보도했다. 갤런당 10.17달러에 해당하는 가격으로, 2012년 9월 세운 종전 최고 기록 8.25셰켈보다 2아고로트 높다(아고로트는 셰켈의 보조 화폐 단위).</p><p>이스라엘 에너지부에 따르면 산정 기간 동안 국제 시장의 휘발유 가격이 약 13% 올랐고, 미국 달러는 약 3% 강세를 보였다. 두 요인은 정부가 규제하는 이스라엘의 유가 산정 공식에 그대로 반영돼 이례적으로 가파른 인상으로 이어졌다. 예루살렘포스트는 원유 가격 상승과 공급망 차질 우려, 세계 에너지 시장의 취약성을 배경으로 꼽았다.</p><p>이번 인상은 정부의 한시적 감세가 아직 유효한 가운데 일어났다. 9월 초 휘발유 가격이 종전 최고 수준으로 돌아가자 베잘렐 스모트리치(Bezalel Smotrich) 재무장관은 휘발유 소비세를 리터당 50아고로트 내려 가격을 7.75셰켈로 낮췄다. 그러나 한 달도 안 돼 국제 유가 상승과 달러 강세가 인하 효과를 모두 지워 버렸다. 이 감세 조치는 10월 31일까지 유지될 예정이며, 연장되지 않으면 11월에 가격이 다시 오를 수 있다.</p><p>현지 방송 N12 뉴스에 따르면 스모트리치 장관은 9월 29일(화) 가격 급등을 막기 위한 추가 보조금을 준비하라고 지시했다. 재무부는 한 달간 리터당 50아고로트를 추가로 인하하는 방안을 추진하고 있다. 승인되면 휘발유 가격은 9월과 거의 같은 약 7.77셰켈로 내려갈 것으로 예상된다.</p><p>재무부는 10월 1일 오전 성명에서 “스모트리치 재무장관은 대중의 의견 검토를 전제로 한 달간 휘발유 리터당 50아고로트 인하에 서명할 계획”이라고 밝혔다. 재무부 법률 고문들은 장관의 추가 인하 서명에 법적 걸림돌이 없다고 판단했으며, 이제 정부 법률고문(법무장관)의 입장을 기다리고 있다.</p><p>절차상 정부 법률고문의 입장이 나온 뒤에야 인하 명령안을 공개해 의견을 받고, 제출된 의견을 검토한 다음 장관이 서명할 수 있다. 예루살렘포스트는 짧은 기간에 두 번째로, 그것도 선거 기간에 이뤄지는 소비세 인하여서 법적으로 특히 민감한 사안이라고 전했다. 9월 인하 역시 예외적 조치로 법적 승인을 거쳤다.</p><p>절차가 끝날 때까지 운전자들은 셀프 주유 95옥탄 휘발유 기준으로 이스라엘 주유소 역사상 가장 비싼 리터당 8.27셰켈을 내야 한다. 직원이 주유해 주는 풀서비스를 이용하면 리터당 26아고로트가 더 붙어 8.53셰켈이 된다.</p>', '셀프 주유 휘발유 가격이 리터당 8.27셰켈로 사상 최고치를 기록했다. 베잘렐 스모트리치 재무장관은 한 달간 리터당 50아고로트를 추가로 내리려 하지만 정부 법률고문의 승인이 필요하다.', '/sites/israeltoday/covers/israel-economy-1.svg', '2026-10-01T12:10:25+00:00'::timestamptz, array['유가', '휘발유', '스모트리치', '이스라엘 경제', '물가']::text[]),
  ('israel-economy', '플라이두바이 회항 사건 후 이스라엘 항공주 9% 가까이 상승', '<p>@@BYLINE@@&nbsp;이스라엘 항공사 이스라에어(Israir)와 엘알(El Al)의 주가가 9월 30일(수) 9% 가까이 올랐다고 예루살렘포스트가 보도했다. 같은 날 두바이를 떠나 텔아비브로 향하던 플라이두바이(flydubai) 여객기가 기내 소동 끝에 사우디아라비아로 회항해 착륙한 사건이 있은 뒤였다.</p><p>예루살렘포스트에 따르면 이스라에어 주가는 1.45셰켈로 출발해 장중 1.58셰켈까지 올랐고, 기사 작성 시점 상승률은 8.8%였다. 엘알 주가는 1.74셰켈에서 1.85셰켈로 7.9% 올랐다.</p><p>이스라에어 주가는 지난 한 달 동안 크게 떨어진 상태였다. 9월 9일 1.60셰켈이던 주가는 9월 29일(화) 1.44셰켈까지 내려갔다가 이날 반등했다. 엘알 주가는 3월부터 8월 사이 큰 폭으로 떨어져 주당 1.2셰켈까지 밀렸지만, 지난 한 달 동안은 꾸준히 올랐다. 텔아비브증권거래소 자료에 따르면 엘알의 기업 가치는 이번 상승으로 약 100억 셰켈로 평가되며, 사상 최고 수준이다. 국영 기업인 플라이두바이는 상장사가 아니어서 주가 측면의 타격은 없었다.</p><p>이스라엘 당국자들은 이번 사건을 조종사 한 명이 납치를 시도해 기내에서 몸싸움이 벌어진 것이라고 밝혔다. 한 이스라엘 당국자는 예루살렘포스트에 “대형 참사를 가까스로 피했다”고 말했다. 이 당국자에 따르면 조종사가 비행기를 지상에 추락시키려 했다는 우려가 커지는 가운데, 다른 승무원들이 탑승한 이스라엘인들의 도움을 받아 해당 조종사를 제압했다.</p><p>플라이두바이 대변인은 조종실에서 벌어진 몸싸움 이후 기내 승무원들이 항공기를 안전하게 확보했다고 확인했다. 그러면서 “이번 사건의 근본적인 이유와 동기는 아직 알려지지 않았으며 공식 조사 대상”이라고 밝혔다.</p><p>이스라엘군(IDF)과 모사드, 신베트(이스라엘 보안국) 등 이스라엘 안보 당국 안에서는 이번 사건이 테러 행위를 의도한 것이었다는 평가가 커지고 있다고 예루살렘포스트는 전했다. 당국자에 따르면 몸싸움이 벌어지는 동안 항공기 고도는 약 4,000미터나 급강하했다.</p>', '이스라엘 당국자들이 조종사의 납치 시도라고 밝힌 플라이두바이 여객기 회항 사건 당일, 이스라에어와 엘알 주가가 큰 폭으로 올랐다. 엘알의 시가총액은 사상 최고 수준을 기록했다.', '/sites/israeltoday/covers/israel-economy-2.svg', '2026-09-30T19:52:35+00:00'::timestamptz, array['항공주', '엘알', '이스라에어', '플라이두바이', '텔아비브증권거래소']::text[]),
  ('israel-economy', '이스라엘 건설 AI 스타트업 빌도츠, 1억3천만 달러 투자 유치', '<p>@@BYLINE@@&nbsp;이스라엘 인공지능(AI) 스타트업 빌도츠(Buildots)가 9월 14일(월) 1억3천만 달러 규모의 투자 유치를 마쳤다고 발표했다고 예루살렘포스트가 보도했다. 이번 투자로 2018년 창업 이후 누적 투자액은 약 2억9,700만 달러가 됐다. 회사는 새 자금을 기술 개발과 인력 채용, 마케팅, 해외 사업 확장에 쓸 계획이다.</p><p>이번 투자는 이스라엘 벤처캐피털 O.G. 벤처 파트너스(O.G. Venture Partners)가 주도했다. 라이트스피드 벤처 파트너스와 인텔 캐피털, 쿰라 캐피털, 포알림 에쿼티, 비올라 그로스 등 투자사와 개인 투자자 아비그도르 빌렌즈(Avigdor Willenz)도 참여했다.</p><p>빌도츠는 건설 현장과 AI를 잇는 시스템을 만든다. 시행사와 원청, 하도급업체 등 공사에 참여하는 모든 주체가 하나의 공유 현황 보고서를 보면서 공정을 확인하고 문제와 지연을 미리 내다볼 수 있게 하는 방식이다. 작업 계획을 입력하면 현장 관리자나 회사 직원이 며칠마다 찍는 현장 영상과 비교하고, 공정표와 3D 모델, 현장 기록을 대조해 수백 가지 공종을 영상만으로 식별한다. 8년간 건설 현장에서 모은 실시간 데이터가 기반이다. 회사는 지연과 조율 문제를 일찍 찾아내 공사 기간을 평균 약 15% 줄일 수 있다고 설명했다.</p><p>고객사로는 인텔과 아즈리엘리 그룹, 아쉬트롬, 티드하르 등 이스라엘 기업과 STO 빌딩 그룹, 모텐슨, 부이그(Bouygues), 호흐티프(HOCHTIEF) 등 해외 건설사가 있다. 미국 시장조사업체 리서치앤드마켓(Research and Markets)에 따르면 세계 부동산 AI 시장은 2026년 중반 약 4,050억 달러 규모이며, 연평균 34~36% 성장해 2030년에는 최대 1조4천억 달러에 이를 전망이다.</p><p>빌도츠는 2018년 로이 다논(Roy Danon) 최고경영자(CEO), 아비브 레이보비치 최고제품책임자(CPO), 야키르 수드리 최고기술책임자(CTO)가 함께 세웠다. 세 사람 모두 이스라엘군(IDF)의 연구개발 지도자 양성 과정인 탈피오트(Talpiot) 출신이다. 직원은 약 400명으로 이 가운데 260명이 이스라엘에서 일하고, 나머지는 미국·캐나다·영국·프랑스·독일·덴마크에 있다. 회사는 약 100명을 추가로 채용하고 있다.</p><p>다논 CEO는 “데이터센터는 규모와 복잡성, 투자 규모 때문에 그런 이탈 하나하나가 막대한 손실을 낳는다”며, 데이터센터 공사에서 풀고 있는 과제가 사무용 건물과 주거용 고층 건물, 학교, 병원 공사에도 똑같이 있다고 말했다. 투자를 주도한 O.G.의 지브 코프(Ziv Kop) 매니징 파트너는 “빌도츠는 과거 모빌아이가 자동차 업계에 했던 일을 건설 산업에서 하고 있다”고 평가했다.</p>', '건설 현장에 인공지능과 컴퓨터 비전을 접목한 빌도츠가 대규모 투자를 유치했다. 회사는 2030년 최대 1조4천억 달러 규모로 커질 것으로 전망되는 세계 부동산 AI 시장을 겨냥하고 있다.', '/sites/israeltoday/covers/israel-economy-3.svg', '2026-09-15T11:08:00+00:00'::timestamptz, array['이스라엘 스타트업', '인공지능', '건설 기술', '투자 유치', '빌도츠']::text[]),
  ('israel-economy', '클랄리트·체크포인트 협력… 이스라엘인 500만 명 의료정보 AI로 보호', '<p>@@BYLINE@@&nbsp;이스라엘의 건강관리기구(HMO) 클랄리트(Clalit)와 세계적인 사이버보안 기업 체크포인트(Check Point)가 9월 28일(월) 협력 관계를 맺었다고 공동성명을 통해 발표했다. 예루살렘포스트에 따르면 이번 협력으로 약 500만 명에 이르는 이스라엘인의 의료 정보가 인공지능(AI) 모델을 활용해 보호받게 된다.</p><p>두 회사는 협력의 목표가 주요 분야에서 클랄리트의 AI 활용을 앞당기는 동시에 클랄리트의 의료 데이터와 디지털 자산, 핵심 기반시설을 지키는 데 있다고 밝혔다. 클랄리트는 일상 업무에 AI를 도입해 업무 과정을 개선하고 대응 시간을 줄이며, AI 에이전트 기반의 진단·연구 도구를 활용할 수 있게 된다고 설명했다. 체크포인트는 조직 전체의 AI 사용과 AI 에이전트를 실시간으로 파악하고 통제하는 기능을 제공한다.</p><p>에이탄 비르트하임(Eytan Wirtheim) 클랄리트 최고경영자는 AI가 의학과 진단, 환자 서비스를 개선할 전에 없던 가능성을 열어 준다며 “우리에게 정보 보안은 혁신의 제약이 아니라 더 빠르고 책임 있게 나아가게 하는 조건”이라고 말했다. 체크포인트의 애덤 일리(Adam Ely) AI 보안 총괄은 사이버보안을 단순한 방어막이 아니라 조직이 첨단 기술을 받아들이게 하는 필수 사업 기반으로 제시하는 회사 전략이 의료 체계의 필요와 맞아떨어졌다고 설명했다.</p><p>아비 아티아(Avi Attia) 클랄리트 최고정보·기술·사이버보안책임자는 이스라엘 기관을 겨냥한 사이버 공격과 사이버 테러 시도가 크게 늘었던 3년간의 전쟁을 겪으며 “이 위협은 비상 시기에만 속한 것이 아니다”라는 점이 분명해졌다고 말했다. 그는 이에 따라 전시에 위협에 대응하는 사고방식에서 벗어나 장기적인 방어 기반을 구축하기로 했다고 덧붙였다.</p><p>클랄리트는 협력 기간에 네 가지 핵심 목표를 이루겠다고 밝혔다. 조직 전반의 안전한 AI 도입, 의료용 AI 게이트웨이 통합, 지속적인 노출 속 사이버 위험 감소, 디지털 업무 공간 보호다.</p><p>아티아 책임자는 클랄리트 정도 규모의 의료 체계라면 다음 위협에 반응하는 데 그쳐서는 안 되고 미리 대비해야 한다며, 이번 협력은 시스템과 의료 데이터를 지킬 상설 역량을 갖추기 위한 것이라고 설명했다. 또 새 기술을 얼마나 빨리 들여오느냐보다 의료진과 환자가 그 기술을 신뢰할 수 있게 도입하는 것이 진짜 시험대라고 강조했다.</p>', '이스라엘 최대 의료기관 클랄리트와 사이버보안 기업 체크포인트가 손잡고 의료 현장의 AI 도입과 의료 데이터 보안을 함께 추진한다.', '/sites/israeltoday/covers/israel-economy-2.svg', '2026-09-28T22:13:20+00:00'::timestamptz, array['클랄리트', '체크포인트', '사이버보안', '의료 AI', '이스라엘 경제']::text[]),
  ('israel-economy', '하파그로이드, ZIM 인수안 개선… 이스라엘 정부에 재검토 요청', '<p>@@BYLINE@@&nbsp;독일 해운사 하파그로이드(Hapag-Lloyd)가 9월 29일(화) 이스라엘 해운사 짐(ZIM Integrated Shipping Services)을 42억 달러에 인수하겠다는 제안의 개선 조건을 검토해 달라고 이스라엘 당국에 촉구했다고 예루살렘포스트가 보도했다.</p><p>이스라엘 재무부는 전날인 9월 28일(월) 이 거래를 승인해서는 안 된다는 입장을 밝혔다. 재무부는 “경제적·운영적·안보적 위험이 이익보다 훨씬 크다”고 주장했다. 이에 대해 하파그로이드는 재무부 입장이 지난주 제시한 상당한 개선 사항을 반영하지 못했다고 반박했다.</p><p>재무부는 하파그로이드의 주주 구성도 문제 삼았다. 재무부에 따르면 카타르가 이 독일 회사의 지분 12.3%를, 사우디아라비아가 10.2%를 갖고 있다. 재무부는 이러한 구조가 “위기 때 정치적 압력과 외국의 영향력과 관련한 실질적인 전략적 위험을 만든다”고 지적했다.</p><p>하파그로이드에 따르면 회사는 이스라엘 사모펀드 피미(FIMI)와 함께 9월 24일 수정 제안의 핵심 내용을 제출했다. 여기에는 극동 지역으로 가는 직항로, 새 회사 짐 이스라엘(ZIM Israel)의 자체 해운 운영, 이스라엘 선원에 대한 투자, 이스라엘의 운송 수요를 위한 추가 안전장치가 담겼다. 관련 거래로 피미는 짐에서 분리한 선박 16척을 짐 이스라엘이라는 새 회사로 인수해 이스라엘의 해상 직항 연결을 확보할 계획이다.</p><p>수정안은 또 이스라엘 정부가 짐에 대해 특별한 소유권을 갖는 ‘황금주(golden share)’ 보호 장치를 강화하는 내용을 담았다. 하파그로이드는 이를 통해 소유권 변동에 대한 이스라엘의 권한과 통제력이 커지고, 외국의 간섭을 막으며, 짐 선단에 대한 이스라엘의 독립성과 통제권이 보장된다고 설명했다.</p><p>하파그로이드는 45일 안에 수정안의 세부 내용을 확정하고, 연내 거래를 마무리하는 데 집중하겠다고 밝혔다. 짐은 이스라엘을 대표하는 해운사로, 처음 인수 제안이 나왔을 때부터 이스라엘 안에서는 거센 반대에 부딪혔다. 최종 승인 여부는 이스라엘 정부의 판단에 달려 있다.</p>', '이스라엘 재무부가 독일 해운사 하파그로이드의 짐(ZIM) 인수에 반대 의견을 내자, 하파그로이드는 직항로 신설과 황금주 강화 등을 담은 개선안을 다시 봐 달라고 촉구했다.', '/sites/israeltoday/covers/israel-economy-3.svg', '2026-09-29T15:51:23+00:00'::timestamptz, array['ZIM', '하파그로이드', '해운', '이스라엘 재무부', '황금주']::text[]),
  ('israel-economy', '에어인디아, 12월부터 텔아비브–델리 직항 재개 예정', '<p>@@BYLINE@@&nbsp;인도 국적 항공사 에어인디아(Air India)가 12월 1일부터 인도의 수도 델리와 이스라엘의 경제 중심지 텔아비브를 잇는 직항편을 주 5회 운항할 계획이라고 이스라엘 방송 N12 뉴스가 보도했다. 예루살렘포스트가 이 소식을 전했다.</p><p>보도에 따르면 에어인디아는 10월 7일 학살 이후 이어진 가자 전쟁 기간 운항 중단과 재개를 되풀이했다. 가장 최근에는 2025년 3월 운항을 재개했지만, 같은 해 5월 예멘 후티 반군이 쏜 탄도미사일이 벤구리온 공항에 떨어진 직후 다시 운항을 멈췄다. 후티 반군은 이란의 지원을 받는 예멘의 무장 세력으로, 가자 전쟁 기간 이스라엘을 향해 미사일과 무인기를 여러 차례 발사했다.</p><p>그 전에도 에어인디아는 2024년 3월 잠시 운항을 재개했다가 4월 중단했고, 5월 다시 재개했다가 8월 또 중단한 바 있다. 전쟁이 이어지는 동안 운항 재개와 중단이 여러 차례 반복되면서, 두 나라를 오가려는 승객들은 일정을 세우기 어려웠다.</p><p>에어인디아는 두 나라 사이를 직항으로 운항하는 유일한 항공사다. 에어인디아가 운항하지 않는 동안 이스라엘과 인도 여행객들은 경유 항공편에 의존해야 했다. 이번 재개로 두 나라 여행객의 선택지가 다시 넓어질 전망이다.</p><p>운항이 재개되면 에어인디아는 벤구리온 공항에 취항하는 외국 장거리 항공사 명단에 이름을 올리게 된다. 현재 이 명단에는 미국 항공사 델타항공과 유나이티드항공이 있다. 델타항공은 9월 7일 뉴욕 JFK–텔아비브 노선 운항을 재개했고, 유나이티드항공은 이틀 뒤 뉴어크–텔아비브 노선을 다시 열었다.</p><p>벤구리온 공항은 텔아비브 인근에 있는 이스라엘의 대표 국제공항으로, 성지순례객 대부분이 드나드는 관문이다. 외국 항공사들의 복귀가 이어지면서 이스라엘을 오가는 하늘길도 조금씩 넓어지고 있다. 다만 보도된 운항 계획은 예정 사항인 만큼, 실제 일정은 항공사 발표를 확인할 필요가 있다.</p>', '에어인디아가 12월 1일부터 델리와 텔아비브를 주 5회 직항으로 잇는다. 전쟁 기간 운항 중단과 재개를 거듭해 온 두 나라 사이 유일한 직항 항공사다.', '/sites/israeltoday/covers/israel-economy-1.svg', '2026-09-28T14:32:55+00:00'::timestamptz, array['에어인디아', '벤구리온 공항', '항공', '인도', '이스라엘 여행']::text[]),
  ('israel-society', '2026 울프상 발표… 이스라엘 수학자 카즈단·베른스타인 공동 수상', '<p>@@BYLINE@@&nbsp;울프재단(Wolf Foundation)이 10월 1일(목) 의학·물리학·화학·수학 분야에서 획기적인 성과를 낸 세계 과학자들을 2026년 울프상 수상자로 발표했다고 예루살렘포스트가 보도했다. 아이작 헤르초그(Isaac Herzog) 대통령과 오스낫 룩센부르크(Osnat Luxenburg) 울프재단 이사회 의장 대행이 예루살렘 대통령 관저에서 수상자 8명을 발표했다.</p><p>수학상은 이스라엘 수학자인 히브리대학교의 데이비드 카즈단(David Kazhdan) 교수와 텔아비브대학교의 요제프 베른스타인(Joseph Bernstein) 교수가 공동으로 받는다. 수상 사유는 “표현론, 보형 형식, 대수기하학에 관한 기초적 연구와 기하학적 표현론을 만드는 데 한 역할”이다.</p><p>의학상은 미국 컬럼비아대학교의 찰스 주커(Charles S. Zuker) 교수에게 돌아갔다. 주커 교수는 사람이 여러 가지 맛을 느끼게 하는 세포를 연구했으며, 실험을 통해 맛의 인식이 혀의 수용체와 연결된 신경 경로를 통해 결정된다는 사실을 밝혀냈다.</p><p>물리학상은 독일 물리학자 이마누엘 블로흐(Immanuel Bloch) 교수와 중국 출신 물리학자 준 예(Jun Ye) 교수가 양자물리학 분야의 업적으로 공동 수상했다. 준 예 교수는 세계에서 가장 안정적이고 정확한 원자시계 개발을 이끌어 전례 없는 정밀도로 시간을 잴 수 있게 했다. 블로흐 교수는 극저온 원자를 복잡한 양자 시스템을 모사하고 연구하는 강력한 도구로 바꾸어, 양자 시뮬레이션을 현대 물리학의 주요 분야로 세우는 데 기여했다.</p><p>이번 보도에는 화학상 수상자에 관한 내용은 나오지 않았다. 발표된 수상자는 모두 8명으로, 보도에 이름이 소개된 수학·의학·물리학 수상자 외의 수상자는 확인되지 않았다.</p><p>울프상은 이스라엘 울프재단이 과학과 예술 분야의 뛰어난 업적에 수여하는 국제적인 상으로, 국제 학계에서 권위 있는 상으로 꼽힌다. 올해 수학상 수상자 두 명은 모두 이스라엘의 대표적인 연구 중심 대학인 히브리대학교와 텔아비브대학교에 소속된 학자들이다.</p>', '울프재단과 헤르초그 대통령이 의학·물리학·화학·수학 분야 수상자 8명을 발표했다. 수학상은 이스라엘 수학자 두 명이 함께 받았다.', '/sites/israeltoday/covers/israel-society-2.svg', '2026-10-03T06:01:00+00:00'::timestamptz, array['울프상', '헤르초그', '과학', '수학', '이스라엘 학계']::text[]),
  ('israel-society', '사랑하는 사람과 함께 먹으면 혈당 덜 오른다…히브리대 연구', '<p>@@BYLINE@@&nbsp;가까운 사람과 함께 식사하면 혼자 먹을 때보다 식후 혈당이 덜 오른다는 이스라엘 연구 결과가 나왔다. 예루살렘포스트에 따르면 예루살렘 히브리대학교(HUJI)와 텔하쇼메르의 셰바 메디컬센터 공동 연구진은 같은 탄수화물 식사를 한 참가자들이 가까운 사람과 함께 있을 때 혈당 상승 폭이 더 작고, 원래 수준으로 돌아오는 속도도 더 빨랐다고 밝혔다.</p><p>연구 결과는 국제 학술지 사이언스 어드밴시스(Science Advances)에 실렸다. 히브리대 쉬르 아칠(Shir Atzil) 교수와 박사과정생 모니아 마살하(Monia Masalha)가 연구를 이끌었고, 셰바 메디컬센터의 샤이 푹스(Shai Fuchs) 박사가 함께했다. 아칠 교수 연구실 학생 6명도 참여해 3년 동안 진행한 프로젝트다. 연구진은 사람의 몸이 사회적 동반자가 곁에 있을 때 스스로를 더 효율적으로 조절한다는 원리를 ‘사회적 생리학’이라고 이름 붙였다.</p><p>실험에서 참가자들은 표준화된 흰 밀빵 102g에 담긴 탄수화물 50g을 먹었고, 연구진은 식후 120분 동안 혈당을 측정했다. 실험은 거실처럼 꾸민 연구실 방에서 진행됐다. 참가자들은 전극을 부착한 상태였지만 꼭 한 식탁에 앉을 필요 없이 자유롭게 지냈다. 아칠 교수는 “신체 접촉이 강력한 지표가 될 것이라고 생각했지만 그렇지 않았다”고 말했다.</p><p>아칠 교수에 따르면 혈당 수치의 평균 변화는 23%였다. 다만 사람마다 효과의 차이가 컸고, 그 원인은 아직 설명하기 어렵다고 그는 덧붙였다. 남녀 간 차이는 없었으며 연구진은 나이와 성별, 체질량지수, 대사 건강, 신체 접촉 정도, 스트레스 수준 등을 통제했다. 효과는 혈당에만 그치지 않았다. 함께 있을 때 추위 속 체온 조절이 나아졌고 성인과 영아 모두 스트레스 반응이 줄었다. 이런 효과는 신체 접촉이 없어도 나타났다.</p><p>아칠 교수는 “혈당 조절은 무엇을 먹느냐만이 아니라 누구와 함께 먹느냐의 문제”라며 인간관계가 신체 건강에 능동적인 생물학적 역할을 한다고 강조했다. 그는 이 현상의 배경으로 뇌를 꼽았다. 스스로 먹을 수 없는 아기는 양육자에게 의존하고, 자라면서 가까운 사람과의 유대 속에서 뇌가 발달해 사회적 상호작용을 통해 몸을 조절하는 법을 배운다는 설명이다.</p><p>연구진은 이번 연구가 예비 단계라고 밝혔다. 다음 단계로는 형제자매와 낯선 사람 사이의 효과를 살펴볼 계획이다. 당뇨병 환자나 당뇨 전단계인 사람은 아직 검사하지 않았지만, 아칠 교수는 이것이 연구가 나아갈 분명한 방향이라고 했다. 혼자 식사하는 노인이나 요양시설 거주자에게도 의미가 있을지에 대해서는 더 연구해야 한다고 답했다. 연구진은 사회적 친밀감이 의료나 영양, 운동을 대신할 수는 없다는 점도 분명히 했다. 이번 연구는 유럽연구위원회(ERC)의 지원을 받았다.</p><p>아칠 교수는 연구의 의미를 “우리 몸은 함께할 때 더 잘 작동한다”는 말로 요약했다. 식탁에서 누구와 마주 앉느냐가 몸에도 영향을 줄 수 있다는 이번 연구는 가정과 공동체가 함께하는 식사 자리의 의미를 새롭게 돌아보게 한다.</p>', '히브리대·셰바 메디컬센터 공동연구팀, 사이언스 어드밴시스에 ‘사회적 생리학’ 발표…연구진은 예비 연구이며 의료·영양·운동을 대신할 수 없다고 강조', '/sites/israeltoday/covers/israel-society-3.svg', '2026-10-03T06:02:00+00:00'::timestamptz, array['히브리대학교', '혈당', '사회적 생리학', '공동체', '건강']::text[]),
  ('israel-local', '헤즈볼라 깃발 사라진 메툴라…최북단 마을에 돌아오는 발걸음', '<p>@@BYLINE@@&nbsp;이스라엘 최북단 마을 메툴라에 주민과 방문객이 다시 돌아오고 있다. 예루살렘포스트 기자는 현장 취재기에서 레바논 국경 너머로 보이던 헤즈볼라 깃발이 사라졌고, 초막절(수콧) 기간에는 관광객과 방문객이 찾아와 식당과 작은 호텔 여러 곳이 문을 열었다고 전했다.</p><p>19세기 후반에 조성된 메툴라의 역사적인 중심가에는 새 벽화가 생겼다. 큰 붉은 숫자로 ‘7.10’이라고 적힌 이 벽화는 10월 7일 학살을 기억하기 위한 것이다. 벽화는 이스라엘 초기의 아름다운 마을 모습에서 2023년 10월 7일의 참상으로 이어지는 마을의 역사를 담았다. 사방에서 날아드는 로켓과 무너진 집, 몸을 피하는 군인들의 모습이 그려져 있다.</p><p>메툴라는 전쟁 내내 헤즈볼라의 공격에 노출됐다. 많은 집이 피해를 입었고 2,000명이 넘는 주민이 피란을 떠났다. 헤즈볼라는 하마스의 기습 당일에는 공격하지 않았지만 10월 8일 전쟁에 가담해 국경 지역에 포격을 가했다. 이스라엘은 대규모 침투를 막지 못할 것을 우려해 메툴라와 키르야트 시모나 등 국경 마을 주민들을 대피시켰다. 예루살렘포스트에 따르면 가자 접경 지역과 북부에서 10만 명 가까운 사람들이 집을 떠나야 했다.</p><p>기자는 전쟁 전의 국경 풍경도 전했다. 2023년 이전에는 국경 너머로 유엔 차량과 함께 헤즈볼라 깃발이 보였고, 건너편 언덕에는 대형 팔레스타인 깃발과 알아크사 모스크를 그린 거대한 광고판이 서 있었다. 기자는 이를 “우리는 여기 있고, 우리가 간다”는 헤즈볼라의 메시지로 읽었다. 그 깃발과 광고판은 이제 모두 사라졌다.</p><p>이스라엘은 2024년 9월 본격적인 반격에 나섰고 헤즈볼라는 큰 손실을 입었다. 2024년 11월에는 휴전이 이뤄졌다. 그러나 올해 3월 이스라엘과 미국의 이란 공습 이후 분쟁이 다시 격화했고, 이스라엘군(IDF)은 레바논 안쪽으로 더 깊이 들어가 여러 마을에서 헤즈볼라를 몰아냈다. 이 과정에서 많은 마을이 파괴됐다고 예루살렘포스트는 전했다. 한때 약 20만 발의 로켓을 보유한 것으로 알려진 헤즈볼라가 2006년 이후 국경에서 누려 온 특권은 사라졌다고 기자는 평가했다.</p><p>다만 기자는 헤즈볼라가 패배했거나 레바논에서 사라진 것은 아니라고 지적했다. 메툴라 인근 북부 갈릴리에서 머문 이틀 밤 동안 레바논 쪽에서 들려오는 것으로 보이는 폭발음을 들었다고 했다. 레바논 정부는 아직 헤즈볼라를 무장 해제하지 못했고, 유엔 병력을 대신할 새 병력이 배치될지, 레바논군이 이 지역을 안정적으로 지킬 수 있을지도 불투명하다고 기자는 덧붙였다.</p><p>지금 메툴라에서 바라본 국경 너머에는 사람의 모습이 거의 보이지 않고, 이스라엘군의 험비와 불도저만 눈에 띈다. 등산로에는 다시 사람들이 오가고 식당도 문을 열었다. 기자는 이를 “더 큰 평화와 고요로 돌아가려는 시도의 시작”이라고 표현했다.</p>', '예루살렘포스트 기자 현장 취재기…초막절 맞아 주민·관광객 복귀 시작됐지만 레바논 쪽 위협은 여전', '/sites/israeltoday/covers/israel-local-1.svg', '2026-10-01T16:58:39+00:00'::timestamptz, array['메툴라', '헤즈볼라', '레바논 국경', '북부 이스라엘', '초막절']::text[]),
  ('israel-opinion', '플라이두바이 피습 사건이 드러낸 ‘새로운 중동’의 가능성과 한계', '<p>@@BYLINE@@&nbsp;두바이를 떠나 텔아비브로 향하던 플라이두바이 FZ1073편에서 조종사가 다른 조종사를 흉기로 찌르고 여객기를 추락시키려 한 사건이 일어났다. 승객과 승무원이 이를 막았고 여객기는 사우디아라비아 타북에 비상착륙했다. 예루살렘포스트는 외교 분석 기사에서 이스라엘인을 태운 아랍에미리트(UAE) 여객기가 사우디에서 도움을 받은 이번 사건이 ‘새로운 중동’의 가능성과 오래된 한계를 함께 보여 줬다고 분석했다.</p><p>현지 매체 와이넷에 따르면 여객기에는 어린이 27명을 포함해 174명이 타고 있었고 대부분 이스라엘인이었다. 사건은 오전 8시 21분께 오만 국적 부기장이 인도 국적 기장을 찌르면서 시작됐다. 이스라엘인 승객 4명이 목숨을 걸고 상황을 장악했고, 찔린 기장은 조종실 문을 여는 것을 도왔으며, 탑승해 있던 외국인 조종사 2명이 기체를 안정시켜 사우디에 착륙시켰다고 와이넷은 전했다.</p><p>와이넷은 상황이 통제되기 전 이스라엘 당국이 최악의 시나리오에 대비했다고 보도했다. 공군은 전투기를 요르단 방향으로 긴급 출격시켰고, 필요하면 9·11식 공격을 막기 위해 여객기를 격추해야 할 수도 있다고 판단했다. 추락이나 인질극에 대비해 공군 특수부대 샬닥과 대테러 부대 야맘도 대기했다. 한 이스라엘 당국자는 “테러범 조종사는 이스라엘에 추락하려 했고 상징이 될 곳을 찾고 있었지만, 도중에 요격됐을 것이기 때문에 성공하지 못했을 것”이라고 말했다.</p><p>이스라엘 카츠 국방장관은 이번 사건을 “지하드 테러 시도”라고 규정했다. 와이넷에 따르면 수사는 모사드가 사우디 정보기관과 접촉하며 이끌고 있다. 부기장이 이란을 위해 움직였을 가능성도 검토되고 있지만 현재로서는 이를 뒷받침할 증거가 없다. 사우디가 이스라엘 항공기의 착륙을 허용하지 않아 승객들을 데려온 구조 항공편도 플라이두바이가 띄웠다.</p><p>예루살렘포스트는 이 사건을 같은 주의 외교 행보와 함께 읽었다. 베냐민 네타냐후 총리는 일요일 아부다비를 비밀리에 방문해 무함마드 빈 자이드(MBZ) UAE 대통령을 만났고, 이란 핵 문제와 홍해 후티 반군 동향에 관한 정보를 공유한 것으로 전해졌다. AP통신은 네타냐후 총리가 MBZ가 10월 7일 이전 하마스의 위협을 경고했다는 하레츠 보도를 부인해 달라고 요청했다고 보도했다. UAE는 회담 사실은 확인했지만 사전 경고 통화는 부인하지 않았다. 이틀 뒤에는 만수르 빈 자이드 UAE 부통령이 리야드에서 무함마드 빈 살만 사우디 왕세자를 만났다. 신문은 세 나라의 폭넓은 조율 가능성을 시사하는 흐름이지만 네타냐후 총리가 이를 중재했다는 근거는 되지 못한다고 선을 그었다.</p><p>신문은 사우디의 태도에서 협력과 한계를 동시에 읽었다. 외교 관계가 없는데도 사우디는 여객기 착륙을 받아들이고 승객들에게 의료 지원을 제공했지만, 이스라엘 항공기를 보내겠다는 요청은 거부했다. 신문은 사우디가 기본적인 인도적 지원과 이스라엘을 향한 ‘눈에 보이는 제스처’ 사이의 경계를 신중하게 지키며, 이스라엘과의 관계를 여전히 ‘뒷방’에 두려 한다고 분석했다. 네타냐후 총리가 사우디 비판 대신 환대를 부각한 데는 선거를 앞둔 정치적 계산도 있었다고 봤다.</p><p>신문은 이스라엘과 UAE의 관계가 10월 7일과 가자·레바논·이란 전쟁을 견뎌 온 만큼 이번 사건으로 흔들리지 않을 것이라고 내다봤다. 또 아브라함 협정이 적대가 사라진 중동을 만들지는 못했지만 “아랍 국가에 착륙할 수밖에 없었던 이스라엘인들이 노골적인 적대 대신 도움을 받을 수 있는 지역”을 만드는 데 기여했다고 평가했다.</p><p>결국 이번 사건은 공식 국교 없이도 위기 때 작동하는 역내 협력의 실체와, 정상화의 문턱을 쉽게 넘지 않으려는 사우디의 신중함을 한꺼번에 드러냈다.</p>', '사우디는 비상착륙한 이스라엘 승객을 도왔지만 이스라엘 항공기 진입은 거부…예루살렘포스트·와이넷 보도로 본 역내 협력의 현주소', '/sites/israeltoday/covers/israel-opinion-2.svg', '2026-10-02T12:48:19+00:00'::timestamptz, array['플라이두바이', '사우디아라비아', '아랍에미리트', '아브라함 협정', '네타냐후']::text[]),
  ('israel-society', '초막절 연휴를 북부 재건에…청소년 수백 명 키르야트 시모나 봉사', '<p>@@BYLINE@@&nbsp;이스라엘 청소년 수백 명이 초막절(수콧) 연휴를 북부 국경 도시 키르야트 시모나를 돕는 데 바쳤다. 예루살렘포스트에 따르면 단체 ‘하쇼메르 하하다쉬’ 산하 청소년운동 단원들은 연휴 기간 도시를 단장하고 주변 자연 명소와 하천을 청소했다.</p><p>청소년들은 일주일 동안 키르야트 시모나의 한 캠핑장에서 지내며 매일 아침 페인트칠과 청소, 잔해와 덤불 제거 작업에 나섰다. 명절의 중간 날들인 ‘홀 하모에드’에는 단체의 리더십 프로그램 참가자들과 군 입대 전 교육과정인 ‘메히노트’ 학생들, 단체 직원과 가족들도 합류했다.</p><p>이들이 힘을 보탠 상부 갈릴리 지역은 이스라엘이 ‘철검 전쟁’이라고 부르는 이번 전쟁 기간 수많은 로켓 공격을 받았다. 주택과 기반시설이 파괴됐고 로켓 포격으로 인한 화재 피해도 컸다. 하쇼메르 하하다쉬는 전쟁이 시작된 뒤 키르야트 시모나와 주변 공동체에서 꾸준히 활동하며 시 당국, 주민들과 관계를 이어 왔다. 단체가 세운 농업학교 네트워크 ‘아담 베아다마’는 전쟁 직후 레바논 국경 인근 키부츠 이르온에 분교를 열어 학생들이 상부 갈릴리 농민들을 돕도록 했고, 역시 레바논 접경인 키부츠 마추바에도 분교를 세웠다.</p><p>설립자이자 최고경영자인 요엘 질버만은 청소년들이 국내외 가족 여행 대신 북부 도시를 돕는 데 연휴를 쓰기로 했다고 전했다. 그는 청소년들이 “방공호 보수와 농민 지원부터 노인 가정 페인트칠, 전쟁 중 로켓에 맞은 현장의 잔해 제거까지 일 년 내내 국가적 사명에 참여한다”며 키르야트 시모나 시와의 협력을 이어 가겠다고 밝혔다.</p><p>아비하이 슈테른 키르야트 시모나 시장은 “하쇼메르 하하다쉬는 언제나 가장 먼저 와서 우리 도시 곳곳에서 봉사해 왔다”고 말했다. 그는 도시를 둘러보다 청소년들이 동네 곳곳에서 일하고 하천까지 청소하는 모습을 보고 감동했다며 이스라엘에는 훌륭하고 영감을 주는 청소년들이 있다고 덧붙였다.</p><p>국경 지역 농민들의 반응도 전해졌다. 키부츠 말키아의 농부 샤이 골라니는 이 단체가 어떤 일이든 늘 먼저 묻고 관심을 갖고 도와준다며 레바논 접경 농민들과 단체가 매일의 협력으로 좋은 관계를 맺고 있다고 말했다. 그는 “하쇼메르 하하다쉬 청소년들은 언제나 우리와 함께 있다”며 이런 지원을 보는 것이 큰 감동이라고 했다.</p><p>초막절은 이스라엘 백성이 광야에서 장막에 거하던 시절을 기억하는 절기로, 오늘날 이스라엘에서는 많은 가정이 여행을 떠나는 연휴이기도 하다. 그 기간을 전쟁의 상처가 남은 이웃 도시를 돌보는 데 쓴 청소년들의 모습은 공동체가 함께 회복을 일궈 가는 북부 이스라엘의 한 단면을 보여 준다.</p>', '‘하쇼메르 하하다쉬’ 청소년운동, 로켓 피해 입은 상부 갈릴리 도시서 페인트칠·잔해 제거·하천 정화', '/sites/israeltoday/covers/israel-society-3.svg', '2026-10-01T15:19:48+00:00'::timestamptz, array['초막절', '키르야트 시모나', '청소년 봉사', '북부 이스라엘', '하쇼메르 하하다쉬']::text[]),
  ('bible-archaeology', '노아의 방주 추정지서 ‘인공 구조물’ 주장…검증은 아직', '<p>@@BYLINE@@&nbsp;노아의 방주 흔적이라는 주장이 이어져 온 튀르키예 두루프나르 지형 아래에 사람이 만든 구조물이 묻혀 있을 수 있다는 주장이 나왔다. 예루살렘포스트에 따르면 탐사 단체 ‘노아의 방주 스캔(NAS)’은 소셜미디어를 통해 이 지형이 지질학적 형성물이 아니며 그 아래에 ‘비범한’ 인공 구조물이 있다는 예비 보고서 내용을 공개했다. 다만 이 결과는 아직 독립적으로 검증되거나 동료 심사를 거치지 않았다.</p><p>이 지형은 한 쿠르드족 목동이 처음 발견했고, 1959년 튀르키예군 일한 두루프나르 대위가 다시 찾아내면서 알려졌다. 독특한 배 모양과 아라랏산과 가까운 위치 때문에 성경의 방주와 연결돼 왔다. 창세기는 홍수 뒤 방주가 아라랏 산에 머물렀다고 기록한다. 1960년대 이후 여러 연구자가 성경과의 연관성을 입증하려 했고, 지형의 길이가 히브리 성경에 묘사된 방주의 크기와 거의 같다는 측정 결과도 있었지만 결정적인 고고학적·과학적 증거는 나오지 않았다.</p><p>반론도 만만치 않다. 미국의 해양 인양 전문가 데이비드 파솔드와 지질학자 로렌스 콜린스는 1990년대 논문에서 “튀르키예 도우베야즈트 인근의 자연 암석 지형이 노아의 방주로 잘못 식별됐다”고 썼다. 이들은 철제 꺾쇠로 여겨진 물체도 현미경 분석 결과 풍화된 화산 광물에서 비롯된 것이라고 밝혔다.</p><p>그러나 2026년 튀르키예 정부는 NAS에 더 본격적인 지질·고고학 발굴을 허가했다. 이번 결과는 엔지니어 코스로 박타르 박사가 개발한 지하 영상 장비 ‘박타르레이더’로 얻은 것이다. NAS에 따르면 조사에서 직선 형태와 각진 교차점, 층 구조, 빈 공간으로 보이는 신호가 감지됐고, 연구진은 이를 지질학적 이상이 아닌 통로와 칸막이, 여러 층의 내부 구조일 가능성으로 해석했다.</p><p>NAS는 나무 같은 유기물이 있는지 확인하기 위해 지형에 구멍을 뚫어 시료를 채취하기 시작했다. 구멍 안으로 로봇을 내려보낸 영상도 공개했는데, NAS는 로봇이 암석이나 기반암에 부딪히지 않았다고 주장했다. 지형의 옆면과 가장자리에서 채취한 흙 시료는 규화목이나 인공물의 흔적이 있는지 실험실에서 분석 중이다.</p><p>박타르 박사는 NAS가 공개한 영상에서 “이것은 내 경력 40년, 45년을 통틀어 가장 중요한 발견”이라고 말했다. 그는 이상 신호들이 같은 원래 물체에서 나온 것이라고 100% 확신한다면서도 “그 원래 물체가 배인지 우주선인지 무엇인지는 모른다”고 했다.</p><p>예루살렘포스트는 증거가 확보돼 독립적으로 평가되기 전까지 두루프나르 지형은 확인된 고고학적 선박도, 입증된 노아의 방주 위치도 아니라고 짚었다. 성경의 방주 이야기를 귀하게 여기는 독자라면 흥미로운 소식이지만, 단체의 주장과 검증된 사실은 구분해 지켜볼 필요가 있다.</p>', '탐사단체 NAS, 튀르키예 두루프나르 지형 레이더 조사 예비 결과 공개…독립 검증·동료 심사 거치지 않아', '/sites/israeltoday/covers/bible-archaeology-1.svg', '2026-10-03T02:29:47+00:00'::timestamptz, array['노아의 방주', '두루프나르', '튀르키예', '성경고고학', '아라랏산']::text[]),
  ('bible-archaeology', '성전산 발치서 대형 정결례장 단지 발굴…순례자들의 정결 의식 흔적', '<p>@@BYLINE@@&nbsp;예루살렘 구시가지 외곽 성전산 발치에서 유대인 순례자들이 성전에 오르기 전 정결 의식을 치르던 곳으로 보이는 대형 정결례장(미크바오트) 단지가 발굴됐다. 예루살렘포스트에 따르면 히브리대학교 고고학연구소의 우지 라이브너 교수와 오리트 펠레그-바르카트 교수가 이끈 발굴팀이 다섯 시즌에 걸친 발굴 끝에 이를 확인했다.</p><p>단지는 오벨 유적에서 약 280㎡에 걸쳐 있으며 큰 중앙 수조와 여러 개의 미크베로 이뤄졌다. 고대 성전산의 주요 출입구였던 ‘삼중문’에서 약 50m 떨어진 자리다. 제2성전 시대 이 문은 성전산 광장 한가운데로 올라가는 지하 계단으로 이어졌다. 히브리대는 1968년부터 오벨을 발굴해 왔으며, 6일 전쟁 직후 벤야민 마자르가 시작한 작업을 손녀 에일라트 마자르가 이었고 그가 세상을 떠난 뒤 현재 발굴팀이 맡았다.</p><p>단지 중앙에서는 사방에서 계단으로 내려가도록 만든 회반죽 수조가 나왔다. 크기는 약 12×9.5m로 1세기 초에 만들어졌다. 북서쪽의 다듬은 돌 건물에는 방 네 개가 있었고 그중 세 곳이 미크베였다. 이 부분은 4세기 후반에 지어진 비잔틴 시대 대형 가옥 아래에 묻혀 있었다.</p><p>모든 미크베 바닥에는 매우 드문 배수 구멍이 있었다. 연구진은 단지에 상시 흐르는 물이 공급됐을 가능성을 보여 주는 단서로 보고 있다. 라이브너 교수는 “일반적인 방식처럼 빗물을 모으는 것이 아니라 흐르는 물”이었을 것이라며, 헤브론 산지에서 성전산으로 물을 끌어오던 수로와 연결됐을 수 있다고 설명했다. 배수 시설은 기드론 골짜기로 이어졌고, 높이가 2m를 넘는 배수로에서는 고대 동전과 토기 조각이 다수 나왔다. 세 미크베 가운데 하나는 둥근 돌 지붕까지 갖춘 채 4.2m 높이 그대로 남아 있었다.</p><p>발굴팀은 이 단지 아래에서 기원전 1세기 것으로 보이는 더 이른 시기의 공공 정결 시설도 찾아냈다. 성전산 바로 옆에서 정결 의식이 오랫동안 이어졌음을 보여 주는 대목이다. 펠레그-바르카트 교수는 제2성전 시대의 기념비적 구조물이 70년 로마에 맞선 제1차 유대 항쟁 때 파괴됐으며 내부에 극적인 파괴의 흔적이 남아 있다고 밝혔다. 이후 이 일대는 수 세기 동안 버려졌다가 비잔틴 시대에 주거지로 다시 쓰였다.</p><p>두 교수는 이번 발견이 “성전을 찾아 예루살렘에 온 수많은 순례자들을 수용하도록 성전산 바로 남쪽 지역이 어떻게 설계됐는지”를 밝히는 연구의 핵심에 닿아 있다고 말했다. 발굴은 암스트롱 성서고고학연구소와 협력해 진행됐다.</p><p>성경은 이스라엘 백성이 절기마다 예루살렘 성전으로 올라갔다고 전하며, 시편에는 ‘성전에 올라가는 노래’가 실려 있다. 복음서 역시 예수와 제자들이 명절에 예루살렘을 찾은 모습을 기록한다. 이번에 드러난 정결례장은 그 순례의 길목에서 사람들이 어떻게 몸과 마음을 준비했는지 짐작하게 한다.</p>', '히브리대 발굴팀, 오벨 유적서 약 280㎡ 규모 미크베 단지 확인…옛 성전 출입구 ‘삼중문’에서 약 50m 거리', '/sites/israeltoday/covers/bible-archaeology-2.svg', '2026-09-24T14:42:58+00:00'::timestamptz, array['오벨', '성전산', '미크베', '제2성전 시대', '성지순례']::text[]),
  ('bible-archaeology', '25톤 제2성전 시대 미크베 통째로 옮겼다…유물청 ‘이사 작전’', '<p>@@BYLINE@@&nbsp;이스라엘 유물청(IAA)이 키르야트 갓의 카르메이 갓 지역 발굴 현장에서 나온 제2성전 시대 미크베(정결례 욕조)를 보존하기 위해 대규모 이전 작업을 벌였다고 예루살렘포스트가 보도했다. 이스라엘 토지청이 비용을 댄 이번 발굴은 신도시 건설에 앞서 2,000년 된 유적이 훼손되지 않도록 미리 진행됐다.</p><p>미크베와 함께 돌로 만든 계량 용기도 출토되면서, 당시 이곳에 유대인 정착지가 있었다는 직접적인 증거가 확보됐다. 유대 율법상 돌그릇은 부정해지지 않는 것으로 여겨져 제2성전 시대 유대인들이 널리 사용했다. 발굴 책임자인 엘레나 코간-자하비, 마얀 마르굴리스, 쉬라 리프시츠는 “이곳에서 발견한 유대인 정착지는 이 지역에서 처음이자 유일하게 알려진 곳”이라며, 유대 저지대와 북부 네게브 사이 경계 지역에서는 지금까지 유대인 정착지가 알려지지 않았다고 설명했다.</p><p>출토 유물로 보아 이 정착지는 2세기 바르 코크바 항쟁 때 유대인 주민들이 떠나면서 버려진 것으로 보인다. 약 500년 뒤 비잔틴 시대에는 전혀 다른 주민들이 이곳에 다시 자리를 잡았다.</p><p>개발 공사가 진행되자 유물청 보존국은 무게 25톤에 이르는 미크베를 국가보물부로 임시 이전하는 과제를 맡았다. 보존국 직원 4명은 2주 동안 쉬지 않고 미크베 전체를 드러냈다. 먼저 사방을 파낸 뒤 구조물 아래를 조심스럽게 뚫고 강철 빔을 밀어 넣어 땅에서 들어 올릴 수 있게 했다. 벽면의 고대 회반죽은 운반 중 진동으로 떨어지지 않도록 거즈와 접착제로 감쌌고, 구조물 전체를 폼으로 보강했다.</p><p>크레인과 미크베 사이 거리 때문에 25톤 구조물을 들어 올리는 데 300톤급 크레인이 동원됐다. 폭이 약 4m에 이르러 특수 광폭 화물차도 필요했다. 인근 베이트 구브린 수장고로 옮기는 동안 도로가 통제됐고 호송 차량이 트럭 앞뒤를 지켰다.</p><p>작업을 이끈 유물청 선임 보존전문가 에얄 카호는 “이런 구조물은 한번 들어 올리면 되돌릴 수 없다”며 모든 세부 사항을 미리 따져야 한다고 말했다. 그는 유물청에서 36년을 일했지만 매번 아드레날린이 다시 솟는다고 했다.</p><p>미크베는 카르메이 갓 공사가 끝나면 원래 자리로 돌아가 새 동네 한가운데 공공 공간의 일부가 된다. 아미하이 엘리야후 문화유산부 장관은 이번 발견이 “제2성전 시대 이스라엘 땅의 유대인 정착을 이해하는 데 중요한 차원”을 더했다고 평가했다. 요한복음의 가나 혼인잔치 장면에도 유대인의 정결 예식을 위한 돌항아리가 등장하는데, 이번 출토품은 그 시대 유대인의 일상을 가까이에서 보여 주는 자료다.</p>', '키르야트 갓 신도시 개발 부지서 나온 정결례 욕조, 보존 위해 임시 이전…공사 끝나면 제자리 공공 공간으로', '/sites/israeltoday/covers/bible-archaeology-3.svg', '2026-09-17T11:15:53+00:00'::timestamptz, array['미크베', '키르야트 갓', '이스라엘 유물청', '제2성전 시대', '정결례']::text[]),
  ('bible-archaeology', '동예루살렘 실완 건물 아래서 제2성전 시대 매장 동굴 발견', '<p>@@BYLINE@@&nbsp;동예루살렘 실완 지역의 한 건물 아래에서 고대 매장 동굴이 발견됐다고 이스라엘 경찰이 발표했다. 예루살렘포스트에 따르면 동굴은 이 지역에서 작전 중이던 국경경찰 대원들이 찾아냈다.</p><p>경찰은 발견 사실을 이스라엘 유물청(IAA)에 알렸고, 유물청은 인력을 보내 현장을 조사했다. 유물청의 예비 조사 결과 이곳의 매장은 기원전 516년~기원후 70년 사이인 제2성전 시대의 것으로 나타났다. 동굴 안에서는 다른 고고학 유물도 함께 나왔다. 경찰과 국경경찰은 유물청과 협력해 현장을 통제하고 있으며, 필요한 연구를 이어 갈 계획이다. 어떤 유물이 나왔는지는 아직 구체적으로 공개되지 않았다.</p><p>이번 발견은 주말 사이 실완에서 두 가문이 충돌해 3명이 숨진 사건을 수사하는 과정에서 이뤄졌다. 경찰에 따르면 1명은 충돌 과정에서 숨졌고, 나머지 2명은 출동한 경찰관들에게 ‘실질적 위협’이 돼 경찰의 총격을 받았다. 경찰은 이 두 사람이 둔기와 흉기, 화염병을 들고 있었다고 밝혔다.</p><p>이타마르 벤그비르 국가안보부 장관은 일부 언론이 밤새 ‘3명 피살’이라고 보도했다며 비판했다. 그는 “그들 중 두 명은 돌과 화염병을 던지다 영웅적인 경찰관들의 총에 맞은 것”이라고 주장했다.</p><p>실완은 예루살렘 구시가지 남쪽 기드론 골짜기 비탈에 자리한 마을로, 그 이름은 성경에 나오는 실로암에서 비롯된 것으로 알려져 있다. 오늘날 주로 아랍계 주민이 거주하는 동네지만, 다윗성 유적과 맞닿아 있어 성경 시대 예루살렘의 흔적이 곳곳에서 발굴돼 온 지역이기도 하다.</p><p>유물청이 제시한 연대의 시작인 기원전 516년은 바벨론 포로에서 돌아온 유대인들이 성전을 다시 세워 봉헌한 시기로, 끝인 기원후 70년은 로마군이 예루살렘 성전을 파괴한 해로 알려져 있다. 예수와 사도들이 활동한 시기도 이 시대에 속한다. 당시 예루살렘 주변에는 바위를 깎아 만든 가족 무덤이 많이 조성됐고, 복음서도 예수의 시신이 바위를 파서 만든 새 무덤에 안치됐다고 전한다. 물론 이번에 발견된 동굴과 성경 속 특정 인물을 연결할 근거는 현재까지 제시되지 않았다.</p><p>이번 동굴이 누구의 무덤인지, 어떤 유물이 함께 묻혔는지는 앞으로 유물청의 조사에서 드러날 전망이다. 유혈 충돌과 치안 문제가 이어지는 동예루살렘에서, 경찰 작전 도중 제2성전 시대 예루살렘 주민들의 흔적이 뜻밖에 모습을 드러낸 셈이다. 실완 일대가 여전히 성경 시대 예루살렘을 이해하는 데 중요한 단서를 품고 있음을 다시 보여 준 발견이다.</p>', '국경경찰, 가문 간 유혈 충돌 수사 중 확인…이스라엘 유물청 예비 조사 결과 기원전 516년~기원후 70년 사이 매장', '/sites/israeltoday/covers/bible-archaeology-1.svg', '2026-08-24T18:20:47+00:00'::timestamptz, array['실완', '동예루살렘', '제2성전 시대', '매장 동굴', '이스라엘 유물청']::text[]),
  ('bible-archaeology', '골리앗의 고향 가드 인근서 2,000년 전 정결례 욕조…세례의 뿌리 조명', '<p>@@BYLINE@@&nbsp;이스라엘 남부에서 2,000년 전 유대인의 정결례 욕조인 미크베가 발굴됐다고 미국 기독교 방송 CBN 뉴스가 보도했다. 발견 장소는 키르야트 갓으로, 골리앗의 고향인 고대 블레셋 도시 가드 유적과 가까운 곳이다. 사무엘상은 소년 다윗이 물맷돌로 쓰러뜨린 블레셋 장수 골리앗을 가드 사람으로 소개한다.</p><p>CBN에 따르면 이번 미크베는 70년 제2성전이 파괴된 뒤에도 이 지역에 남아 있던 유대인 공동체의 존재를 보여 준다. 이 공동체는 로마 하드리아누스 황제 시대에 일어난, 로마 제국에 맞선 마지막 유대인 반란인 바르 코크바 항쟁 때까지 이어졌다. 이스라엘 유물청은 미크베를 보존하기 위해 욕조 전체를 파내 현장에서 옮겼다.</p><p>미크베는 몸 전체를 물에 담가 정결하게 하는 의식을 위한 시설로, 오늘날에도 정통파 유대인 공동체에서 쓰이고 있다. 레위기 등 구약 율법은 여러 경우에 부정해진 사람이 몸을 물로 씻도록 규정한다. CBN은 성경이 레위기에서 다루는 정결과 거룩함을 소개하며, 이번 발견이 기독교 세례의 시작과 연결되는 제2성전 시대의 전통을 떠올리게 한다고 전했다.</p><p>이스라엘 관광 가이드 요아브 로템은 CBN과의 인터뷰에서 “이것이 요한의 세례의 뿌리”라고 말했다. 그는 레위기에서 제2성전 시대 유대교를 거쳐 세례 요한과 예수에 이르는 흐름을 짚으며, 그 뿌리가 지금도 땅속에 남아 있다고 설명했다. 복음서가 전하는 세례 요한의 요단강 세례를 떠올리면, 한국 교회 성도들에게도 의미 있게 다가오는 대목이다.</p><p>로템은 이번 발견이 로마가 유대인을 없애려 한 뒤에도 유대인이 이 땅에서 완전히 사라지지 않았다는 최신 고고학적 증거라고 주장했다. CBN은 일부 반이스라엘 활동가들이 유대인이 1948년에 갑자기 나타나 이 땅을 차지했다고 주장하지만, 로템은 유대인과 이 땅의 분명한 연결 고리가 계속 드러나고 있다고 반박했다고 전했다.</p><p>로템은 히브리어와 아람어, 아랍어로 된 고문서 40만 점을 담은 카이로 게니자 문서 등 역사 기록도 근거로 들었다. 카이로 게니자는 이집트 카이로의 한 회당에 오랫동안 보관돼 온 방대한 유대 문서 더미다. 그는 “유대인들은 70년 이후에도 여전히 살아 있었다”며 일부는 소수로 이 땅에 남았고 많은 유대인이 갈릴리로 옮겨 갔다고 설명했다.</p><p>CBN은 이번 발견을 하나님이 유대 민족에게 주신 땅에서 이어진 거의 4,000년 역사의 또 다른 증거로 평가했다. 이스라엘 땅에서 고고학 발굴이 이어질 때마다 성경과 유대 역사의 접점을 찾으려는 관심도 함께 커지고 있다.</p>', 'CBN 뉴스, 키르야트 갓 미크베 발견 보도…제2성전 파괴 이후에도 남아 있던 유대인 공동체의 흔적', '/sites/israeltoday/covers/bible-archaeology-2.svg', '2026-10-02T00:03:00+00:00'::timestamptz, array['미크베', '키르야트 갓', '세례 요한', '정결례', '성경고고학']::text[]),
  ('bible-archaeology', '튀르키예 유적서 성경 구절 담긴 듯한 초기 기독교 금 부적 출토', '<p>@@BYLINE@@&nbsp;튀르키예 고고학자들이 발굴 현장에서 성경 구절을 담은 것으로 보이는 희귀한 초기 기독교 금 부적과 약 3,500년 전 상형문자가 새겨진 돌 인장을 찾아냈다. 예루살렘포스트는 튀르키예 매체 튀르키예 투데이가 7월 말 이같이 보도했다고 전했다.</p><p>보도에 따르면 빌켄트대학교와 미국 시카고대학교, 빌레지크 셰이흐 에데발리대학교 연구진이 투르크멘 카라회위크 유적의 세 번째 발굴 시즌에 이 유물들을 발견했다.</p><p>기독교 부적은 기원후 4~5세기 것으로 추정되며 작은 구리 용기 안에서 나왔다. 그 안에는 얇은 금판이 들어 있었다. 빌켄트대학교의 미켈레 루즈가르 마사는 “구리 상자 안에서 두께가 0.1㎜에 불과한 매우 얇은 금판을 발견했는데, 성경 구절이 적혀 있을 가능성이 크다”고 말했다. 어떤 구절인지는 보도에 나오지 않았다.</p><p>마사는 이 부적이 어린아이의 것이었을 가능성이 높다고 설명했다. 그는 부적을 튀르키예의 전통 액막이 장식인 ‘나자르 본주우’와 비슷한 것으로 생각할 수 있다고 했다. 나자르 본주우는 파란 유리 구슬에 눈 모양을 넣은 장식으로, 지금도 튀르키예 곳곳에서 흔히 볼 수 있다. 이런 부적은 드물며, 비슷한 유물이 독일에서 발견된 적이 있다고 덧붙였다.</p><p>함께 나온 돌 인장에는 루위어 상형문자가 새겨져 있었다. 고대 근동에서 인장은 문서나 물품에 소유자와 권한을 표시하는 데 쓰였다. 루위어는 청동기와 철기 시대 아나톨리아에서 쓰인 고대 언어로, 루위어 상형문자는 히타이트 시대의 인장과 비문에도 널리 쓰였다. 마사에 따르면 인장에는 사람 이름과 관직명이 함께 적혀 있어, 조직화된 국가 관료 체계에서 하급 직책을 맡았던 인물의 것으로 보인다. 인장에 새겨진 이름은 ‘쿠룬티-지티’로, 히타이트의 사슴 신이자 들판의 수호신인 쿠룬타와 관련이 있다. 이 발견은 투르크멘 카라회위크가 당시 주요 행정 중심지였음을 시사한다. 현장에서는 구리 인장 2점과 다른 이름이 찍힌 점토 인장 자국도 나왔다.</p><p>오늘날 튀르키예 땅인 아나톨리아, 곧 소아시아는 사도 바울이 복음을 전한 선교 무대였고 요한계시록의 일곱 교회가 있던 지역이다. 히타이트는 성경에 나오는 ‘헷 족속’과 관련지어 논의되기도 한다. 성경 구절을 담아 아이에게 지니게 했던 것으로 보이는 이번 부적은, 말씀으로 자녀를 지키려 했던 초기 기독교 시대 부모의 마음과 함께 신앙과 당시 민간 풍습이 어떻게 맞닿아 있었는지 보여 주는 자료로 주목된다. 연구진의 추가 분석을 통해 금판에 적힌 내용이 확인될지 관심이 모인다.</p>', '4~5세기 추정 구리 상자 속 0.1㎜ 금박…약 3,500년 전 루위어 상형문자 인장도 함께 발견', '/sites/israeltoday/covers/bible-archaeology-3.svg', '2026-09-18T09:46:45+00:00'::timestamptz, array['초기 기독교', '튀르키예', '부적', '히타이트', '성경고고학']::text[]),
  ('bible-land', '가장 오래된 평화조약 새 파편 확인…이집트·히타이트 ‘영원한 조약’', '<p>@@BYLINE@@&nbsp;고대 이집트와 히타이트가 맺은 평화조약의 새로운 점토판 조각이 튀르키예에서 확인됐다. 예루살렘포스트에 따르면 튀르키예 문화관광부는 히타이트 제국의 수도였던 하투샤에서 지난해 발견된 쐐기문자 점토판 조각이 이 조약의 일부로 밝혀졌다고 발표했다. 이 발견은 9월 21일 세계 평화의 날에 맞춰 공개됐다.</p><p>메흐메트 누리 에르소이 문화관광부 장관은 엑스(X·옛 트위터)에 “아나톨리아의 흙 속에서 수천 년 된 평화의 흔적을 발견했다”고 썼다. 그는 이번 발견이 평화와 외교의 역사에서 아나톨리아가 차지하는 깊은 자리를 다시 보여 준다고 강조했다.</p><p>조각은 2025년 초룸주 보아즈칼레 지역의 보아즈쾨이·하투샤 유적 발굴 과정에서 나왔다. 히타이트 왕궁이 있던 곳으로 추정되는 자리다. 하투샤는 청동기 시대 히타이트 제국의 수도였다. 연구진은 발견 이후 쐐기문자를 분석해 이 조각이 조약의 아카드어 사본 가운데 하나의 앞면에 해당한다는 결론을 내렸다.</p><p>에르소이 장관에 따르면 새 조각에는 한 나라에서 다른 나라로 도망한 사람들의 처우를 규정한 조항의 일부가 담겨 있다. 읽을 수 있는 부분에는 이집트와 히타이트 땅에서 도망한 사람들에 관한 내용과 함께, 그들의 집이 파괴되지 않도록 보호한다는 문장이 나온다.</p><p>‘영원한 조약’ 또는 ‘은 조약’으로도 불리는 이 조약은 현존하는 가장 오래된 평화조약이다. 히타이트 왕 하투실리 3세와 이집트 파라오 람세스 2세가 기원전 1259년경 수 세기에 걸친 두 나라의 전쟁을 끝내기 위해 맺었다. ‘카데시 조약’으로도 불리지만, 기원전 1274년에 벌어진 카데시 전투는 조약에 언급되지 않는다. 이집트어 본문은 테베의 람세스 2세 장제전(라메세움)과 카르나크 신전 벽에 상형문자로 새겨졌고, 아카드어 점토판 조각들은 1906~1912년 하투샤 초기 발굴 때 나왔다. 조약 사본은 뉴욕 유엔 본부 벽에도 걸려 있다.</p><p>튀르키예는 하투샤에서 나온 점토판 사본을 완성하기 위해 남은 조각들을 찾는 발굴을 이어 갈 계획이다. 앞서 발견된 조각들은 이스탄불 고고학박물관과 아나톨리아 문명박물관, 베를린 고대근동박물관, 상트페테르부르크 에르미타주 박물관 등에 나뉘어 소장돼 있다.</p><p>성경 독자에게도 낯설지 않은 이름들이다. 히타이트는 성경의 ‘헷 족속’과 관련지어 논의되곤 하고, 람세스 2세는 출애굽 시대의 파라오 후보로 자주 거론되지만 학계의 견해는 엇갈린다. 이번 조각은 성경 역사의 배경이 되는 고대 근동에서 강대국들이 어떻게 전쟁을 끝내고 질서를 세우려 했는지 보여 주는 자료다.</p>', '튀르키예 하투샤서 나온 쐐기문자 점토판 조각…나라 사이를 도망한 사람들의 처우와 가옥 보호 조항 담겨', '/sites/israeltoday/covers/bible-land-1.svg', '2026-09-26T22:48:46+00:00'::timestamptz, array['히타이트', '람세스 2세', '평화조약', '튀르키예', '고대 근동']::text[]),
  ('bible-feasts', '심하트 토라, 끝이 아니라 새 시작을 기뻐하는 날', '<p>@@BYLINE@@&nbsp;통곡의 벽과 성지를 담당하는 랍비 슈무엘 라비노비츠는 예루살렘포스트에 실은 심하트 토라 칼럼에서 이 절기의 기쁨이 지나간 성취보다 다가올 배움에 있다고 주장했다. 심하트 토라(토라의 기쁨)는 회당에서 한 해 동안 이어 온 토라(모세오경) 낭독을 마무리하고 새 주기를 시작하는 날이다. 유대인들은 신명기 마지막 단락인 ‘베조트 하브라카’를 읽은 뒤 곧바로 창세기 첫 단락 ‘베레쉬트’를 읽어 끝과 시작 사이에 틈을 두지 않는다.</p><p>라비노비츠는 랍비 야코프 벤 아셰르의 법전 『투르』(오라흐 하임 669항)를 인용해 이 관습을 설명했다. 토라를 마쳤으니 기뻐하는 것이 마땅하고, 곧바로 창세기를 시작하는 것은 ‘이미 다 읽었으니 다시 읽을 생각이 없다’는 고발의 빌미를 주지 않기 위해서라는 것이다. 필자는 다음 안식일까지 기다렸다면 마침이 작별처럼 보였을 것이라며, 끝은 이별이 아니라 새로운 시작을 가능하게 하는 자리라고 풀이했다.</p><p>평소 토라를 거의 펼치지 않는 사람은 무엇을 기뻐해야 하느냐는 질문에 필자는 한 민담으로 답했다. 토라 두루마리를 안고 힘껏 춤추던 시골 사람에게 사람들이 오랫동안 책을 펴지 않았다고 지적하자, 그는 “내 형제가 결혼한다면 함께 축하해야 하지 않겠습니까?”라고 되물었다. 라비노비츠는 심하트 토라의 기쁨이 개인의 기쁨에 그치지 않고, 이스라엘 백성 안에 있는 토라와 그 토라가 유대 민족과 창조주 사이에 맺어 주는 관계에 대한 기쁨이라고 설명했다.</p><p>필자는 이 장면의 교육적 의미도 강조했다. 아버지가 토라를 안고 춤추며 사랑을 표현하는 모습을 본 아이는 어떤 설명보다 강한 메시지, 곧 토라가 의무의 체계만이 아니라 생명과 기쁨으로 가득한 것이라는 메시지를 받는다는 것이다. 아버지가 날마다 공부하는 습관을 갖추지 못했더라도, 아이가 본 그 춤이 여러 해 뒤 토라를 배우려는 마음을 깨울 수 있다고 그는 덧붙였다.</p><p>칼럼은 랍비 이츠하크 후트너가 『파하드 이츠하크』에 남긴 일화도 소개했다. 게르 하시디즘의 첫 레베인 ‘히두셰이 하림’은 심하트 토라에 열정적으로 춤추던 두 제자를 보며 한 사람이 먼저 지칠 것이라고 말했고, 실제로 그렇게 됐다. 레베는 먼저 지친 제자는 과거에 배운 토라로 기뻐했기에 그 기쁨에 한계가 있었고, 끝까지 춤춘 제자는 앞으로 배울 토라로 기뻐했기에 기쁨이 다하지 않았다고 설명했다. 그리고 “진실은 우리가 토라를 새로 시작하기 때문에 기뻐한다는 것”이라고 말했다고 칼럼은 전했다.</p><p>라비노비츠는 그래서 심하트 토라에는 모두가 같은 자리에서 출발한다고 강조했다. 지난 한 해 많이 배운 사람도, 기회를 놓쳤다고 느끼는 사람도 창세기를 다시 펴는 순간 같은 토라와 아직 쓰이지 않은 같은 한 해 앞에 선다는 것이다. 그는 지난해에 얼마나 배웠는지만 물을 것이 아니라 새해에 얼마나 배울 준비가 되어 있는지 물어야 한다고 제안했다.</p><p>말씀을 ‘다 읽었다’는 성취보다 ‘다시 읽겠다’는 결단에 무게를 두는 이 전통은, 해마다 성경 통독을 다짐하고 자녀에게 신앙을 물려주려는 한국 교회 성도와 가정에도 생각할 거리를 던진다.</p>', '통곡의 벽 랍비 슈무엘 라비노비츠는 예루살렘포스트 칼럼에서 토라 낭독을 마치자마자 창세기를 다시 펴는 전통에 담긴 의미를 짚었다.', '/sites/israeltoday/covers/bible-feasts-2.svg', '2026-10-02T11:56:44+00:00'::timestamptz, array['심하트토라', '토라', '유대절기', '신앙교육', '통곡의벽']::text[]),
  ('bible-feasts', '초막과 네 가지 식물이 말하는 이스라엘의 하나 됨', '<p>@@BYLINE@@&nbsp;이스라엘의 초하르(Tzohar) 랍비기구 의장이자 쇼함 시 수석랍비인 필자는 예루살렘포스트에 기고한 초막절 칼럼에서 초막(수카)과 네 가지 식물이라는 두 계명을 통해 이스라엘 사회의 하나 됨을 이야기했다. 필자는 한 계명은 철저히 개인적이고 다른 한 계명은 철저히 공동체적이라는 차이에 주목하며, 이것이 깊은 분열 속에 선거를 앞둔 오늘의 이스라엘에 주는 의미를 풀어냈다.</p><p>네 가지 식물은 룰라브(종려나무 가지), 에트로그(시트론), 하다심(도금양), 아라보트(버드나무)로 초막절 기도와 예식의 중심을 이룬다. 초막은 절기 동안 식사를 하고 날씨가 허락하면 잠도 자는 물리적인 집이고, 네 가지 식물은 영적인 초점 역할을 한다고 필자는 설명했다.</p><p>필자에 따르면 두 계명에는 분명한 율법상 차이가 있다. 토라는 각 사람이 네 가지 식물을 직접 소유하도록 요구하기 때문에, 남의 것을 훔치는 것은 물론 빌려서 계명을 지키는 것도 문제가 된다. 근거는 ‘너희를 위하여 취하라’는 구절의 ‘너희’라는 단어다. 반면 초막은 다른 사람이 지은 것을 써도 계명을 온전히 지킨 것이 된다. ‘이스라엘에서 난 자는 다 초막에 거할지니’라는 구절이 복수형으로 쓰인 데서 주석가들은 “이스라엘 온 백성이 하나의 공동 초막에 앉는 것이 마땅할 것”이라는 가르침을 끌어냈다고 필자는 소개했다.</p><p>현자들은 네 가지 식물을 여러 유형의 사람에 비유했다. 향과 맛이 모두 좋은 에트로그는 다가가기 쉽고 친근한 사람을, 향도 맛도 없는 아라바는 덜 친근한 사람을 뜻한다는 것이다. 필자는 각자 자기 식물을 마련해야 하는 이유를 영성과 신앙이 깊이 개인적인 가치이기 때문이라고 해석했다. 나에게 맞는 것이 이웃이나 가족에게도 맞는다고 여겨서는 안 되며, 유대교는 저마다의 길로 영성에 이르도록 격려한다는 설명이다.</p><p>그러나 군대, 정당, 치안기관, 의료 서비스처럼 함께 세우고 함께 써야 할 공동의 제도도 있으며 이것이 초막의 상징이라고 필자는 강조했다. 집단마다 따로 초막을 짓자는 생각에 대해 그는 “솔직히 말해 그것은 사회적·국가적 재앙으로 가는 처방”이라고 경고했다. 이번 선거는 3년간의 고통스러운 전쟁, 그리고 사법개혁을 둘러싼 극심한 사회적 위기 뒤에 치러진다고 필자는 짚었다.</p><p>필자는 공동의 초막을 짓기 위한 세 가지를 제안했다. 첫째, 가족은 좋을 때나 나쁠 때나 가족이며 모두 한 아버지를 둔 같은 유대인 가족임을 기억하자는 것이다. 둘째, 상대 진영이 나를 무너뜨리려 한다는 두려움을 내려놓자는 것이다. 그는 초하르가 지난해 실시한 조사에서 하레디(초정통파) 응답자 다수가 세속 진영의 징집 확대 요구를 하레디 공동체를 약화시키려는 의도로 보고, 세속 응답자 다수는 세속 학교의 유대학 강화가 자녀에게 종교적 영향을 줄까 우려하는 것으로 나타났다고 소개했다. 셋째, 외부의 위협이 아니라 공동의 가치와 더 나은 미래에 대한 비전 위에서 하나 되자는 것이다.</p><p>필자는 이 길을 찾는다면 하나님의 축복 가운데 마침내 모두가 한 초막 아래 함께 살 기회를 얻게 될 것이라고 글을 맺었다. 각자의 신앙을 지키면서도 한 몸 된 공동체를 이뤄야 하는 과제는, 다양한 배경의 성도가 함께 예배하는 한국 교회에도 낯설지 않은 물음이다.</p>', '초하르 랍비기구 의장은 예루살렘포스트 칼럼에서 개인의 영성은 각자의 몫이지만 공동체는 한 초막 아래 함께 세워야 한다며, 선거를 앞둔 이스라엘 사회에 통합을 호소했다.', '/sites/israeltoday/covers/bible-feasts-3.svg', '2026-09-25T19:56:19+00:00'::timestamptz, array['초막절', '수콧', '네가지식물', '이스라엘선거', '공동체']::text[]),
  ('bible-feasts', '2천 년 전 유대인들은 성전 밖에서 욤키푸르를 어떻게 지켰나', '<p>@@BYLINE@@&nbsp;2천 년 전 대제사장이 지성소에 들어가던 욤키푸르(대속죄일), 이스라엘 땅과 디아스포라의 유대인들은 금식하고 있었다. 그렇다면 그들은 그 밖에 무엇을 했을까. 예루살렘포스트는 이 질문을 붙들고 히브리대학교 탈무드학과 야이르 푸르스텐베르그 교수와 함께 제2성전 시대 성전 밖 유대인들의 대속죄일을 짚어 보는 기획 기사를 실었다.</p><p>성전에서 드린 대속죄일 예식은 레위기 16장과 미쉬나 요마, 탈무드에 자세히 기록돼 있다. 대제사장은 자신과 집안을 위해 수송아지를 속죄제로 드렸고, 똑같은 염소 두 마리를 두고 제비를 뽑아 하나는 여호와께, 하나는 아사셀을 위해 광야로 보냈다. 그러나 욤키푸르는 순례 절기가 아니어서 예루살렘에 올라가야 할 계명은 없었고, 오늘날 익숙한 ‘콜 니드레’ 같은 기도문도 아직 지어지기 전이었다.</p><p>푸르스텐베르그 교수는 성전 밖 풍경을 보여 주는 핵심 자료로 알렉산드리아의 유대 철학자 필론(기원전 20년~기원후 50년)의 저술을 꼽았다. 필론은 『특별법』에서 평소 종교 생활에 무관심한 이들까지 이날의 금식을 진지하게 지켰다고 기록했다. 또 사람들이 아침부터 저녁까지 기도하며 알고 지은 죄와 모르고 지은 죄의 용서를 구했다고 썼다.</p><p>어디서 어떻게 기도했는지는 분명하지 않다. 푸르스텐베르그 교수는 오늘날과 같은 정형화된 기도가 제2성전 시대에는 알려져 있지 않았다고 본다. 그는 “제2성전 시대 자료는 회당을 토라 공부와 연결한다”고 설명했다. 다만 기원전 2세기부터 기원후 68년까지 존재한 쿰란 공동체는 자체적인 고정 기도문을 갖고 있었다. 예루살렘에서 동쪽으로 약 35~40km 떨어진 사해 북서쪽 동굴에서 나온 사해 사본에는 ‘슬픔’과 ‘울음’을 언급하는 욤키푸르 기도가 남아 있어, 이 공동체가 이날을 매우 엄숙하게 이해했음을 보여 준다.</p><p>대속죄일이 늘 슬픔의 날이었던 것은 아니다. 토라는 이날 ‘스스로 괴롭게 하라’(레위기 23장 27절)고 명하지만, 대부분의 자료는 이날을 애도의 날로 보지 않는다고 기사는 전했다. 오히려 미쉬나 타아니트 4장 8절은 아브월 15일과 욤키푸르만큼 이스라엘에게 기쁜 날이 없었다고 기록한다. 탈무드는 이 기쁨을 금송아지 사건 이후 하나님과 이스라엘의 화해를 상징하는 두 번째 돌판과 연결한다. 푸르스텐베르그 교수는 대제사장이 지성소에서 나오기를 기다리던 긴장이 풀린 데서 이런 축제 분위기가 나왔을 수 있다고 덧붙였다.</p><p>기사는 성전 밖의 많은 유대인에게 대속죄일이 오늘날의 회당 중심 예배보다 개인 기도와 성찰의 날이었을 수 있다고 정리했다. 푸르스텐베르그 교수는 그날 예배의 중심은 성전이었고, 그곳에 없는 이들은 결과를 기다려야 했다며 “고대인의 사고방식에서는 이치에 맞는다고 생각한다”고 말했다.</p><p>기사는 바알 셈 토브(1700~1760)에게서 전해 오는 일화로 끝을 맺었다. 기도문을 읽지 못하던 한 사람이 알고 있는 히브리어 글자만 되풀이하며 그 글자로 하나님이 기뻐하실 말을 지어 달라고 기도했다는 이야기다. ‘자비로우신 분은 마음을 원하신다’는 이 교훈은, 레위기 16장의 대제사장 사역을 그리스도의 대속과 연결해 읽는 한국 그리스도인들에게도 기도의 본질을 돌아보게 한다.</p>', '예루살렘포스트는 히브리대 탈무드 학자와 함께 필론의 기록과 사해 사본, 미쉬나를 따라 제2성전 시대 대속죄일의 풍경을 재구성했다.', '/sites/israeltoday/covers/bible-feasts-1.svg', '2026-09-20T10:52:48+00:00'::timestamptz, array['욤키푸르', '대속죄일', '제2성전', '사해사본', '레위기']::text[]),
  ('holyland-jerusalem', '욤키푸르 앞둔 통곡의 벽, 마지막 셀리호트 기도에 15만 명', '<p>@@BYLINE@@&nbsp;대속죄일(욤키푸르)을 앞둔 토요일 밤, 예루살렘 통곡의 벽(코텔)에서 열린 마지막 셀리호트 기도회에 약 15만 명이 모였다고 예루살렘포스트가 보도했다. 셀리호트는 유대력 새해와 대속죄일을 앞두고 드리는 참회 기도로, 이날 모임은 올해 이어진 셀리호트 집회의 마지막 순서였다.</p><p>기도회는 이른 저녁에 시작돼 중심 예식에서 절정을 이뤘다. 참석자들은 통곡의 벽 광장뿐 아니라 주변 발코니와 구시가지 골목까지 가득 메웠다. 인파가 몰리자 주최 측은 광장 외곽과 구시가지 입구인 욥바문 성벽, IDF 광장(키카르 짜할)에 대형 스크린을 설치해 예식을 중계했다.</p><p>예식에는 베냐민 네타냐후 총리와 부인 사라 여사, 다비드 요세프 세파르디 수석랍비, 칼만 메이르 바르 아슈케나지 수석랍비, 슈무엘 라비노비츠 통곡의 벽·성지 담당 랍비, 모셰 리온 예루살렘 시장이 참석했다. 네타냐후 총리는 평화를 위한 기도와 이스라엘군(IDF) 및 보안군의 안전을 위한 기도를 드렸고, 두 수석랍비는 유대 민족의 평화와 단합을 위해 기도했다.</p><p>라비노비츠 랍비는 연설에서 “이번 달은 통곡의 벽이 유대 민족의 고동치는 심장임을 다시 한번 증명했다”고 말했다. 그는 키파를 쓴 사람과 쓰지 않은 사람, 모든 공동체와 견해를 가진 이들이 전국에서 모여 한마음으로 섰다며, 장병들의 승리와 부상자의 회복, 유족의 위로를 위해 함께 기도했다고 밝혔다. 이어 새해가 치유와 위로, 승리와 축복의 해가 되기를 바란다고 덧붙였다.</p><p>이날 기도회에는 하마스에 억류됐다 풀려난 엘리야 코헨과 노바 음악축제 생존자인 그의 아내 지브 아부드, 전 인질 롬 브라슬라브스키, 엘카나 보흐보트, 오하드 벤 아미도 함께했다.</p><p>브라슬라브스키는 이날 밤 X(옛 트위터)에 “하늘에 계신 아버지, 아름다운 우리 조국의 통곡의 벽까지 와서 죄송하다고 말씀드립니다”라는 글을 올렸다. 그는 노바 현장에서 더 많은 일을 하지 못한 것, 억류 중 무너지고 의심했던 순간들을 고백하면서도 가자지구에서 매일 매시간 하나님이 함께하심을 느꼈다고 썼다. 하마스가 이슬람으로 개종시키려 할 때마다 압력에 굴복하지 않았다는 그는 “포로 생활 중에도 아버지는 결코 자녀를 버리지 않는다는 것을 늘 알았다”고 했다. 그는 지난 욤키푸르에는 가자지구 데이르 알발라에 붙잡혀 있었지만 이제는 자유인으로 통곡의 벽에 섰다고 적었다.</p><p>통곡의 벽 유산재단은 별도 성명에서 이번 달에만 200만 명 가까운 사람이 통곡의 벽을 찾았으며, 여기에는 전 인질과 유족, 장병과 보안군이 포함됐다고 밝혔다. 재단은 대속죄일 기도가 금식 기간 내내 통곡의 벽 광장에서 이어지며, 월요일 밤 네일라 기도와 쇼파르(뿔나팔) 소리로 마무리된다고 전했다.</p>', '네타냐후 총리와 두 수석랍비, 가자지구에서 풀려난 전 인질들도 참석했다. 통곡의 벽 유산재단은 한 달 동안 200만 명 가까이 다녀갔다고 밝혔다.', '/sites/israeltoday/covers/holyland-jerusalem-2.svg', '2026-09-20T10:12:55+00:00'::timestamptz, array['통곡의벽', '욤키푸르', '셀리호트', '예루살렘', '전인질']::text[]),
  ('mission-christian-israel', '51개국 기독교 지도자 550여 명, 예루살렘 다윗성서 예배 축제', '<p>@@BYLINE@@&nbsp;국제 기독교 단체 이글스윙스(Eagles’ Wings)가 10월 3일 토요일 밤 예루살렘 구시가지의 다윗성(Tower of David)에서 연례 음악 축제 ‘어웨이크 예루살렘(Awake Jerusalem)’을 연다고 예루살렘포스트가 보도했다. 세계 각국의 기독교 아티스트들이 무대에 서며, 해외 시청자를 위한 생중계도 예정돼 있다.</p><p>이번 축제는 이글스윙스 설립자이자 대표인 로버트 스턴스 감독이 이끄는 열흘 일정 방문의 중심 행사다. 51개국에서 550명이 넘는 기독교 지도자가 이번 방문단에 참여해 이스라엘에 들어왔다. 방문 일정은 초막절 기간에 시작돼 10월 7일 하마스 공격 3주년까지 이어진다.</p><p>주최 측은 이 행사를 단순한 콘서트가 아니라 “성경의 땅에서 하나님을 만나는 자리”라고 소개했다. 방문한 지도자들이 속한 교회와 네트워크는 합쳐서 수천만 명의 그리스도인에게 닿는다. 이글스윙스는 이들이 이스라엘과 그 백성, 그리고 지난 3년간의 경험을 더 깊이 이해하고 돌아가기를 바란다고 밝혔다. 행사는 기독교 방송과 미디어 플랫폼을 통해서도 송출된다.</p><p>참가자 가운데는 필리핀 최대 복음주의 교회 중 하나인 워드오브호프 크리스천 처치의 설립자 겸 담임목사 데이비드 소브레페냐 감독, 코스타리카 하나님의성회 총감독이자 세계 히스패닉 하나님의성회 회장인 리카르도 카스티요 메디나 목사, 브라질의 헤이나우두 두스산투스 목사 등이 있다. 나이지리아에서는 와리 왕국의 오기아메 아투와체 3세 국왕 부부와 크리스토퍼 그와빈 무사 국방장관도 함께했다.</p><p>일정은 축제에만 머물지 않는다. 대표단은 이스라엘 지도자들과 이스라엘군(IDF), 외무부 관계자, 종교 지도자, 귀환 인질과 유족을 만날 예정이다. 이글스윙스는 2023년 10월 이후 이스라엘이 겪어 온 도전을 참가자들이 직접 보고 듣도록 이 만남들을 마련했다고 설명했다. 이스라엘 관계자와 종교 지도자들이 참여하는 전략 브리핑에서는 이스라엘의 안보 과제와 지역 내 위치를 다룬다.</p><p>스턴스 감독은 “우리는 이스라엘 백성에게 우리가 그들 곁에 굳건히 서 있음을 알리려고 이곳에 왔다”고 말했다. 그는 이스라엘과 예루살렘을 위한 기도에 실질적인 행동을 더하고, 이스라엘을 정확히 이해하고 뜨겁게 지지하는 일이 이 시대에 시급하다는 메시지를 각자의 영향권에 전하고자 한다고 밝혔다.</p><p>이글스윙스는 지난 30년 동안 그리스도인들이 신앙의 뿌리를 탐구하고 이스라엘을 직접 경험하도록 방문단을 이끌어 왔다. 올해 방문은 세계 각지에서 순례객이 모이는 초막절과 10월 7일 3주년을 며칠 앞둔 시점이 겹쳐, 참가자들이 이스라엘 사람들을 직접 만나 연대를 표현하는 자리가 될 것이라고 단체는 설명했다.</p>', '이글스윙스가 이끄는 열흘 일정의 방문단은 초막절에 도착해 10·7 공격 3주년까지 이스라엘에 머물며 귀환 인질과 유족 등을 만난다.', '/sites/israeltoday/covers/mission-christian-israel-3.svg', '2026-10-01T14:51:22+00:00'::timestamptz, array['이글스윙스', '어웨이크예루살렘', '다윗성', '초막절', '기독교지도자']::text[]),
  ('mission-christian-israel', '70개국 그리스도인 예루살렘에 모여 초막절 지켜', '<p>@@BYLINE@@&nbsp;국제기독교대사관(ICEJ)이 주최하는 2026년 초막절 축제(Feast of Tabernacles)에 70개국에서 1,800명이 넘는 그리스도인이 예루살렘을 찾았다고 CBN 뉴스가 보도했다. CBN은 3년 가까운 전쟁 끝에 항공사와 관광객이 이스라엘로 돌아오고 있으며, 초막절을 맞아 그리스도인들도 다시 예루살렘을 찾고 있다고 전했다. 같은 매체의 다른 보도는 참가자 수를 2,000명 가까이로 전했다.</p><p>참가자들은 예루살렘에서의 첫날 밤을 영어, 히브리어, 아랍어 예배로 시작했다. ICEJ의 노르웨이 지역 책임자 다그 율리우센은 환영사에서 왕의 왕이신 분을 그분의 도성에서 경배하기 위해 모였다며 “유대 민족에게 여러분은 혼자가 아니라는 강하고 따뜻한 메시지를 전하려 한다”고 말했다. CBN은 지난주 뉴욕에서 유엔 각국 대표단이 베냐민 네타냐후 이스라엘 총리의 연설 도중 퇴장한 것과 대조적인 풍경이 예루살렘에서 펼쳐졌다고 전했다.</p><p>기독교 가수 아론 슈스트는 유대인 실로와 아랍인 니자르를 무대에 소개하며 두 사람이 예수님 덕분에 소중한 친구가 됐다고 말했다. 이어 참가국 대표들이 차례로 무대를 가로지르며 자기 나라 국기를 흔들었다.</p><p>이스라엘 최초의 아랍계 이스라엘인 대(對)기독교 세계 대사인 조지 딕은 “백성은 살아남았고, 이스라엘 국가는 살아 있다”며 방문객들을 환영했다. 그는 2023년 10월 7일을 포함해 이스라엘이 여러 세대에 걸쳐 겪은 시련을 이야기한 뒤, 고국에 돌아가면 이스라엘을 알리고 증오에 맞서 진실의 편에 서 달라고 당부했다.</p><p>ICEJ는 1980년 많은 나라가 예루살렘에서 대사관을 철수하기로 결정한 데 대한 응답으로 그리스도인들이 세운 단체다. ICEJ는 그 뒤로 해마다 초막절 축제를 열어 왔으며, 이를 모든 민족이 예루살렘에 올라와 초막절을 지킬 것이라는 스가랴 14장 말씀이 장차 이뤄질 것을 보여 주는 표징으로 여긴다고 CBN은 설명했다.</p><p>올해 축제 주제는 요엘 3장 16절이다. 위르겐 뷜러 ICEJ 회장은 이 본문을 낭독한 뒤, 지금이 민족들이 이스라엘에 등을 돌리는 요엘 3장의 마지막 때라고 믿는다며 참가자들에게 각자의 나라를 위해 기도하라고 촉구했다. 그는 이 말씀이 하나님의 백성을 대하는 세계 각국을 향한 경고라고 주장했다. 또 참가자들이 각자의 나라를 대표하는 만큼 자기 나라가 이스라엘과 하나님 편에 서도록 부르짖어야 한다고 말했다.</p><p>CBN은 외국 항공사들이 관광객을 태우고 속속 이스라엘로 돌아오는 가운데, 이번 참가자들이 이스라엘 땅의 유대 민족에게 사랑과 지지를 보여 주기 위해 예루살렘을 찾았다고 전했다.</p>', '국제기독교대사관(ICEJ)이 주최한 초막절 축제에 1,800명이 넘는 성도가 참가했다. 올해 주제는 요엘 3장 16절이다.', '/sites/israeltoday/covers/mission-christian-israel-1.svg', '2026-10-02T00:04:00+00:00'::timestamptz, array['초막절', 'ICEJ', '국제기독교대사관', '예루살렘', '요엘']::text[]),
  ('mission-christian-israel', '미국 목사가 교회 잔디밭에 이스라엘 깃발을 꽂는 이유', '<p>@@BYLINE@@&nbsp;미국 일리노이주 레이크 취리크에 있는 쿠엔틴 로드 침례교회의 짐 스커더 주니어 담임목사는 CBN 뉴스에 실은 칼럼에서 그리스도인이 이스라엘을 지지해야 하느냐는 물음에 망설임 없이 그렇다고 답했다. 그는 최근 한 젊은 여성이 왜 그렇게 이스라엘 이야기를 자주 하느냐고 묻자 “내게 가장 중요한 것이 이스라엘에서 왔다”고 답했다고 소개했다.</p><p>필자가 내세운 이유는 단순하다. 구주 예수님이 유대인이고, 성경이 거의 전부 유대인의 손으로 기록됐다는 것이다. 유대인이 없었다면 그리스도인에게 가장 소중한 이 두 가지도 없었다는 설명이다. 필자는 이스라엘이 세계의 일상적인 대화에서 칭송보다 비난을 더 많이 받는 지금이, 자신이 대표하는 쿠엔틴 로드 침례교회와 데이스프링 성경대학·신학교, 인그레이스 미니스트리가 그리스도인들에게 ‘예수님의 가족’ 곁에 서는 일의 중요성을 알릴 기회라고 주장했다.</p><p>그의 교회는 하마스의 이스라엘 공격 3주년을 앞두고 국제기독교유대인친선협회(IFCJ)가 벌이는 ‘펠로십의 깃발(Flags of Fellowship)’ 캠페인의 거점 교회로 나섰다. 교회 잔디밭에 수천 개의 깃발을 세워 공격 당일 숨진 무고한 생명을 공개적으로 기리는 행사다. 필자에 따르면 올해로 3년째인 이 추모 행사는 미국과 세계 3,000곳이 넘는 교회가 참여하는 운동으로 커졌다. 교회마다 내건 1,200개의 깃발은 그날 희생된 1,200명을 기억하는 의미이며, 필자는 기억에는 책임이 따른다고 강조했다.</p><p>필자는 일부 사역자들이 이스라엘 지지를 공개적으로 드러내기를 꺼리지만 자신들은 그 반대라고 밝혔다. 그 근거로 창세기 12장 3절의 축복 약속을 들며, 아브라함과 이삭과 야곱의 하나님이 유대 민족에게 이스라엘 땅을 영원한 고향으로 약속하셨다고 주장했다. 그는 “나는 세상에서 가장 똑똑한 사람은 아닐지 몰라도 하나님께 맞설 만큼 어리석지는 않다”고 썼다.</p><p>필자는 지난 4년 동안 교회가 지역 유대인 공동체와 우정을 쌓아 왔다고 전했다. 최근에는 아내와 함께 푸드 팬트리 ‘허쉬의 냉장고’ 헌정식에 참석했다. 이 이름은 노바 음악축제 인근에서 다친 뒤 억류 중 숨진 이스라엘계 미국인 허쉬 골드버그-폴린을 기리는 것이다. 필자에 따르면 허쉬는 대피소에서 친구 아네르와 함께 날아든 수류탄을 밖으로 던져 여러 사람의 생명을 구했다. 필자는 그의 어머니 레이철의 이야기를 들으며 미국과 세계에서 반유대주의가 커지고 있음을 다시 떠올렸다고 했다.</p><p>필자는 하나님이 이스라엘을 ‘눈동자’(스가랴 2장 8절)로 여기시며, 우리가 이웃 특히 이스라엘을 어떻게 대하는지로 우리를 판단하실 것이라고 믿는다고 밝혔다. 그는 IFCJ 같은 단체가 홀로코스트 생존자와 고아, 노인, 테러와 전쟁 피해자를 돕고 있다고 소개했다.</p><p>칼럼은 그리스도인들에게 구원의 반석(베드로전서 2장 6절)이신 예수님을 전해 준 유대인 친구들에게 보답하라고 권하며 세 가지를 제안했다. 이스라엘과 유대 민족에 대한 지지를 담대하고 공개적으로 표현할 것, 이스라엘에 뿌리를 둔 신앙의 유산을 기리는 특별 예배를 드릴 것, 그리고 깃발을 내걸어 연대를 보여 줄 것이다.</p>', '시카고 교외의 짐 스커더 주니어 목사는 CBN 뉴스 칼럼에서 하마스 공격 3주년을 앞두고 ‘펠로십의 깃발’ 캠페인에 동참하는 이유를 밝혔다.', '/sites/israeltoday/covers/mission-christian-israel-2.svg', '2026-10-02T00:05:00+00:00'::timestamptz, array['펠로십의깃발', 'IFCJ', '친이스라엘', '미국교회', '칼럼']::text[]),
  ('mission-christian-israel', '시애틀 시장, ‘기독교 시온주의 아마겟돈’ 경고한 저자들과 대담', '<p>@@BYLINE@@&nbsp;미국 시애틀의 케이티 윌슨 시장이 9월 24일 타운홀 시애틀에서 작가 나오미 클라인, 애스트라 테일러와 함께 두 사람의 신간 『종말의 파시즘(End Times Fascism)』 북토크를 진행했다고 유대계 매체 JNS(유대뉴스신디케이트)가 보도했다. JNS에 따르면 윌슨 시장은 이 자리에서 책을 높이 평가하고 가자 전쟁을 집단학살이라고 표현했다. 행사는 시애틀 채널(Seattle Channel)이 녹화해 온라인에 공개했다.</p><p>이 책은 종교 근본주의자와 실리콘밸리 기술자, 민족주의자들이 종말론적 미래관을 공유하며 일종의 동맹을 이루고 있다는 저자들의 주장을 담았다. 윌슨 시장은 “여러분의 작업은 좌파에게 매우 중요하다”고 말했다. 그는 가자지구 재개발 계획을 거론하며 누군가 콘도를 팔아 큰돈을 벌게 될 것이라고 꼬집기도 했다.</p><p>몬트리올 출신 유대계 캐나다 작가로 밴쿠버에 사는 클라인(56)은 ‘종말론자들’을 주제로 한 대화에서 도널드 트럼프 대통령이 기독교 시온주의자인 마이크 허커비를 주이스라엘 대사로 임명했다고 언급했다. JNS는 클라인이 ‘평화를 위한 유대인의 목소리(JVP)’를 지지한다고 전했다. 또 아칸소 주지사를 지낸 허커비 대사는 2025년 4월 상원 인준을 받았으며, 스스로 기독교 시온주의자라고 밝혀 왔다고 설명했다.</p><p>클라인은 복음주의 기독교인들이 알아크사를 둘러싼 이스라엘의 행보를 지지하는 것이 이미 불안정한 지역에 성냥불을 긋는 일이며, 핵무기를 동원한 3차 세계대전을 부를 수 있다고 주장했다. 그는 위니펙 출신 캐나다계 미국인 작가이자 활동가인 테일러(46)와 함께 일부 기독교 시온주의자들이 종말론과 연결해 의미를 두는 ‘흠 없는 붉은 암송아지’와 동물 제사에 대해 공부했다고 밝혔다.</p><p>클라인은 이들이 이스라엘 정부 안에서, 그리고 미국 정부 안에서도 과거 어느 때보다 큰 영향력을 갖게 됐다고 주장했다. 그는 “우리는 그들이 틀렸고 이것이 메시아를 오게 하지 않을 것이라고 생각하지만, 그렇다고 그들이 아마겟돈을 촉발하지 못한다는 뜻은 아니다”라고 말했다.</p><p>테일러는 청중에게 미국민주사회주의자(DSA)에 가입하거나 선거 운동에 참여하라고 권했고, 윌슨 시장은 전적으로 동의한다고 답했다. JNS는 윌슨 시장이 스스로를 민주사회주의자라고 소개하지만 DSA 회원은 아니며, 2025년 시장 선거 때 이 단체의 지지를 받지 못했다고 전했다. JNS는 윌슨 시장에게 입장을 요청했다고 밝혔다.</p><p>기독교 시온주의는 성경의 약속을 근거로 이스라엘을 지지하는 복음주의 흐름을 가리킨다. 이번 대담은 북미 진보 진영 일각에서 이 신앙 흐름을 정치적 위협으로 보는 시각이 공직자가 함께한 공개 무대에서 드러난 사례라는 점에서, 이스라엘을 위해 기도하는 한국 교회도 눈여겨볼 만하다.</p>', 'JNS에 따르면 케이티 윌슨 시장은 나오미 클라인·애스트라 테일러의 신간 북토크를 진행하며 가자 전쟁을 집단학살로 규정했다. 클라인은 기독교 시온주의자들이 종말 전쟁을 부를 수 있다고 주장했다.', '/sites/israeltoday/covers/mission-christian-israel-3.svg', '2026-10-02T22:01:22+00:00'::timestamptz, array['기독교시온주의', '시애틀', '나오미클라인', '종말론', '미국']::text[]),
  ('holyland-jerusalem', '예루살렘 이번 주 볼거리, 영어 뮤지컬부터 숲 탐방까지(10월 2~8일)', '<p>@@BYLINE@@&nbsp;예루살렘포스트의 주간 문화 안내 ‘예루살렘 하이라이트’가 10월 2일부터 8일까지 예루살렘에서 즐길 수 있는 영화와 공연, 체험 프로그램을 소개했다. 신문은 계속되는 안보 상황 때문에 행사가 연기되거나 취소될 수 있다며 예약 전 반드시 확인하라고 당부했다. 예루살렘을 찾는 한국 방문객이 일정 사이에 참고할 만한 프로그램을 날짜별로 정리했다.</p><p>10월 2일 금요일에는 예루살렘 시네마테크에서 2024년 멕시코 자연 영화 『플라밍고: 운석 이후의 삶』(로렌소 하게르만 감독)이 상영된다. 홍학의 삶을 가까이에서 담은 작품으로 영어와 히브리어 자막이 함께 나온다. 상영은 오후 6시 30분, 관람료는 25셰켈이다.</p><p>10월 4일 일요일에는 칸 극장에서 사무엘 베케트의 1953년 고전 『고도를 기다리며』가 무대에 오른다. 우디 벤모셰가 연출했고, 조 엘드로르의 히브리어 번역으로 공연된다. 공연은 오후 8시, 관람료는 220셰켈이다. 히브리어 공연인 만큼 작품 줄거리를 미리 알고 가는 편이 좋다.</p><p>10월 5일 월요일에는 영어 뮤지컬 『라스트 파이브 이어스』를 볼 수 있다. 제이슨 로버트 브라운이 작사·작곡한 2001년 작품으로, 한 남녀의 5년 관계를 남자는 처음 만난 순간부터, 여자는 이혼한 시점부터 거꾸로 풀어 가는 독특한 구성이다. 공연은 오후 5시와 8시 30분 두 차례, 관람료는 100셰켈이다.</p><p>10월 6일 화요일 소개된 곳은 예루살렘에 기반을 둔 영어 중고서적 온라인 서점 ‘에브리데이 캐리 북스’다. 홀로코스트에서 살아남아 미국에서 새 삶을 일군 에스더 니센탈 크리니츠의 『생존의 기억』(90셰켈) 등을 구할 수 있으며, 예루살렘 시내는 무료로 배달해 준다.</p><p>10월 7일 수요일에는 아다라 페스킨 샬렘과 함께하는 영어 채집 체험이 열린다. 먹을 수 있는 식물뿐 아니라 독성이 있는 식물, 병을 다스리는 데 쓰일 수 있는 식물까지 배우며 예루살렘 숲을 2시간 동안 걷는다. 비용은 20명 이하 단체 기준 1,250셰켈이고 한 사람 추가할 때마다 50셰켈이며, 한 그룹은 최대 40명이다.</p><p>10월 8일 목요일에는 예루살렘 음악센터에서 지휘자 츠비 카르멜리와 영 이스라엘 필하모닉 체임버 오케스트라가 오스트리아 작곡가 로베르트 푹스의 현악 오케스트라를 위한 세레나데 3번을 연주한다. 공연은 오후 7시, 관람료는 125셰켈이다.</p>', '예루살렘포스트가 소개한 한 주간의 공연·체험 가운데 방문객이 참고할 만한 프로그램을 추렸다. 안보 상황에 따라 일정이 바뀔 수 있어 사전 확인이 필요하다.', '/sites/israeltoday/covers/holyland-jerusalem-1.svg', '2026-10-02T16:13:02+00:00'::timestamptz, array['예루살렘', '문화행사', '공연', '성지여행', '주간안내']::text[]),
  ('holyland-travel', '초막절 예루살렘, 제사장 축복부터 ‘순례자의 길’까지', '<p>@@BYLINE@@&nbsp;예루살렘포스트가 초막절(수콧)을 맞아 예루살렘과 근교에서 가족이 함께 즐길 수 있는 프로그램을 모은 안내 기사를 실었다. 글은 가족 나들이 정보 사이트 ‘펀 인 예루살렘(Fun In Jerusalem)’의 설립자 조애나 셰브슨과 론잇 안스바허가 썼다. 필자들은 초막절 예루살렘을 발코니와 마당마다 초막이 서고 박물관과 문화기관이 특별 프로그램을 여는 곳으로 소개하며, 무엇을 하든 미리 예약하라고 강하게 권했다.</p><p>가장 눈에 띄는 행사는 통곡의 벽에서 열리는 ‘비르카트 코하님(제사장의 축복)’이다. 수천 명의 제사장 가문 후손이 모인 수만 명에게 축복을 선포하는 자리로, 올해는 9월 28일 월요일과 10월 1일 목요일 오전 9시 30분과 10시 30분에 열리는 것으로 안내됐다. 참가는 무료이며, 필자들은 구시가지까지 걸어 들어가고 걸어 나올 계획을 세우라고 조언했다.</p><p>예루살렘 사프라 광장에는 이스라엘에서 가장 큰 초막이 세워진다. 모셰 레온 예루살렘 시장 부부는 9월 27일 오후 4시 이 초막에서 시민을 맞이하는 것으로 소개됐다. 초막절의 대표 행사인 예루살렘 행진은 9월 28일 열리며 12km(기바트 마수아 출발), 9km(에인 야엘 출발), 5km(사프라 광장 출발) 세 코스 중 하나를 골라 걸을 수 있고 참가는 무료다.</p><p>성경 속 순례를 직접 걸어 보는 투어도 있다. 가이드 데브라 누스바움 스테펜은 다윗성에서 남쪽 벽 발굴지까지 이어지는 고대 ‘순례자의 길’을 안내한다. 세 순례 절기마다 수많은 예배자가 예루살렘으로 오르던 길의 옛 돌 위를 걷는 일정으로, 반나절 투어는 400달러, 종일 투어는 600달러이며 입장료는 따로 내야 한다. 이스라엘 박물관에서는 나흐리엘 셀라반이 ‘이사야 대두루마리와 기록된 말씀’ 투어를 진행하며 비용은 90~130셰켈이다.</p><p>벧세메스의 성경자연사박물관은 코끼리를 초막의 벽으로 쓸 수 있는지를 두고 2,000년 동안 이어진 토론을 소재로 초막절 프로그램을 마련했다. 고대 이스라엘의 야생동물과 쇼파르(뿔나팔) 전시관도 둘러볼 수 있다. 입장료는 성인 58셰켈, 어린이와 학생, 노인, 군인은 45셰켈이다.</p><p>성막(미쉬칸)이 있던 고대 실로에서는 9월 28일부터 30일까지 실물 크기의 성물 전시와 3D 가상 투어 등을 갖춘 축제가 열리는 것으로 안내됐다. 3세 이상 입장료는 64셰켈이다. 성경 시대에 쓰인 약용 식물과 천연 재료를 배우고 직접 연고를 만드는 약 2시간 반짜리 체험(350셰켈)도 소개됐다.</p><p>봉사로 절기를 보내는 방법도 있다. 이스라엘 국가 푸드뱅크인 레켓 이스라엘에서는 농가가 기부한 과일과 채소를 수확하거나 음식 나눔을 돕는 봉사에 무료로 참여할 수 있다. 필자들은 어떤 활동을 고르든 초막절 예루살렘에서 즐거운 시간을 보낼 것이라고 글을 맺었다.</p>', '예루살렘포스트가 소개한 초막절 가족 프로그램 가운데 성경과 맞닿은 체험을 골랐다. 날짜가 정해진 행사는 대부분 지났지만 예약제 프로그램은 순례 일정에 참고할 만하다.', '/sites/israeltoday/covers/holyland-travel-2.svg', '2026-09-25T17:37:57+00:00'::timestamptz, array['초막절', '성지순례', '예루살렘', '통곡의벽', '가족여행']::text[]),
  ('holyland-travel', '텔아비브발 서울 직항 열린다…예루살렘포스트 여행 팟캐스트 조명', '<p>@@BYLINE@@&nbsp;이스라엘에서 서울로 곧장 가는 하늘길이 열린다. 예루살렘포스트는 여행 팟캐스트 ‘트래블 에디션’에서 앞으로 몇 달 안에 이스라엘과 필리핀, 한국, 아르헨티나를 직항으로 잇는 주요 신규 노선 세 개가 열린다며, 텔아비브에서 출발하는 마닐라·서울·부에노스아이레스 노선을 주제로 한 회차를 공개했다.</p><p>이번 회차는 새 노선의 세 목적지를 각국 외교관의 목소리로 소개하는 형식으로 꾸며졌다. 한국 편에는 주이스라엘 한국대사관의 차석(Deputy Chief of Mission)이 출연해 깊어지는 두 나라의 관계, 서울에서 꼭 가 봐야 할 흥미로운 지역, 그리고 한국 음식의 매력을 이야기했다고 신문은 전했다.</p><p>필리핀 편에서는 주이스라엘 필리핀 대사가 섬나라 특유의 분위기와 필리핀만의 독특한 유대인 연결고리, 활기찬 음식 문화를 소개했다. 아르헨티나 편에서는 주이스라엘 아르헨티나 대사가 다양한 지역의 매력과 현지 유대인 공동체, 그리고 널리 알려진 아르헨티나식 스테이크를 훨씬 넘어서는 음식 문화를 설명했다.</p><p>팟캐스트는 여행자에게 필요한 실용 정보도 함께 다뤘다. 공항과 현지 교통, 기후, 통화, 숙소, 그리고 유대인 여행자에게 중요한 코셔 음식 사정까지 짚었다. 이 회차는 애플 팟캐스트와 스포티파이, 유튜브에서도 들을 수 있다.</p><p>서울이 이스라엘발 신규 직항 목적지로 꼽히고, 이스라엘 매체가 한국대사관 외교관을 직접 초대해 한국을 소개했다는 점은 눈여겨볼 만하다. 해마다 성지순례를 준비하는 한국 교회와 성도들에게도 반가운 소식이다. 직항 노선이 안정적으로 운항된다면 경유에 따른 시간과 비용을 줄여, 순례객의 이동 부담도 한결 가벼워질 것으로 보인다.</p><p>다만 예루살렘포스트의 소개글에는 어느 항공사가 언제부터, 얼마나 자주 운항하는지는 나와 있지 않다. 순례나 방문을 계획하는 교회와 여행사는 운항 일정과 요금을 항공사의 공식 발표로 확인할 필요가 있다.</p>', '앞으로 몇 달 안에 이스라엘과 한국·필리핀·아르헨티나를 잇는 직항 노선이 새로 열린다. 팟캐스트에는 주이스라엘 한국대사관 차석이 출연했다.', '/sites/israeltoday/covers/holyland-travel-3.svg', '2026-09-15T10:52:00+00:00'::timestamptz, array['직항노선', '서울', '텔아비브', '성지순례', '한국이스라엘']::text[]),
  ('holyland-photo', 'KKL-JNF, 1950~60년대 초막절 풍경 담은 미공개 사진 공개', '<p>@@BYLINE@@&nbsp;이스라엘 유대민족기금(KKL-JNF) 사진 아카이브가 초막절(수코트)을 앞두고 1950~60년대 이스라엘 각지에서 초막절을 지키던 사람들의 모습을 담은 미공개 사진 네 장을 공개했다고 예루살렘포스트가 보도했다. 정교하게 꾸민 초막이나 상점에서 산 장식, 소셜미디어에 올리는 사진이 등장하기 훨씬 전, 이스라엘의 초막절이 무엇보다 공동체의 축제였음을 보여주는 자료다.</p><p>첫 번째 사진은 1959년(유대력 5720년) 초막절에 촬영됐다. 예루살렘의 한 초막 안에서 하시딤 유대인이 ‘네 가지 식물’을 손에 들고 룰라브 계명을 행하는 장면이다. KKL-JNF에 따르면 그를 둘러싼 초막 벽은 손으로 만든 종이 사슬과 장식으로 꾸며져 있다.</p><p>1963년 사진은 분위기가 사뭇 다르다. 조용히 기도하는 예루살렘 초막과 달리, 북부 마을 호르샤트 탈에서 열린 대규모 축제 현장에서 많은 사람이 수확의 절기를 기념하는 춤 공연을 지켜보고 있다.</p><p>1964년 예루살렘에서 찍힌 사진에는 초막절 중간 기간(홀 하모에드)에 열린 ‘예루살렘 깃발’ 행사에 참여한 아이들이 등장한다. 흰옷을 입은 아이들은 네 가지 식물과 꽃, 깃발 등을 들고 공원을 행진하고 있다.</p><p>마지막 사진은 6일 전쟁과 예루살렘 재통일 몇 달 뒤인 1967년, 예루살렘의 ‘네 가지 식물’ 시장에서 촬영됐다. 룰라브(종려나무 가지)와 도금양 가지, 에트로그(시트론 열매)가 수북이 쌓인 좌판 사이에서 한 아이가 에트로그를 들고 서 있다. 이 시장은 지금도 해마다 예루살렘에서 열린다.</p><p>KKL-JNF 아카이브 책임자 에프랏 시나이는 “이 사진들은 수십 년 전 이스라엘에서 지켜졌던, 그리고 오늘날에도 여전히 지켜지는 초막절을 다시 만나게 해 준다”고 말했다. 그는 가족의 초막과 예루살렘 시장, 대규모 야외 모임이 모두 사진에 담겼다며 “전통과 시온주의 교육, 농업과 공동체가 어우러져 이 절기만의 독특한 이스라엘적 성격을 만들어 냈음을 보여준다”고 설명했다.</p><p>초막절은 레위기에 기록된 절기로, 광야에서 장막에 거하던 시절을 기억하며 초막을 짓고 그 안에서 지내는 절기다. 네 가지 식물을 함께 드는 관습도 레위기 말씀에 뿌리를 두고 있다. 초막절 무렵 예루살렘을 찾는 순례객이라면 반세기 넘게 이어져 온 네 가지 식물 시장에서 사진 속 풍경이 오늘날 어떻게 이어지고 있는지 직접 볼 수 있다.</p>', '초막 안의 기도부터 북부 마을의 수확 축제, 예루살렘 ‘네 가지 식물’ 시장까지 공동체 절기로서의 초막절을 보여주는 기록 사진들이 처음 공개됐다.', '/sites/israeltoday/covers/holyland-photo-1.svg', '2026-09-25T10:03:35+00:00'::timestamptz, array['초막절', '수코트', 'KKL-JNF', '예루살렘', '기록사진']::text[]),
  ('holyland-history', '‘황금의 예루살렘’ 작곡가에 엽서 보낸 용사, 60년 가까이 지나 확인', '<p>@@BYLINE@@&nbsp;이스라엘을 대표하는 노래 ‘황금의 예루살렘(예루샬라임 셸 자하브)’의 작곡가 나오미 셰메르에게 6일 전쟁 당시 칭찬 엽서를 보낸 인물이 참전 용사 아하론 바르오즈로 확인됐다고 이스라엘 국립도서관이 발표했다. 예루살렘포스트가 전한 이 소식에는 현지 매체 와이넷(Ynet)과 바르오즈의 인터뷰 내용도 함께 담겼다.</p><p>이 노래는 1967년 독립기념일 전야에 가수 슐리 나탄이 처음 불렀다. 3주 뒤인 6월 5일 6일 전쟁이 터졌다. 이튿날 시나이 사막의 부대로 위문 공연을 가던 셰메르는 이스라엘군(IDF)이 예루살렘 구시가지를 되찾았다는 라디오 소식을 듣고 작은 주소록에 곡의 유명한 4절을 써 내려갔다. 성전산에서 쇼파르(뿔나팔) 소리가 울린다는 내용이 담긴 가사다.</p><p>같은 날 북부의 한 정찰부대를 대표해 바르오즈가 전선에서 셰메르에게 엽서를 보냈다. 그는 “당신의 노래 ‘황금의 예루살렘’은 전초기지에서 우리 삶의 일부가 됐습니다”라고 썼다. 이어 “지금 이 순간 우리 공군기가 골란고원을 폭격하고 있고, 라디오에서는 당신의 노래가 흘러나오고 있습니다”라고 적은 뒤 끝에 ‘화요일 9시 35분’이라고 시각을 남겼다. 바르오즈는 이후 골란고원 전투에서 부상을 입었다.</p><p>셰메르는 이 엽서를 간직했고, 전쟁이 끝난 뒤 아흐레 만에 답장을 보냈다. 그는 부대의 승리를 축하하면서 “멀리서나마 노래로 여러분을 도울 수 있었다니 기쁩니다”라고 썼다. 올해 89세인 바르오즈는 이 답장을 액자에 넣어 집 벽에 걸어 두고, 집을 찾는 모든 이에게 보여주었다고 와이넷에 말했다.</p><p>엽서를 쓴 사람이 누구인지는 오랫동안 알려지지 않았다. 그러다 최근 셰메르의 주소록과 초기 악보 초안, 그리고 이 엽서 등 개인 기록물을 선보인 국립도서관 전시 투어에서 한 참가자가 들뜬 모습으로 가이드에게 다가왔다. 바르오즈의 딸이 전시된 엽서에서 아버지의 필체를 알아본 것이다.</p><p>바르오즈는 8월 중순 셰메르의 답장 액자를 국립도서관에 기증했고, 이로써 두 사람이 주고받은 엽서와 편지가 한곳에 모이게 됐다. 그는 와이넷에 당시 책상도 의자도 없어서 다른 병사를 앞에 세우고 그의 등을 받침 삼아 엽서를 썼으며, 갈릴리 호숫가 키부츠 크부차트 키네렛에 있는 셰메르의 집으로 보냈다고 회상했다.</p><p>바르오즈는 동원된 수십만 명의 병사가 모두 이 노래를 불렀지만 정작 셰메르에게 감사 편지를 쓴 사람은 없었다는 사실이 놀라웠다고 말했다. 그는 이제 편지가 국립도서관에 있어야 할 때라며, 특히 손주 세대와 ‘입대하느니 차라리 죽겠다’고 말하는 이들을 위해서라도 그곳에 있어야 한다고 강조했다.</p>', '6일 전쟁 전선에서 나오미 셰메르에게 감사 엽서를 보낸 주인공은 참전 용사 아하론 바르오즈였다. 딸이 국립도서관 전시에서 아버지의 필체를 알아봤다.', '/sites/israeltoday/covers/holyland-history-2.svg', '2026-09-03T08:25:14+00:00'::timestamptz, array['황금의 예루살렘', '나오미 셰메르', '6일 전쟁', '국립도서관', '예루살렘']::text[]),
  ('holyland-history', '건국 초 ‘내전 위기’의 상징 알탈레나호, 78년 만에 해저서 발견', '<p>@@BYLINE@@&nbsp;1948년 이스라엘군(IDF)과 유대 지하조직 이르군의 무력 충돌 끝에 불타 가라앉은 선박 알탈레나호의 잔해가 침몰 78년 만에 지중해 해저에서 온전한 상태로 발견됐다. 예루살렘포스트에 따르면 이타마르 벤그비르 국가안보장관과 유산부(Heritage Ministry)가 이같이 발표했으며, 유산부는 선박이 이스라엘 해안에서 약 20km 떨어진 수심 503m 지점에 있다고 밝혔다.</p><p>알탈레나호는 1948년 6월 이스라엘 앞바다에 도착했다. 배에는 신생 유대 국가로 향하는 이민자 수백 명과 이르군 대원들, 독립전쟁에 쓰일 대량의 무기와 탄약이 실려 있었다. 이르군(에첼)은 메나헴 베긴이 이끈 건국 이전의 유대 지하조직으로, 영국 통치와 아랍 세력에 맞서 싸웠다.</p><p>1948년 5월 14일 독립 선언 이후 여러 유대 무장조직이 IDF로 편입되기 시작했고, 6월 1일 이르군 통합 합의가 서명됐다. 쟁점은 배에 실린 무기였다. 베긴은 무기의 20%를 예루살렘에서 싸우는 이르군 부대에 보내려 했지만, 다비드 벤구리온 총리의 정부는 국내에 반입된 무기는 IDF 관할이라고 맞섰다. 별도의 정치 세력이 무장하면 ‘군대 안의 군대’가 생길 수 있다는 우려 때문이었다. 당시는 무기 반입을 금지한 유엔 중재 휴전 기간이기도 했다.</p><p>알탈레나호는 6월 20일 네타냐 북쪽 크파르 비트킨에 도착해 승객을 내리고 무기를 하역하기 시작했다. 이튿날 IDF가 일대를 포위하고 무기 인도를 요구했으나 거부되자 교전이 벌어져 이르군 대원 6명과 IDF 병사 2명이 숨졌다. 6월 22일 텔아비브 앞바다에서 충돌이 재개됐고, IDF의 포격으로 배에 불이 붙었다. 이 사건의 사망자는 모두 19명(IDF 3명, 이르군 16명)이었다.</p><p>사태가 더 번질 수 있는 상황에서 베긴은 이르군에 IDF를 향한 보복을 금지하고 내전으로 치달아서는 안 된다고 경고했다. 예루살렘포스트는 이 결정이 훗날 총리가 된 베긴의 정치적 유산을 규정하는 요소가 됐으며, 이 사건으로 신생 국가가 정부 권한 아래 단일 국군을 둔다는 원칙이 세워졌다고 전했다. 불탄 배는 텔아비브 앞바다에 남아 있다가 먼바다로 예인돼 가라앉혀졌다.</p><p>벤그비르 장관은 “오늘 밤 우리는 이스라엘 사회 역사에서 가장 고통스럽고도 형성적인 사건 가운데 하나에 대한 역사의 고리를 닫는다”고 말했다. 아미하이 엘리야후 유산부 장관은 “알탈레나호의 발견은 우리 국가 기억에 있어 결정적인 순간”이라고 밝혔다.</p><p>벤구리온 유산연구소의 라몬 지브아브 부국장은 이번 발견이 오늘날에도 유효한 중요한 논의를 할 기회라며 “배와 함께 내전의 위험까지 돌아온다면, 그 위험은 바다에 남아 있는 편이 낫다”고 말했다.</p>', '이스라엘 유산부는 선박이 해안에서 약 20km 떨어진 수심 503m 지점에서 온전한 상태로 발견됐다고 밝혔다.', '/sites/israeltoday/covers/holyland-history-3.svg', '2026-08-24T10:42:30+00:00'::timestamptz, array['알탈레나호', '이스라엘 건국', '메나헴 베긴', '벤구리온', '해저 발견']::text[]),
  ('holyland-jerusalem', '‘예루살렘은 우리 도시’ 설전 뒤에 가려진 성지의 복잡한 현실', '<p>@@BYLINE@@&nbsp;베냐민 네타냐후 이스라엘 총리가 9월 24일 유엔 연설에서 레제프 타이이프 에르도안 튀르키예 대통령을 비판하며 예루살렘 문제를 꺼냈다. 그는 에르도안이 예루살렘의 통치자가 되겠다고 말한다며 “이곳은 우리의 도시다”라고 반박했다. 미국 유대계 매체 JNS는 분석 기사에서 두 지도자의 설전 이면에 놓인 예루살렘 성지 관리의 복잡한 구조를 짚었다.</p><p>JNS에 따르면 에르도안은 6년 전에도 비슷한 말을 했다. 2020년 10월 1일 튀르키예 의회 개회 연설에서 그는 예루살렘을 “우리의 도시, 우리에게서 나온 도시”라고 선언했다. 근거는 현재의 주권이 아니라 역사였다. 그는 제1차 세계대전 중에 끝난 네 세기에 걸친 오스만 제국의 예루살렘 통치와 술레이만 대제가 구시가지에 남긴 흔적을 내세웠다.</p><p>JNS는 이 역사가 에르도안에게 ‘계승’의 언어를 줄 뿐, 오늘날 튀르키예에 성지에 대한 공식 관리 역할을 주지는 않는다고 분석했다. 다만 튀르키예는 말 뒤에 자금과 기관을 두고 있다. 튀르키예 협력조정청(TİKA)은 2005년부터 동예루살렘 등지에서 교육·문화·복원 사업을 지원해 왔고, 2017년 6월까지 동예루살렘에서만 71건의 사업을 진행했다고 밝혔다. 400명 규모의 여학생 기숙사 계획도 지원했다.</p><p>한계도 분명하다. TİKA는 2017년 알아크사 모스크 옆 이슬람 박물관을 보수하려 할 때 요르단 당국과 허가 협상을 벌였다. 1994년 이스라엘-요르단 평화조약 제9조는 이스라엘이 “예루살렘 무슬림 성지에서 요르단 하심 왕국이 현재 갖는 특별한 역할”을 존중한다고 규정한다. JNS는 이 조항이 요르단에 예루살렘 주권을 넘기거나 이스라엘과 팔레스타인의 주장을 정리하는 것은 아니지만, 튀르키예에는 없는 요르단의 역할을 공식 인정한 것이라고 설명했다.</p><p>요르단의 지위는 2013년 3월 압둘라 2세 국왕과 마흐무드 압바스 팔레스타인자치정부 수반이 암만에서 맺은 협정으로 재확인됐다. 성지를 관리하는 예루살렘 이슬람 와크프는 요르단의 종교 행정과 연결돼 있다.</p><p>그렇다고 요르단의 지위를 과장해서도 안 된다고 JNS는 덧붙였다. 이스라엘은 예루살렘을 수도로 여기며 통치와 안보 권한을 행사하고, 성전산 일대의 출입과 안보도 상당 부분 통제한다. 다만 동예루살렘에 대한 이스라엘의 주권은 국제적으로 인정받지 못하고 있다. 팔레스타인은 동예루살렘을 미래 국가의 수도로 주장하며, 튀르키예도 이를 지지한다. 에르도안은 9월 22일 유엔 연설에서도 이 입장을 되풀이했다.</p><p>JNS는 주권, 안보, 종교 행정, 역사적 관리권, 정치적 상징이 서로 겹쳐 있으며 어느 한 주체에 모두 속하지 않는다고 결론지었다. 성전산을 찾는 순례객이 마주하는 현실도 ‘누구의 도시인가’라는 구호만으로는 설명되지 않는다는 것이다.</p>', '네타냐후와 에르도안이 유엔에서 예루살렘을 두고 맞섰지만, 무슬림 성지에는 1994년 조약이 인정한 요르단의 ‘특별한 역할’이 따로 있다고 JNS가 분석했다.', '/sites/israeltoday/covers/holyland-jerusalem-1.svg', '2026-10-02T09:06:00+00:00'::timestamptz, array['예루살렘', '성전산', '요르단', '튀르키예', '네타냐후']::text[]),
  ('shema-jewish-edu', '‘다음 세대는 누가 가르치나’…유대인 교육자 300여 명 예루살렘에', '<p>@@BYLINE@@&nbsp;전 세계 유대인 교육자들이 다음 세대 교육을 논의하기 위해 예루살렘에 모인다. 예루살렘포스트에 따르면 이스라엘 디아스포라·반유대주의대응부가 주최하는 ‘글로벌 유대인 교육자 서밋’이 10월 12일부터 나흘간 예루살렘 라마다 호텔에서 열린다. 해외 유대인 교사와 교장 등 200여 명과 이스라엘 교사 100명 등 300여 명이 참석한다. 당초 3월로 예정됐던 행사는 ‘포효하는 사자’ 작전으로 연기됐다.</p><p>행사 진행은 세계 각국의 유대인 주간학교를 지원하는 교육단체 유나이티드(UnitEd)가 맡는다. 레이첼 핑크 교육국장은 “유대 교육의 미래는 프로그램이나 교육과정만으로 만들어지지 않는다”며 매일 유대인 아이들 앞에 서는 사람들이 그 미래를 만든다고 말했다. 행사에서는 뛰어난 교육자 8명에게 ‘유대인 교사상’이 수여된다.</p><p>서밋은 교육자 개인의 정체성과 사명, 이스라엘과 세계 유대인 공동체의 관계, 그리고 유대 지식과 가치와 소속감을 다음 세대에 전하는 책임이라는 세 가지 주제를 다룬다. 주최 측은 참석자들이 세계 각지의 동료 네트워크와 새로운 교육 도구, 새로워진 사명감을 안고 공동체로 돌아가도록 돕는 것이 주요 목표라고 밝혔다.</p><p>참석자들의 이야기에서는 현장의 무게가 드러난다. 호주 시드니 케세르 토라 칼리지의 레비 밀레키 랍비는 동화와 높은 생활비, 반유대주의를 호주 유대 교육의 주요 과제로 꼽았다. 그는 2025년 12월 14일 시드니 본다이 해변에서 하누카 기간에 일어난 총격 사건으로 15명이 숨지고 40명이 다쳤으며, 당시 학교 학생 90여 명이 해변에 있었다고 전했다. 그는 학교가 받은 영향이 상당했다며 “유대 교육자들은 다음 세대를 길러내고 있기에 가장 중요한 역할을 한다”고 말했다.</p><p>남아공 케이프타운 유나이티드 헤르츨리아 학교의 샘 서굿 랍비는 10월 7일 사건이 세계 유대인의 취약함을 드러냈지만 서로를 향한 책임감도 일깨웠다고 말했다. 그는 반유대주의에 대한 응답은 분명한 정체성에서 출발해야 한다며 “우리가 여기 있는 것은 이것이 바로 우리 자신이기 때문이다”라고 강조했다. 그에 따르면 남아공 유대인 아이들의 75~85%가 유대인 주간학교에 다니며, 학교가 공동체의 중심 역할을 한다.</p><p>이 기사는 위기의 시대에 신앙과 정체성을 다음 세대에 전하는 일이 결국 ‘사람’, 곧 교사의 몫이라는 점을 보여준다. 공격을 받은 뒤에도 학교가 아이들 곁을 지키고, 정체성을 반대 세력에 대한 반응이 아니라 ‘우리가 누구인가’에서 출발시키려는 이들의 고민은 다음 세대 신앙 교육을 고민하는 한국 교회 교사와 부모에게도 생각할 거리를 던진다.</p>', '10월 12일부터 나흘간 ‘글로벌 유대인 교육자 서밋’이 열린다. 반유대주의와 동화의 도전 앞에 선 호주·남아공 교육자들이 현장의 고민을 전했다.', '/sites/israeltoday/covers/shema-jewish-edu-2.svg', '2026-10-01T12:29:23+00:00'::timestamptz, array['유대인 교육', '다음 세대', '교사', '반유대주의', '예루살렘']::text[]),
  ('shema-torah', '유대인은 왜 닫힌 토라를 안고 춤추나…심하트 토라와 ‘하나 됨’', '<p>@@BYLINE@@&nbsp;초막절 끝자락의 심하트 토라(토라의 기쁨)는 한 해 동안 이어온 토라 낭독을 마치고 다시 창세기로 돌아가는 날이다. 미국 유대계 매체 JNS에 실린 칼럼에서 젊은 유대인 직장인들과 함께 사역하는 한 하바드 랍비는 이 절기가 분열된 유대 사회에 주는 메시지를 풀어냈다.</p><p>필자는 10월 7일 하마스의 공격 며칠 뒤 철저히 세속적인 한 이스라엘인에게서 전화를 받았다고 회상했다. 그는 그런 일을 겪고도 어떻게 기도 속에서 하나님의 자비를 말할 수 있느냐며 하나님께 분노했다. 신학적 질문 앞에서 책부터 펴던 필자는 그날 대신 그와 커피를 마셨다. 두 사람은 이야기하고 울고 웃다가 끝내 서로를 껴안았다. 누구도 상대를 설득하지 못했지만, 필자는 그 자리에 두 사람의 의견 차이보다 깊은 무언가가 있었다고 썼다.</p><p>필자는 유대인들이 세속·정통·진보·이스라엘·미국 같은 수식어를 ‘유대인’이라는 단어보다 더 중요하게 여기게 됐다고 진단했다. 각 진영이 유대인의 가장 큰 문제를 결국 ‘다른 유대인’으로 결론 내리는 일이 얼마나 잦은지 놀랍다는 것이다. 10월 7일은 잠시 이 구도를 흔들었지만 옛 구분은 점차 돌아왔고, 3년이 지난 지금 필자는 그 비극이 원래 있던 연결을 드러냈을 뿐이라고 봤다.</p><p>그가 주목한 것은 심하트 토라의 모습이다. 의대 졸업생이 해부학 교과서를 덮고 껴안은 채 춤추지는 않는다. 책은 펼쳐서 공부하고 질문하고 논쟁하라고 있는 것이다. 그런데 유대인은 한 해 동안 토라를 읽고 끝에 이르면 책을 덮고 목이 쉬도록 노래하며 춤춘다. 그 시간만큼은 학자와 초심자가 같은 토라를 붙들고, 세속 이스라엘인과 하바드 랍비가 같은 원 안에서 춤출 수 있다는 것이다. 필자는 “하나 됨은 우리의 차이 아래에 존재한다”며 우리의 과제는 그것을 드러내는 일이라고 강조했다.</p><p>그리고 춤이 끝나면 곧바로 토라를 다시 편다. ‘태초에 하나님이 창조하시니라’로 시작하는 창세기 첫 구절, 곧 ‘베레시트 바라 엘로힘’으로 돌아간다. 필자는 토라를 덮는 일이 논쟁을 제자리에 두게 한다고 해석했다. 몇 시간 동안 논쟁보다 앞선 관계를 기억하고, 다시 공부하고 질문하며 진리를 찾는다는 것이다. 그는 논쟁 자체는 진리를 찾는 과정에 속하지만, 논쟁이 상대를 ‘문제’로 만들 때 탈이 난다고 지적했다.</p><p>필자는 어려운 대화 속에서 “나는 옳으려 하는가, 아니면 우리가 함께 옳은 것을 찾으려 하는가?”를 스스로 묻게 됐다고 했다. 또 ‘다리를 놓는다’는 표현은 너무 늦게 시작한다며, 연결은 이미 있었다고 말했다. 그는 “심하트 토라는 순서를 바로잡는다”며 먼저 춤추고, 그다음 토라를 펼쳐 질문하고 논쟁하라고 권했다.</p><p>교파와 세대, 정치적 입장에 따라 갈라지기 쉬운 한국 교회에도 이 칼럼은 생각할 거리를 준다. 진리에 대한 확신을 내려놓지 않으면서도 옆에서 함께 진리를 찾는 이를 적으로 만들지 않는 태도, 그리고 말씀 앞에 함께 서는 기쁨이 논쟁보다 먼저라는 필자의 고백은 공동체가 붙들 만한 순서다.</p>', '한 하바드 랍비는 칼럼에서 토라를 덮고 함께 춤춘 뒤 곧바로 다시 펼치는 심하트 토라의 순서에 유대인 연합의 비밀이 있다고 말했다.', '/sites/israeltoday/covers/shema-torah-3.svg', '2026-10-02T17:31:00+00:00'::timestamptz, array['심하트 토라', '유대인 연합', '토라', '쉐마', '초막절']::text[]),
  ('shema-torah', '파라샤 니짜빔이 전하는 메시지 ‘우리는 모두 같은 배에 타고 있다’', '<p>@@BYLINE@@&nbsp;예루살렘포스트에 실린 칼럼에서 통곡의 벽과 성지 담당 랍비는 유대 신년(로쉬 하샤나)을 앞두고 읽는 토라 본문 ‘니짜빔’(신명기 29장 이하)을 통해 ‘서로에 대한 책임’을 강조했다. 필자는 개인의 성취와 성공에 몰두하는 서구 사회가 타인을 경쟁자나 사생활을 위협하는 존재로 바라보게 만든다고 진단했다.</p><p>필자에 따르면 건강한 사회는 강한 사람이 약한 사람을 붙들어 어려움에서 벗어나도록 돕는 상호 부조 위에 세워진다. 오늘은 내가 너를 돕고 내일은 네 자녀가 내 자녀를 돕는다는 이해다. 그러나 모두가 자기 일에만 몰두하면 ‘각자 알아서 하라’는 무관심의 이념이 자라나고, 영적·도덕적 영역에서도 남의 삶에 간섭하지 말라는 금기가 생긴다. 필자는 사람마다 자기 소견에 옳은 대로 행하는 사이 도덕적 가치가 서서히 무너진다고 지적했다.</p><p>필자는 잘 알려진 배의 비유를 들었다. 배에 탄 한 승객이 자기 자리 밑에 구멍을 뚫자 다른 승객들이 놀라 말렸다. 그러자 그는 “나는 당신들 자리가 아니라 내 자리 밑에 구멍을 뚫는 것이다”라고 대답했다. 승객들은 물이 차오르면 배 전체가 가라앉아 모두 함께 빠져 죽는다고 답했다. 필자는 ‘내 자리 밑에서만’ 벌어지는 일은 사실상 없으며, 한 사람에게 일어난 일이 결국 사회 전체에 영향을 준다고 강조했다.</p><p>니짜빔 본문은 ‘너희가 오늘 다 여호와 앞에 섰다’는 선언과 함께 그 자리에 선 이들을 길게 열거하며 시작한다(신명기 29장). 필자는 단어 하나도 허투루 쓰지 않는 토라가 이 대목에서 지도자와 평범한 사람, 남자와 여자, 어른과 아이, 본토인과 개종자를 일일이 나열한다는 데 주목했다. 모두가 함께 서 있다는 것이다. 세상을 고치는 일은 몇몇 개인에게만 기댈 수 없으며, 모든 사람이 동역자이고 각자 자리와 역할이 있다는 메시지라고 그는 해석했다.</p><p>필자는 모세가 생애 마지막 날 온 백성을 모아 하나님과의 언약을 새롭게 세웠고, 그때부터 백성 한 사람 한 사람이 서로의 행위에 책임을 지게 됐다고 설명했다. 탈무드는 이를 “모든 유대인은 서로에 대해 책임이 있다”고 표현한다. 또 탈무드는 가족이나 도시, 온 세상을 향해 바로잡을 말을 할 수 있는데도 하지 않는 사람은 그 결과에 책임이 있다고 가르친다.</p><p>필자는 영국 랍비장을 지낸 조너선 색스 랍비의 말로 이 가르침을 요약했다. “당신이 내게 동의할 필요는 없지만, 나를 아껴 주어야 한다”는 것이다. 모두가 똑같이 생각하거나 똑같이 살 필요는 없지만, 같은 배에 탄 이들을 돌보는 일은 중요하다는 뜻이다.</p><p>필자의 결론은 새해를 맞는 이들에게 나 자신만이 아니라 곁에 있는 사람을 보라는 것이다. 공동체 안에서 서로를 돌보는 일을 귀하게 여기는 한국 교회에도, 개인의 신앙이 공동체의 책임과 분리될 수 없다는 이 가르침은 다시 새길 만한 메시지다.</p>', '통곡의 벽 랍비는 칼럼에서 개인의 성공에 몰두하는 시대에 ‘서로에 대한 책임’이라는 유대 전통의 가르침을 되새겼다.', '/sites/israeltoday/covers/shema-torah-1.svg', '2026-09-04T11:52:38+00:00'::timestamptz, array['파라샤', '니짜빔', '공동체', '상호 책임', '쉐마']::text[]),
  ('shema-family', '통곡의 벽 랍비 ‘사랑은 결혼 전에 완성하는 것이 아니다’', '<p>@@BYLINE@@&nbsp;통곡의 벽과 성지 담당 랍비인 슈무엘 라비노비츠는 예루살렘포스트에 실린 칼럼에서 신명기의 토라 본문 ‘키 테체’를 바탕으로 결혼과 가정의 의미를 짚었다. 필자는 사람에게 생계와 인정, 머물 집 같은 기본적 필요 외에도 안전하고 안정되며 익숙한 자리, 곧 소속감과 연속성을 주는 자리가 필요하다며 그것이 바로 배우자와 자녀로 이뤄진 가정이라고 말했다.</p><p>필자는 이 필요가 창조 때부터 기록돼 있다고 설명했다. 창세기 2장 18절은 아담이 창조된 직후 사람이 혼자 사는 것이 좋지 않으니 그를 위해 돕는 배필을 짓겠다는 하나님의 말씀을 전한다. 많은 이들이 자신을 완성해 주는 짝을 만나 가정을 이루지만, 한때 상대 없이는 삶을 상상할 수 없던 부부가 시간이 지나며 서로에게 낯선 사람이 되기도 한다는 것이 필자의 문제의식이다.</p><p>이번 주 본문인 신명기 24장 1절은 이혼 증서를 써서 아내를 내보내는 경우를 다룬다. 필자는 자신이 직접 고른 아내가 어떻게 갑자기 눈에 차지 않게 될 수 있느냐고 묻는다. 유대 현인들은 “첫 아내와 이혼하는 사람을 위해서는 제단도 눈물을 흘린다”고 가르쳤다.</p><p>필자는 토라 주석가 말빔(랍비 메이르 라이부시)의 관점을 빌려 답을 찾는다. 오늘날 사람들은 결정하기 전에 모든 것을 미리 알고 싶어 하고, 그래서 결혼 전 오랜 시간 서로를 알아 가는 경우가 많다. 그러나 사랑을 결혼 전에 모두 쌓아 버리면 부부는 감정이 정점에 이른 상태로 결혼식에 이르고, 결혼 뒤에야 차이와 약점이 드러나면서 실망하기 쉽다는 것이다.</p><p>반대로 전통적인 유대 중매(쉬두힘)는 가정생활에 중요한 부분에서 두 사람이 잘 맞는지 살핀 뒤 함께 사랑을 쌓아 가는 방식이라고 필자는 소개했다. 그는 “목표는 결혼 전에 사랑을 다 쌓는 것이 아니라 결혼을 통해 사랑을 쌓기 시작하는 것”이라고 강조했다. 함께 겪는 경험과 넘어선 어려움, 친절과 헌신 하나하나가 관계에 새로운 층을 더하고, 그렇게 사랑은 해가 갈수록 깊어진다는 것이다.</p><p>필자는 남편과 아내의 관계가 사람과 창조주의 관계를 비추는 거울이기도 하다고 말했다. 신년을 앞두고 회개 기도(슬리홋)를 드리는 ‘자비의 날들’에 사람들은 ‘먼저 모든 것을 이해하고, 마음이 편해지고, 연결된 다음에야 헌신하겠다’는 태도로 하나님께 나아가기 쉽다. 그러나 유대의 길은 그 반대라는 것이다. 필자는 “먼저 우리는 연결된다”며 계명을 지키고 선한 일을 더하는 행동 속에서, 감정이 아직 완전하지 않더라도 관계가 깊어진다고 썼다.</p><p>결혼을 감정의 정점이 아니라 사랑을 함께 키워 가는 출발점으로 보는 이 관점은, 언약 위에 세워지는 그리스도인 가정에도 의미 있는 질문을 던진다. 신앙 역시 모든 것을 이해한 뒤가 아니라 순종하며 걷는 가운데 깊어진다는 필자의 통찰은 결혼을 준비하는 청년과 오래 함께 걸어온 부부 모두가 곱씹어 볼 만하다.</p>', '슈무엘 라비노비츠 랍비는 토라 본문 ‘키 테체’ 칼럼에서 결혼의 비밀을 ‘먼저 연결되고, 그 안에서 사랑을 키워 가는 것’이라고 풀이했다.', '/sites/israeltoday/covers/shema-family-2.svg', '2026-08-21T11:58:26+00:00'::timestamptz, array['결혼', '가정', '파라샤', '키 테체', '쉐마']::text[]),
  ('shema-family', '위워크 창업자 애덤 뉴먼 ‘매주 25시간 안식일이 나를 돌아보게 했다’', '<p>@@BYLINE@@&nbsp;공유 오피스 기업 위워크(WeWork)의 공동 창업자 애덤 뉴먼이 안식일(샤바트)을 지키며 자신을 더 잘 이해하게 되고 관계도 깊어졌다고 말했다. 예루살렘포스트에 따르면 뉴먼은 스티븐 바틀렛이 진행하는 팟캐스트 ‘다이어리 오브 어 CEO’ 인터뷰에서 자신을 알아 가는 데 가장 효과적이었던 습관이 무엇이냐는 질문에 유대인의 안식일을 꼽았다.</p><p>뉴먼은 약 10년 전부터 안식일을 지키기 시작했다며, 금요일이면 25시간 동안 기술과 단절하고 가족, 친구들과 시간을 보내며 자신보다 큰 무언가에 참여한다고 설명했다. 안식일은 금요일 해 지기 전에 시작해 토요일 밤이 된 뒤 끝나며, 전통적으로 이를 지키는 유대인들은 이 시간에 일과 전자기기 사용을 삼간다. 그는 “그 단절이 사실은 누구도 이해하는 것보다 훨씬 많은 연결을 만들어 낸다”고 말했다.</p><p>뉴먼은 청취자들에게 24시간 동안 휴대전화 없이 지내 보라고 권했다. 그는 처음 두 시간 동안 휴대전화가 있는 줄 알고 주머니로 손이 가는 횟수를 보면 자신이 얼마나 중독돼 있는지 알게 될 것이라며 이를 ‘실제 중독’이라고 표현했다. 친구들과의 저녁 식사나 야외 활동처럼 미리 계획을 세워 두면, 하루를 마칠 무렵 더 나은 기분과 함께 누구와 함께해야 할지, 다음에 무엇을 해야 할지에 대한 좋은 생각이 떠오를 것이라고 했다.</p><p>뉴먼은 진행자 바틀렛에게도 직접 실천해 보라고 권했다. 바틀렛은 약혼자가 여러 번 휴대전화를 내려놓으라고 했다며 그런 생각만으로도 불편하다고 털어놓았지만, 결국 화면 없는 하루를 시도해 보고 결과를 알려 주겠다고 약속했다. 조건을 정하면서 뉴먼은 이 도전이 기술에 초점을 맞춘 것이라며 운전이나 종이에 아이디어를 적는 일은 괜찮다고 했다. 그는 “안식일을 지키라는 게 아니다”라고 덧붙였다.</p><p>뉴먼은 인터뷰 앞부분에서 아내 레베카가 교제 초기에 자신을 영적인 삶으로 이끌었다고 말했다. 레베카는 물질적 성공에 집중하던 그에게 도전을 던지며 참된 만족을 찾도록 격려했고, 그 탐색은 유대 신비주의 전통인 카발라에서 시작됐다고 한다. 아내와 여섯 자녀와 보내는 매주의 시간에 대해 그는 “우리가 함께하는 그 24시간은 정말 놀라웠다”고 말했다.</p><p>성공 신화의 상징처럼 여겨지던 기업가가 꼽은 ‘가장 효과적인 습관’이 매주 하루 멈추는 일이었다는 점은 눈길을 끈다. 스마트폰이 식탁과 잠자리까지 들어온 한국 가정에서도, 주일 하루만큼은 화면을 내려놓고 가족과 이웃, 그리고 하나님께 마음을 돌리는 ‘거룩한 멈춤’을 다시 생각해 볼 만하다.</p>', '10년째 안식일을 지켜 온 뉴먼은 팟캐스트 인터뷰에서 기술과의 단절이 오히려 더 깊은 연결을 만든다며 진행자에게 ‘화면 없는 하루’를 권했다.', '/sites/israeltoday/covers/shema-family-3.svg', '2026-09-29T22:18:12+00:00'::timestamptz, array['안식일', '디지털 디톡스', '가정', '애덤 뉴먼', '쉐마']::text[]),
  ('shema-nextgen', '나무 그늘 아래 교실부터 칠판 앞 수학까지…이스라엘 옛 교실 사진', '<p>@@BYLINE@@&nbsp;이스라엘 유대민족기금(KKL-JNF) 사진 아카이브가 9월 1일 시작된 이스라엘의 새 학년도를 맞아 지난 한 세기 이스라엘 교실의 모습을 보여주는 희귀 사진 다섯 장을 공개했다고 예루살렘포스트가 보도했다. 사진은 1925년부터 1963년까지에 걸쳐 있으며, 현대 기술이나 화이트보드는 물론 교실조차 없던 시절 아이들이 어떻게 배웠는지를 보여준다.</p><p>가장 오래된 사진은 1925년 8월 모샤브(협동농장 마을) 크파르 하시딤에서 찍혔다. 이스라엘 건국보다 20년 가까이 앞선 때다. 제대로 된 교실이 없던 이곳에서 아이들은 나무 그늘 아래 모여 앉아 교사의 이야기에 귀를 기울이고 있다.</p><p>15년 뒤인 1940년 사진은 예루살렘 슈피처 여학교 도서관에서 여러 소녀가 함께 책을 읽는 모습을 담았다. 1944년 키부츠 미슈마르 하에메크에서 찍은 사진에서는 어린 남학생들이 글씨 쓰기를 연습하는 것으로 보인다.</p><p>나머지 두 장은 1961년과 1963년 사진이다. 1961년 사진에서는 추르 하다사의 한 학생이 칠판 앞에서 수학 문제를 풀고 있고, 1963년 예루살렘에서 찍은 사진에는 아이들로 붐비는 교실에서 학생들이 신이 나서 편지를 뜯어 읽는 장면이 담겼다.</p><p>KKL-JNF의 에프랏 시나이는 “이 사진들은 우리가 잠시 과거의 교실로 들어가 아이들이 어떻게 배웠는지뿐 아니라 이곳에서 세워지던 사회가 어떤 모습이었는지를 보게 해 준다”고 말했다. 그는 칠판과 책, 책상, 그리고 나무 아래에서 열린 수업까지 사진 속 장면들이 “교육과 공동체, 그리고 땅에 대한 사랑 사이의 깊은 연결을 드러낸다”며 새 학년이 시작되는 때에 이 순간들을 보존하고 대중과 나눌 수 있어 영광이라고 밝혔다.</p><p>사진 속 아이들에게는 스마트폰도, 번듯한 교실도 없었다. 그러나 나무 그늘 아래 교사 곁에 모여 앉은 아이들의 모습은, 다음 세대를 가르치는 일의 중심에 결국 사람과 사람의 만남이 있다는 사실을 일깨운다. 나라가 세워지기도 전에 먼저 아이들을 가르치는 일부터 시작한 공동체의 모습은, 화려한 시설과 프로그램보다 말씀과 삶을 함께 나누는 교사와 부모의 자리를 고민하는 한국 교회와 가정에도 시사하는 바가 크다.</p><p>특히 이 사진들이 보여주듯 배움은 책상 앞에서만 이뤄지지 않았다. 도서관에서 함께 책을 읽고, 글씨를 반복해 익히고, 친구들 앞에서 문제를 풀며 아이들은 지식과 함께 공동체의 일원이 되는 법을 배웠다. 교회학교와 가정의 신앙 교육 역시 같은 공간에서 함께 배우고 함께 자라는 경험 속에서 뿌리를 내린다.</p>', 'KKL-JNF 사진 아카이브가 새 학년도를 맞아 1925년부터 1963년까지 이스라엘 교실 풍경을 담은 희귀 사진 다섯 장을 공개했다.', '/sites/israeltoday/covers/shema-nextgen-1.svg', '2026-09-01T07:34:21+00:00'::timestamptz, array['다음 세대', '교육', 'KKL-JNF', '기록사진', '이스라엘 역사']::text[]),
  ('shema-column', '‘배관공 야니브’와 심하트 토라…‘끝은 곧 다음 책임의 시작’', '<p>@@BYLINE@@&nbsp;미국 유대계 매체 JNS에 실린 칼럼은 한 배관공의 이야기로 시작한다. 직업이 배관공인 야니브는 납치된 비행기의 조종석에 앉게 됐다. 그는 그런 상황을 준비한 사람이 아니었고, 승객 174명의 생명을 책임지게 되리라고는 예상하지도 못했다. 그러나 상황은 그에게 즉시 행동할 것을 요구했다고 필자는 썼다.</p><p>필자에 따르면 기내에 있던 비번 조종사 두 명 가운데 한 명은 너무 큰 충격을 받아 곧바로 조종간을 잡지 못했다. 필자는 그 반응이 충분히 이해할 만하다고 했다. 충격은 사람을 마비시킬 수 있다. 하지만 비행기는 모두가 감정을 추스를 때까지 기다려 줄 수 없었다. 필자는 사람은 때로 상황이 즉각적인 행동을 요구할 때에야 자신이 무엇을 할 수 있는지 발견한다며, 야니브의 이야기가 유대인의 회복력과 책임, 생존에 관한 교훈이 된다고 주장했다.</p><p>필자가 연결한 것은 심하트 토라의 리듬이다. 심하트 토라에 유대인들은 한 해 동안 읽어 온 토라를 신명기 마지막 말씀으로 마친다. 큰일을 끝냈으니 잠시 쉬고 싶은 유혹이 들 법하지만, 유대인들은 끝에 머물지 않고 곧바로 창세기 첫머리로 돌아간다. 필자는 완성과 새로운 시작 사이에 긴 쉼이 없다며 “우리가 다시 시작하는 것은 이야기가 끝나지 않았기 때문이다”라고 썼다. 모든 마침에는 다음 책임의 시작이 담겨 있다는 것이다.</p><p>필자는 심하트 토라의 교훈이 감정을 무시하라는 것이 아니라고 강조했다. 충격도, 두려움도, 슬픔도 실제로 존재한다. 다만 감정이 언제나 행동을 결정하게 둘 수는 없으며, 필자는 “두려움보다 책임이 더 크게 부르는 순간이 있다”고 했다. 야니브에게는 ‘이건 불가능하다, 나는 배관공일 뿐이니 다른 사람이 해야 한다’며 물러설 여유가 없었다는 것이다.</p><p>필자는 메시지를 이렇게 정리했다. 느끼지 말라는 것이 아니라 “행동이 필요할 때 감정이 행동을 가로막지 않게 하라”는 것이다. 위기의 순간에는 무슨 일이 일어났는지 이해하고 회복할 시간을 갖고 싶지만, 다른 이들의 필요가 그 시간을 허락하지 않을 때가 있다. 늘 또 다른 계명과 도와야 할 사람, 감당해야 할 책임이 기다리고 있다는 것이다.</p><p>필자는 사람은 때로 그 힘을 써야 할 순간이 온 뒤에야 자신에게 힘이 있었음을 발견한다며, 그것이 유대 민족이 기적적으로 살아남아 온 비결이라고 주장했다. 두려움이 멈추라고 말할 때 유대 전통은 ‘계속 가라, 다시 시작하라’고 말한다는 것이다.</p><p>말씀을 다 읽은 날 곧바로 첫 장을 다시 펴는 심하트 토라의 전통은, 사역과 신앙의 한 계절을 마친 한국 교회와 성도들에게도 끝이 곧 새로운 부르심의 시작일 수 있음을 돌아보게 한다.</p>', 'JNS 칼럼은 납치된 여객기 조종석에 앉아 174명의 생명을 책임진 한 배관공의 이야기에서 토라를 마치자마자 다시 시작하는 심하트 토라의 교훈을 읽어냈다.', '/sites/israeltoday/covers/shema-column-2.svg', '2026-10-02T13:21:00+00:00'::timestamptz, array['심하트 토라', '책임', '회복력', '유대 전통', '쉐마']::text[])
) as v(slug, title, body, excerpt, thumb, published_at, tags)
join categories c on c.outlet_id = ctx.outlet_id and c.slug = v.slug
where not exists (select 1 from articles a where a.outlet_id = ctx.outlet_id and a.title = v.title);

-- 기자명 '관리자', 기자 이메일 비우기, 편집 메모 (칸이 있을 때만)
--   기자 이메일은 DB 규칙이 대표 이메일로 채우므로, 잠깐 그 규칙을 끄고 비운 뒤 다시 켠다
do $fix$
begin
  if exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'articles' and column_name = 'byline') then
    update articles a set byline = '관리자'
    from outlets o where a.outlet_id = o.id and o.name = 'Israel Today' and a.body like '<p>[%=관리자 기자]%' and a.byline is distinct from '관리자';
  end if;
  if exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'articles' and column_name = 'byline_email') then
    if exists (select 1 from pg_trigger where tgname = 'articles_byline_email') then
      alter table articles disable trigger articles_byline_email;
    end if;
    update articles a set byline_email = null
    from outlets o where a.outlet_id = o.id and o.name = 'Israel Today' and a.body like '<p>[%=관리자 기자]%' and a.byline_email is not null;
    if exists (select 1 from pg_trigger where tgname = 'articles_byline_email') then
      alter table articles enable trigger articles_byline_email;
    end if;
  end if;
  if exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'articles' and column_name = 'ai_notes') then
    update articles a set ai_notes = v.notes
    from outlets o, (values
  ('흉기 든 부기장 막아선 승객들…플라이두바이 174명 무사 귀환', '• 확인할 점: 출처마다 다른 내용이 있어 하나만 썼다: 고도 하강(와이넷 1만4천 피트 이상 / JPost 1만6,625 피트) → 와이넷 기준. 탑승 인원(와이넷 승객 174명 / JNS 승무원 8명 포함 182명) → 승객 174명. 기장 나이(38·39세)는 뺐다. 범인 제압 주체는 나중 보도(인도인 기장·승객) 기준.
